// 用語集（1）: 自動生成元 scratchpad/gloss/w1
window.GLOSSARY = (window.GLOSSARY || []).concat([
  {term:"1848年革命",yomi:"せんはっぴゃくよんじゅうはちねんかくめい",def:"1848年にフランスの二月革命をきっかけにヨーロッパ各地へ広がった革命の総称。ウィーンやベルリンで三月革命がおこり、メッテルニヒが失脚してウィーン体制は崩壊した。自由主義・民族主義の高まりを示し「諸国民の春」とよばれる。",year:1848,end:1849,region:"europe",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["ウィーン体制","二月革命","三月革命","諸国民の春"]},
  {term:"3B政策",yomi:"さんビーせいさく",def:"ドイツのヴィルヘルム2世が進めた中東進出政策。ベルリン・ビザンティウム（イスタンブル）・バグダードを鉄道で結ぶ構想で、イギリスの3C政策と対立し、第一次世界大戦前の英独対立の一因となった。",year:1899,region:"europe",cat:"制度・政策",rank:3,course:["sogo","tankyu"],related:["3C政策","ヴィルヘルム2世","バグダード鉄道"]},
  {term:"4王国分立",yomi:"よんおうこくぶんりつ",def:"アッシリア滅亡後、オリエントがエジプト・リディア・メディア・新バビロニア（カルデア）の4王国に分かれた状態。前6世紀にアケメネス朝ペルシアがこれらを征服し、オリエントを再統一した。",year:-612,end:-550,region:"west",cat:"事件・戦争",rank:2,course:["tankyu"],related:["アッシリア","リディア","メディア","新バビロニア"]},
  {term:"ASEAN",yomi:"アセアン",def:"東南アジア諸国連合。1967年、インドネシア・マレーシア・フィリピン・シンガポール・タイの5か国で結成された地域協力機構。当初は反共的性格をもったが、冷戦後はベトナムなどが加わり10か国に拡大し、経済協力を進めている。",year:1967,region:"sea",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["東南アジア条約機構","ベトナム戦争","アジアNIES"]},
  {term:"CIS",yomi:"シーアイエス",def:"独立国家共同体。1991年のソ連解体の際、ロシア・ウクライナ・ベラルーシなど旧ソ連構成共和国の多くが結成したゆるやかな国家連合。バルト3国は参加しなかった。",year:1991,region:"europe",cat:"組織・運動",rank:2,course:["sogo","tankyu"],related:["ソ連の解体","エリツィン","ゴルバチョフ"]},
  {term:"EEC",yomi:"イーイーシー",def:"ヨーロッパ経済共同体。1957年のローマ条約にもとづき1958年に発足した。フランス・西ドイツ・イタリア・ベネルクス3国の6か国で関税同盟と共同市場をめざし、のちEC、さらにEUへと発展した。",year:1958,region:"europe",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["EU","ローマ条約","ヨーロッパ石炭鉄鋼共同体"]},
  {term:"EU",yomi:"イーユー",def:"ヨーロッパ連合。1992年のマーストリヒト条約にもとづき1993年にECを母体に発足した。共通通貨ユーロの導入や共通外交・安全保障政策をめざし、冷戦後は東欧諸国も加盟して拡大した。",year:1993,region:"europe",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["EEC","マーストリヒト条約","ユーロ","EU離脱"]},
  {term:"EU加盟",yomi:"イーユーかめい",def:"ヨーロッパ連合への加盟。冷戦終結後、旧社会主義圏の東欧諸国やバルト3国が市場経済化と民主化を進め、2004年に一斉にEUに加盟した。EUは東方へ大きく拡大した。",year:2004,region:"europe",cat:"事件・戦争",rank:1,course:["sogo","tankyu"],related:["EU","バルト3国","冷戦の終結"]},
  {term:"EU本部",yomi:"イーユーほんぶ",def:"ベルギーの首都ブリュッセルに置かれたEUの主要機関（ヨーロッパ委員会など）の所在地。ブリュッセルは「ヨーロッパの首都」ともよばれ、NATOの本部も置かれている。",year:1993,region:"europe",cat:"地名・地域",rank:1,course:["sogo","tankyu"],related:["EU","ブリュッセル"]},
  {term:"EU離脱",yomi:"イーユーりだつ",def:"イギリスのEUからの離脱（ブレグジット）。2016年の国民投票で離脱派が多数を占め、2020年に正式に離脱した。移民問題や主権回復への不満が背景にあり、ヨーロッパ統合の転機となった。",year:2020,region:"europe",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["EU","イギリス","グローバル化"]},
  {term:"GATT",yomi:"ガット",def:"関税と貿易に関する一般協定。1947年に調印され、関税引き下げと自由貿易の拡大をめざした。IMFとともに第二次世界大戦後の国際経済体制を支え、1995年にWTOへ発展的に解消した。",year:1947,end:1995,region:"europe",cat:"条約・宣言",rank:3,course:["sogo","tankyu"],related:["IMF","WTO","ブレトン=ウッズ体制"]},
  {term:"GHQ",yomi:"ジーエイチキュー",def:"連合国軍最高司令官総司令部。第二次世界大戦後の日本占領のため設置され、マッカーサーが最高司令官となった。日本政府に指令を出す間接統治の方式で、財閥解体・農地改革・日本国憲法制定などの民主化を進めた。",year:1945,end:1952,region:"east",cat:"組織・運動",rank:3,course:["sogo"],related:["マッカーサー","サンフランシスコ平和条約","農地改革"]},
  {term:"IMF",yomi:"アイエムエフ",def:"国際通貨基金。1944年のブレトン=ウッズ会議で設立が決まり、1945年に発足した。為替の安定と国際収支の不均衡を是正するための短期融資を行い、ドルを基軸とする戦後の国際通貨体制を支えた。",year:1945,region:"america",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["GATT","ブレトン=ウッズ体制","世界銀行"]},
  {term:"INF全廃条約",yomi:"アイエヌエフぜんぱいじょうやく",def:"中距離核戦力全廃条約。1987年にアメリカのレーガン大統領とソ連のゴルバチョフ書記長が調印した。特定の種類の核兵器をはじめて全廃する内容で、冷戦終結への流れをつくった。",year:1987,region:"europe",cat:"条約・宣言",rank:2,course:["sogo","tankyu"],related:["ゴルバチョフ","レーガン","冷戦の終結"]},
  {term:"NATO",yomi:"ナトー",def:"北大西洋条約機構。1949年にアメリカ・カナダと西欧諸国が結成した集団防衛機構で、ソ連に対抗する西側陣営の軍事同盟である。1955年に西ドイツが加盟し、冷戦後は東欧諸国にも拡大した。",year:1949,region:"europe",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["ワルシャワ条約機構","冷戦","西ドイツ"]},
  {term:"NATO空爆",yomi:"ナトーくうばく",def:"1999年、コソヴォ紛争でアルバニア系住民への迫害を止めることを理由に、NATOが国連安保理の決議を経ずにセルビア（新ユーゴスラヴィア）を空爆した事件。人道的介入の是非が議論された。",year:1999,region:"europe",cat:"事件・戦争",rank:1,course:["sogo","tankyu"],related:["NATO","コソヴォ紛争","ユーゴスラヴィア"]},
  {term:"NATO脱退",yomi:"ナトーだったい",def:"1966年、フランスのド=ゴール大統領がアメリカ主導に反発し、NATOの軍事機構から脱退したこと。独自の核武装とともに自主外交の象徴となった。フランスは2009年に復帰した。",year:1966,region:"europe",cat:"事件・戦争",rank:1,course:["sogo","tankyu"],related:["ド=ゴール","NATO","第五共和政"]},
  {term:"NGO",yomi:"エヌジーオー",def:"非政府組織。政府から独立して、人権・環境・開発・医療などの分野で国境をこえて活動する民間の団体。アムネスティ=インターナショナルや国境なき医師団などがあり、グローバル化のなかで役割を高めている。",region:"oceania",cat:"組織・運動",rank:1,course:["sogo","tankyu"],related:["国際連合","SDGs","グローバル化"]},
  {term:"NIES",yomi:"ニーズ",def:"新興工業経済地域。1970年代以降、輸出志向型の工業化で急速に成長した国・地域をさす。韓国・台湾・香港・シンガポールのアジアNIESのほか、ラテンアメリカ諸国なども含まれた。",year:1970,end:1990,region:"east",cat:"経済・社会",rank:2,course:["sogo","tankyu"],related:["アジアNIES","石油危機","グローバル化"]},
  {term:"OPEC",yomi:"オペック",def:"石油輸出国機構。1960年、産油国が国際石油資本に対抗して結成した。1973年の第4次中東戦争の際、アラブ産油国の石油戦略と連動して原油価格を大幅に引き上げ、石油危機をひきおこした。",year:1960,region:"west",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["石油危機","サウジアラビア","第4次中東戦争"]},
  {term:"PKO",yomi:"ピーケーオー",def:"国連平和維持活動。紛争地域で停戦監視や選挙監視、兵力引き離しなどを行い、紛争の再発を防ぐ国際連合の活動である。冷戦後に急増し、南スーダンなどにも派遣された。",region:"oceania",cat:"制度・政策",rank:2,course:["sogo","tankyu"],related:["国際連合","PKO協力法","南スーダン"]},
  {term:"PKO協力法",yomi:"ピーケーオーきょうりょくほう",def:"1992年に日本で成立した国連平和維持活動協力法。湾岸戦争で国際貢献のあり方が問われたことを背景とし、自衛隊がカンボジアなどのPKOに派遣されるようになった。",year:1992,region:"east",cat:"制度・政策",rank:2,course:["sogo"],related:["PKO","湾岸戦争","国際連合"]},
  {term:"PLO",yomi:"ピーエルオー",def:"パレスチナ解放機構。1964年に結成されたパレスチナ人の組織で、アラファトの指導のもとイスラエルと武力闘争を展開した。1993年のオスロ合意でイスラエルと相互承認し、パレスチナ暫定自治が始まった。",year:1964,region:"west",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["アラファト","オスロ合意","パレスチナ問題"]},
  {term:"SDGs",yomi:"エスディージーズ",def:"持続可能な開発目標。2015年の国連サミットで採択された、2030年までに達成をめざす17の国際目標である。貧困・飢餓の撲滅、気候変動への対策、ジェンダー平等など、地球規模の課題を包括的にかかげる。",year:2015,end:2030,region:"oceania",cat:"制度・政策",rank:2,course:["sogo","tankyu"],related:["国際連合","グローバル化","NGO"]},
  {term:"SWAPO",yomi:"スワポ",def:"南西アフリカ人民機構。南アフリカの支配下にあった南西アフリカ（ナミビア）の独立をめざした解放組織。武装闘争を続け、1990年のナミビア独立後は与党となった。",year:1960,region:"africa",cat:"組織・運動",rank:1,course:["tankyu"],related:["ナミビア","アパルトヘイト"]},
  {term:"TVA",yomi:"ティーヴィーエー",def:"テネシー川流域開発公社。1933年、フランクリン=ローズヴェルトのニューディールの一環として設立された。ダム建設などの公共事業によって雇用を創出し、地域開発と失業者救済をはかった。",year:1933,region:"america",cat:"制度・政策",rank:2,course:["sogo","tankyu"],related:["ニューディール","フランクリン=ローズヴェルト","世界恐慌"]},
  {term:"UNHCR",yomi:"ユーエヌエイチシーアール",def:"国連難民高等弁務官事務所。1950年に設立された国際連合の機関で、難民の保護と支援、帰還や定住の援助を行う。1990年代には緒方貞子が高等弁務官をつとめた。",year:1950,region:"oceania",cat:"組織・運動",rank:2,course:["sogo","tankyu"],related:["国際連合","難民","NGO"]},
  {term:"WTO",yomi:"ダブリューティーオー",def:"世界貿易機関。1995年、GATTを発展させて発足した国際機関。モノだけでなくサービスや知的財産権もあつかい、貿易紛争の処理機能を強化した。2001年には中国も加盟した。",year:1995,region:"oceania",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["GATT","グローバル化","IMF"]},
  {term:"「モナ=リザ」",yomi:"モナ=リザ",def:"レオナルド=ダ=ヴィンチが16世紀初めに描いた女性の肖像画。遠近法や輪郭をぼかすスフマート技法を用い、ルネサンス絵画の代表作とされる。現在はパリのルーヴル美術館に所蔵されている。",year:1503,end:1519,region:"europe",cat:"文化・学問",rank:2,course:["tankyu"],related:["レオナルド=ダ=ヴィンチ","ルネサンス","「最後の晩餐」"]},
  {term:"「最後の晩餐」",yomi:"さいごのばんさん",def:"レオナルド=ダ=ヴィンチがミラノの修道院の食堂の壁に描いた壁画。イエスと12使徒の最後の食事の場面を、遠近法を用いた緊張感ある構図で表現した、ルネサンス美術の傑作である。",year:1495,end:1498,region:"europe",cat:"文化・学問",rank:2,course:["tankyu"],related:["レオナルド=ダ=ヴィンチ","ルネサンス","「モナ=リザ」"]},
  {term:"「鎖国」",yomi:"さこく",def:"江戸幕府による対外統制の体制。キリスト教の禁止と貿易の統制を目的に、1639年ポルトガル船の来航を禁じ、長崎でのオランダ・中国との貿易などに限った。実際には朝鮮・琉球・アイヌとの交流も続いていた。",year:1639,end:1854,region:"east",cat:"制度・政策",rank:3,course:["sogo","tankyu"],related:["日米和親条約","オランダ","キリスト教の伝来"]},
  {term:"『エミール』",yomi:"エミール",def:"フランスの思想家ルソーが1762年に著した教育論。子どもの自然な成長を重んじる教育を説き、近代教育思想に大きな影響を与えた。同じ年に『社会契約論』も刊行された。",year:1762,region:"europe",cat:"文化・学問",rank:1,course:["tankyu"],related:["ルソー","『社会契約論』","啓蒙思想"]},
  {term:"『キリスト教綱要』",yomi:"キリストきょうこうよう",def:"カルヴァンが1536年に著した宗教改革の神学書。神の絶対的主権と予定説を体系的に説き、カルヴァン派（改革派）の教義の基礎となった。",year:1536,region:"europe",cat:"文化・学問",rank:2,course:["tankyu"],related:["カルヴァン","予定説","宗教改革"]},
  {term:"『プリンキピア』",yomi:"プリンキピア",def:"ニュートンが1687年に刊行した『自然哲学の数学的原理』の通称。万有引力の法則と運動の法則を数学的に示し、近代物理学の基礎を築いた。17世紀の科学革命の到達点とされる。",year:1687,region:"europe",cat:"文化・学問",rank:2,course:["tankyu"],related:["ニュートン","科学革命","ガリレイ"]},
  {term:"『ローマ法大全』",yomi:"ローマほうたいぜん",def:"ビザンツ皇帝ユスティニアヌスが法学者トリボニアヌスらに命じて編纂させたローマ法の集大成。のちのヨーロッパ諸国の法律に大きな影響を与えた。",year:534,region:"europe",cat:"文化・学問",rank:3,course:["tankyu"],related:["ユスティニアヌス大帝","ビザンツ帝国","ローマ法"]},
  {term:"『世界の記述（東方見聞録）』",yomi:"せかいのきじゅつ（とうほうけんぶんろく）",def:"ヴェネツィア出身のマルコ=ポーロが、元のフビライに仕えた体験などを口述し記録させた旅行記。日本を「ジパング」として紹介し、ヨーロッパ人のアジアへの関心を高めた。",year:1299,region:"europe",cat:"文化・学問",rank:3,course:["tankyu"],related:["マルコ=ポーロ","元","ジパング"]},
  {term:"『人間不平等起源論』",yomi:"にんげんふびょうどうきげんろん",def:"ルソーが1755年に著した書物。自然状態では平等であった人間が、私有財産の成立によって不平等になったと論じ、文明社会を批判した。",year:1755,region:"europe",cat:"文化・学問",rank:1,course:["tankyu"],related:["ルソー","『社会契約論』","啓蒙思想"]},
  {term:"『共産党宣言』",yomi:"きょうさんとうせんげん",def:"マルクスとエンゲルスが1848年に発表した文書。歴史を階級闘争の歴史ととらえ、プロレタリアートによる革命を説いて「万国のプロレタリア、団結せよ」と結んだ。社会主義運動に大きな影響を与えた。",year:1848,region:"europe",cat:"文化・学問",rank:3,course:["sogo","tankyu"],related:["マルクス","エンゲルス","『資本論』"]},
  {term:"『医学典範』",yomi:"いがくてんぱん",def:"イブン=シーナー（アヴィケンナ）が著した医学書。ギリシア・イスラームの医学を集大成したもので、ラテン語に翻訳され、ヨーロッパでも長く医学の教科書として用いられた。",year:1020,region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["イブン=シーナー","イスラーム科学","アヴィケンナ"]},
  {term:"『千夜一夜物語』",yomi:"せんやいちやものがたり",def:"インド・イラン・アラビアなどの説話をもとに、アッバース朝期以降にアラビア語でまとめられた説話集。『アラビアン=ナイト』ともいい、ハールーン=アッラシードも登場する。",region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["ハールーン=アッラシード","アッバース朝","イスラーム"]},
  {term:"『四庫全書』",yomi:"しこぜんしょ",def:"清の乾隆帝の命で編纂された叢書。古今の書物を経・史・子・集の4部に分類して収めた。学問を奨励する一方、清朝に不都合な書物は禁書とされ、思想統制の面ももっていた。",year:1782,region:"east",cat:"文化・学問",rank:2,course:["tankyu"],related:["乾隆帝","清","『康熙字典』"]},
  {term:"『国家』",yomi:"こっか",def:"ギリシアの哲学者プラトンの主著の一つ。イデア論にもとづき、哲学者が統治する理想国家（哲人政治）を説いた。",region:"europe",cat:"文化・学問",rank:1,course:["tankyu"],related:["プラトン","イデア論","アリストテレス"]},
  {term:"『大唐西域記』",yomi:"だいとうさいいきき",def:"唐の僧玄奘が、インドへの求法の旅の見聞をまとめた地誌。ヴァルダナ朝のハルシャ王の時代のインドや、中央アジア諸国の様子を伝える貴重な史料である。",year:646,region:"east",cat:"文化・学問",rank:2,course:["tankyu"],related:["玄奘","唐","ヴァルダナ朝"]},
  {term:"『大旅行記（三大陸周遊記）』",yomi:"だいりょこうき（さんたいりくしゅうゆうき）",def:"モロッコ出身のイブン=バットゥータが、アジア・アフリカ・ヨーロッパの3大陸をめぐった旅の記録。14世紀のイスラーム世界の広がりや、元・マリ王国などの様子を伝える。",year:1355,region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["イブン=バットゥータ","イスラーム・ネットワーク","マリ王国"]},
  {term:"『天文対話』",yomi:"てんもんたいわ",def:"ガリレイが1632年に刊行した書物。天動説と地動説を対話形式で比べ、地動説を支持したため、ガリレイはローマ教会の宗教裁判にかけられた。",year:1632,region:"europe",cat:"文化・学問",rank:1,course:["tankyu"],related:["ガリレイ","地動説","コペルニクス"]},
  {term:"『学問のすゝめ』",yomi:"がくもんのすすめ",def:"福沢諭吉が1872年から刊行した啓蒙書。「天は人の上に人を造らず」と人間の平等を説き、学問による個人の独立を訴えた。明治初期にベストセラーとなった。",year:1872,region:"east",cat:"文化・学問",rank:2,course:["sogo"],related:["福沢諭吉","文明開化","『西洋事情』"]},
  {term:"『康熙字典』",yomi:"こうきじてん",def:"清の康熙帝の命で編纂された漢字字典。約4万7千字を部首と画数で分類したもので、のちの漢字字典の基準となった。",year:1716,region:"east",cat:"文化・学問",rank:1,course:["tankyu"],related:["康熙帝","清","『四庫全書』"]},
  {term:"『政治学』",yomi:"せいじがく",def:"アリストテレスの著作。「人間はポリス的動物である」として、ギリシアのポリスの政治体制を比較・分類し、国家のあり方を論じた。",region:"europe",cat:"文化・学問",rank:1,course:["tankyu"],related:["アリストテレス","プラトン","ポリス"]},
  {term:"『文明論之概略』",yomi:"ぶんめいろんのがいりゃく",def:"福沢諭吉が1875年に著した書物。西洋文明を手本として日本の文明化を進め、国の独立を保つべきことを説いた。",year:1875,region:"east",cat:"文化・学問",rank:1,course:["sogo"],related:["福沢諭吉","『学問のすゝめ』","文明開化"]},
  {term:"『新約聖書』",yomi:"しんやくせいしょ",def:"イエスの言行や使徒の活動を記したキリスト教の聖典。福音書やパウロの書簡などからなり、ギリシア語のコイネーで書かれた。ユダヤ教以来の『旧約聖書』とあわせて聖書とされる。",region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["イエス","キリスト教","パウロ"]},
  {term:"『永楽大典』",yomi:"えいらくたいてん",def:"明の永楽帝の命で編纂された類書（百科事典）。古今の書物から事項ごとに文章を集めた大規模なもので、多くが失われたが、現在まで一部が伝わる。",year:1408,region:"east",cat:"文化・学問",rank:2,course:["tankyu"],related:["永楽帝","明","『四書大全』"]},
  {term:"『海国図志』",yomi:"かいこくずし",def:"清の魏源が林則徐の集めた資料をもとに著した世界地理書。アヘン戦争後、西洋の事情を紹介し、その技術を学ぶ必要を説いた。幕末の日本でも読まれた。",year:1842,region:"east",cat:"文化・学問",rank:1,course:["tankyu"],related:["魏源","林則徐","アヘン戦争"]},
  {term:"『社会契約論』",yomi:"しゃかいけいやくろん",def:"ルソーが1762年に著した政治思想書。人民の一般意志にもとづく人民主権を説き、直接民主政を理想とした。フランス革命、とくにジャコバン派に大きな影響を与えた。",year:1762,region:"europe",cat:"文化・学問",rank:3,course:["sogo","tankyu"],related:["ルソー","人民主権","フランス革命"]},
  {term:"『統治二論』",yomi:"とうちにろん",def:"ロックが1690年に刊行した政治論。社会契約説の立場から自然権の保障を政府の目的とし、政府が権利を侵した場合の抵抗権を認めた。名誉革命を正当化し、アメリカ独立宣言に影響を与えた。",year:1690,region:"europe",cat:"文化・学問",rank:2,course:["sogo","tankyu"],related:["ロック","社会契約説","名誉革命","アメリカ独立宣言"]},
  {term:"『西洋事情』",yomi:"せいようじじょう",def:"福沢諭吉が幕末の欧米視察をもとに著した書物。欧米の政治・経済・社会制度をわかりやすく紹介し、幕末・明治初期の人々に広く読まれた。",year:1866,region:"east",cat:"文化・学問",rank:1,course:["sogo"],related:["福沢諭吉","『学問のすゝめ』","文明開化"]},
  {term:"『論語』",yomi:"ろんご",def:"孔子とその弟子たちの言行を記録した書物。仁や礼を重んじる孔子の教えを伝え、のちに四書の一つとして儒教の基本経典となった。",region:"east",cat:"文化・学問",rank:2,course:["tankyu"],related:["孔子","儒家","儒教"]},
  {term:"『貞観政要』",yomi:"じょうがんせいよう",def:"唐の太宗と臣下との政治問答をまとめた書物。名君とされた太宗の政治（貞観の治）を伝え、のちの中国や日本で帝王学の書として読まれた。",region:"east",cat:"文化・学問",rank:1,course:["tankyu"],related:["太宗（唐）","唐","貞観の治"]},
  {term:"『資本論』",yomi:"しほんろん",def:"マルクスの主著。1867年に第1巻が刊行され、資本主義経済のしくみを分析して、その矛盾から社会主義への移行が必然であると論じた。",year:1867,region:"europe",cat:"文化・学問",rank:2,course:["sogo","tankyu"],related:["マルクス","『共産党宣言』","社会主義"]},
  {term:"くさび形文字",yomi:"くさびがたもじ",def:"シュメール人が考案した文字。粘土板に葦のペンで刻んだため、くさび形になった。アッカド語など他の言語にも用いられ、オリエント各地で広く使われた。",year:-3000,region:"west",cat:"文化・学問",rank:3,course:["tankyu"],related:["シュメール人","粘土板","アッカド語"]},
  {term:"すず",yomi:"すず",def:"金属の一種で、マレー半島はすずの世界的産地であった。19世紀後半以降、イギリス支配下のマレー半島で中国系労働者によって大規模に採掘され、ゴムとともに主要な輸出品となった。",region:"sea",cat:"経済・社会",rank:1,course:["tankyu"],related:["ゴム","マレー連合州","イギリス"]},
  {term:"アイバク",yomi:"アイバク",def:"ゴール朝のマムルーク（奴隷軍人）出身の武将。1206年に北インドのデリーで奴隷王朝を開き、デリー=スルタン朝の最初の君主となった。",year:1206,end:1210,region:"south",cat:"人物",rank:2,course:["tankyu"],related:["奴隷王朝","デリー=スルタン朝","クトゥブ=ミナール"]},
  {term:"アイユーブ朝",yomi:"アイユーブちょう",def:"クルド人のサラーフ=アッディーンがエジプトに建てた王朝。ファーティマ朝を倒してスンナ派を復興し、1187年に十字軍からイェルサレムを奪回した。のちマムルーク朝にかわられた。",year:1169,end:1250,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["サラーフ=アッディーン","十字軍","マムルーク朝"]},
  {term:"アイルランド自治法",yomi:"アイルランドじちほう",def:"イギリス議会で成立したアイルランドの自治を認める法律。グラッドストンが19世紀末から法案を提出したが否決され、1914年に成立したものの第一次世界大戦のため実施は延期された。",year:1914,region:"europe",cat:"制度・政策",rank:2,course:["sogo","tankyu"],related:["グラッドストン","アイルランド問題","シン=フェイン党"]},
  {term:"アイルランド自由国",yomi:"アイルランドじゆうこく",def:"1922年、北アイルランドを除いて成立したイギリスの自治領。1937年に新憲法を定めて国名をエールとし、1949年にイギリス連邦を離脱してアイルランド共和国となった。",year:1922,end:1937,region:"europe",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["シン=フェイン党","アイルランド自治法","ウェストミンスター憲章"]},
  {term:"アイン=ジャールートの戦い",yomi:"アイン=ジャールートのたたかい",def:"1260年、パレスチナでマムルーク朝がモンゴル軍を破った戦い。のちのスルタン、バイバルスが活躍し、モンゴルの西方への進出を食い止めた。",year:1260,region:"west",cat:"事件・戦争",rank:2,course:["tankyu"],related:["マムルーク朝","バイバルス","イル=ハン国"]},
  {term:"アウクスブルクの和議",yomi:"アウクスブルクのわぎ",def:"1555年、神聖ローマ帝国でルター派を認めた取り決め。諸侯はカトリックとルター派のどちらかを選ぶことができたが、個人の信仰の自由やカルヴァン派は認められなかった。",year:1555,region:"europe",cat:"条約・宣言",rank:3,course:["tankyu"],related:["ルター","カール5世","宗教改革"]},
  {term:"アウグストゥス",yomi:"アウグストゥス",def:"ローマ初代皇帝オクタウィアヌスが、前27年に元老院から与えられた「尊厳者」の称号。彼は共和政の形式を残しつつ実権をにぎる元首政（プリンキパトゥス）を始め、「ローマの平和」の基礎を築いた。",year:-27,end:14,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["オクタウィアヌス","元首政","パクス=ロマーナ"]},
  {term:"アウスグライヒ（妥協）",yomi:"アウスグライヒ（だきょう）",def:"1867年、プロイセン=オーストリア戦争に敗れたオーストリアが、ハンガリーの自治を認めて結んだ妥協。これにより同君連合のオーストリア=ハンガリー帝国が成立した。",year:1867,region:"europe",cat:"制度・政策",rank:2,course:["tankyu"],related:["オーストリア=ハンガリー帝国","プロイセン=オーストリア戦争","マジャール人"]},
  {term:"アウステルリッツの戦い",yomi:"アウステルリッツのたたかい",def:"1805年、ナポレオンがオーストリア・ロシアの連合軍を破った戦い。3人の皇帝が参戦したため三帝会戦ともいう。翌年ライン同盟が結成され、神聖ローマ帝国は消滅した。",year:1805,region:"europe",cat:"事件・戦争",rank:2,course:["tankyu"],related:["ナポレオン","三帝会戦","ライン同盟"]},
  {term:"アウラングゼーブ",yomi:"アウラングゼーブ",def:"ムガル帝国第6代皇帝。最大版図を実現したが、厳格なスンナ派の立場からジズヤを復活させるなど非ムスリムを圧迫したため、ラージプートやマラーター、シク教徒の反発を招き、帝国の衰退をまねいた。",year:1658,end:1707,region:"south",cat:"人物",rank:3,course:["tankyu"],related:["ムガル帝国","ジズヤの復活","シク教徒","マラーター王国"]},
  {term:"アウン=サン",yomi:"アウン=サン",def:"ビルマ独立運動の指導者。タキン党で活動し、第二次世界大戦中は日本と協力したのち抗日に転じた。戦後イギリスと独立交渉を進めたが、独立直前の1947年に暗殺された。",year:1915,end:1947,region:"sea",cat:"人物",rank:2,course:["tankyu"],related:["ビルマ","アウン=サン=スー=チー","タキン党"]},
  {term:"アウン=サン=スー=チー",yomi:"アウン=サン=スー=チー",def:"ミャンマー（ビルマ）の民主化運動の指導者で、アウン=サンの娘。軍事政権のもとで長く軟禁され、1991年にノーベル平和賞を受けた。2016年から政権を担ったが、2021年の軍のクーデタで拘束された。",year:1988,region:"sea",cat:"人物",rank:2,course:["sogo","tankyu"],related:["アウン=サン","ミャンマー","軍事政権"]},
  {term:"アカデメイア",yomi:"アカデメイア",def:"プラトンがアテネ郊外に開いた学園。哲学や数学などを研究・教育し、アリストテレスも学んだ。529年にユスティニアヌス帝によって閉鎖された。",year:-387,region:"europe",cat:"文化・学問",rank:1,course:["tankyu"],related:["プラトン","アリストテレス","イデア論"]},
  {term:"アギナルド",yomi:"アギナルド",def:"フィリピン独立運動の指導者。スペインに対する革命を指導し、1899年にフィリピン共和国の大統領となったが、フィリピン=アメリカ戦争で敗れ、アメリカの支配を受けることになった。",year:1898,end:1901,region:"sea",cat:"人物",rank:2,course:["tankyu"],related:["フィリピン=アメリカ戦争","アメリカ=スペイン戦争","ホセ=リサール"]},
  {term:"アクスム王国",yomi:"アクスムおうこく",def:"紀元前後からエチオピア高原に栄えた王国。紅海交易で繁栄し、4世紀にメロエ王国を滅ぼした。同じころキリスト教を受け入れた。",region:"africa",cat:"国家・王朝",rank:2,course:["tankyu"],related:["クシュ王国","メロエ","キリスト教"]},
  {term:"アクティウムの海戦",yomi:"アクティウムのかいせん",def:"前31年、オクタウィアヌスがアントニウスとクレオパトラの連合軍を破った海戦。翌年プトレマイオス朝エジプトは滅び、ローマは地中海世界を統一した。",year:-31,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["オクタウィアヌス","アントニウス","クレオパトラ","プトレマイオス朝"]},
  {term:"アクバル",yomi:"アクバル",def:"ムガル帝国第3代皇帝。北インドを統一して中央集権体制を整え、官僚を位階で序列化するマンサブダール制をしいた。ジズヤを廃止してヒンドゥー教徒との融和をはかった。",year:1556,end:1605,region:"south",cat:"人物",rank:3,course:["tankyu"],related:["ムガル帝国","ジズヤの廃止","アウラングゼーブ","アグラ"]},
  {term:"アグラ",yomi:"アグラ",def:"北インドのヤムナー川沿いの都市。ムガル帝国のアクバルらが都を置き、シャー=ジャハーンが妃の墓廟タージ=マハルを建てた。",region:"south",cat:"地名・地域",rank:1,course:["tankyu"],related:["アクバル","タージ=マハル","ムガル帝国"]},
  {term:"アケメネス朝",yomi:"アケメネスちょう",def:"イラン人（ペルシア人）がたてた王朝。キュロス2世が建国し、ダレイオス1世のときエーゲ海北岸からインダス川に及ぶ大帝国となった。サトラップの配置や「王の道」を整えたが、アレクサンドロス大王に滅ぼされた。",year:-550,end:-330,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["キュロス2世","ダレイオス1世","サトラップ","アレクサンドロス大王"]},
  {term:"アシャンティ王国",yomi:"アシャンティおうこく",def:"17世紀末から現在のガーナにあたる地域に栄えた王国。金や奴隷の取引で繁栄したが、19世紀にイギリスと戦い、1902年に植民地（黄金海岸）に編入された。",year:1670,end:1902,region:"africa",cat:"国家・王朝",rank:1,course:["tankyu"],related:["黄金海岸","奴隷貿易","イギリス"]},
  {term:"アショーカ王",yomi:"アショーカおう",def:"マウリヤ朝の第3代の王。カリンガ征服の悲惨さから仏教に帰依し、ダルマ（法）にもとづく政治を行った。各地に詔勅を刻んだ石柱碑や磨崖碑を建て、仏典結集やセイロンへの布教も行ったとされる。",year:-268,end:-232,region:"south",cat:"人物",rank:3,course:["tankyu"],related:["マウリヤ朝","仏典結集","カリンガ"]},
  {term:"アジア=アフリカ会議",yomi:"アジア=アフリカかいぎ",def:"1955年、インドネシアのバンドンで開かれた会議。29か国のアジア・アフリカ諸国が参加し、反植民地主義や平和共存をうたう平和十原則を採択した。第三勢力の結集を示した。",year:1955,region:"sea",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["平和十原則","ネルー","周恩来","スカルノ"]},
  {term:"アジアNIES",yomi:"アジアニーズ",def:"1970年代以降、輸出志向型工業化で急成長した韓国・台湾・香港・シンガポールの4つの国・地域の総称。開発独裁のもとで外資を導入して発展した例が多い。",year:1970,end:1990,region:"east",cat:"経済・社会",rank:3,course:["sogo","tankyu"],related:["NIES","韓国","シンガポール"]},
  {term:"アジア・アフリカ会議",yomi:"アジア・アフリカかいぎ",def:"アジア=アフリカ会議と同じ。1955年にインドネシアのバンドンで開かれ、アジア・アフリカ29か国が平和十原則を採択した。バンドン会議ともいい、第三世界の連帯を示した。",year:1955,region:"sea",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["アジア=アフリカ会議","平和十原則","第三世界"]},
  {term:"アステカ文明",yomi:"アステカぶんめい",def:"メキシコ高原に栄えたメソアメリカ文明の一つ。都テノチティトランを中心に、太陽神信仰・人身供犠、ピラミッド状の神殿、絵文字などを特色とした。",year:1325,end:1521,region:"america",cat:"文化・学問",rank:2,course:["tankyu"],related:["アステカ王国","テノチティトラン","メソアメリカ文明"]},
  {term:"アステカ王国",yomi:"アステカおうこく",def:"14世紀にメキシコ高原にアステカ人がたてた国。都テノチティトランを中心に周辺を支配したが、1521年にスペインのコルテスに征服された。",year:1325,end:1521,region:"america",cat:"国家・王朝",rank:3,course:["tankyu"],related:["コルテス","テノチティトラン","インカ帝国"]},
  {term:"アスワン=ハイダム",yomi:"アスワン=ハイダム",def:"エジプトのナイル川上流に建設された巨大ダム。ナセル政権が建設を進め、英米の資金援助撤回がスエズ運河国有化のきっかけとなった。ソ連の援助で1970年に完成した。",year:1970,region:"west",cat:"経済・社会",rank:2,course:["tankyu"],related:["ナセル","スエズ運河国有化","エジプト"]},
  {term:"アズハル=モスク",yomi:"アズハル=モスク",def:"ファーティマ朝がカイロに建てたモスク。付属の学院はのちスンナ派の最高学府となり、現在も続くイスラーム世界の学問の中心の一つである。",year:970,region:"west",cat:"文化・学問",rank:1,course:["tankyu"],related:["ファーティマ朝","カイロ","イスラーム"]},
  {term:"アタナシウス派",yomi:"アタナシウスは",def:"イエスを神と同質とする説をとる派。325年のニケーア公会議で正統とされ、のちの三位一体説の基礎となった。クローヴィスはこの派に改宗し、ローマ人の支持を得た。",year:325,region:"europe",cat:"思想・宗教",rank:3,course:["tankyu"],related:["ニケーア公会議","アリウス派","三位一体説"]},
  {term:"アタワルパ",yomi:"アタワルパ",def:"インカ帝国最後の皇帝。1532年にスペインのピサロにとらえられ、翌年処刑された。これによりインカ帝国は事実上滅亡した。",year:1532,end:1533,region:"america",cat:"人物",rank:1,course:["tankyu"],related:["インカ帝国","ピサロ"]},
  {term:"アチェ戦争",yomi:"アチェせんそう",def:"スマトラ島北端のアチェ王国がオランダの侵略に抵抗した戦争。1873年に始まり、イスラームの信仰と結びついた激しい抵抗が20世紀初めまで続いた。",year:1873,end:1912,region:"sea",cat:"事件・戦争",rank:1,course:["tankyu"],related:["オランダ領東インド","イスラーム"]},
  {term:"アッカド人",yomi:"アッカドじん",def:"メソポタミアのセム語系民族。前24世紀ころサルゴン1世がシュメールの都市国家を征服して、メソポタミア最初の統一国家を築いた。",year:-2350,region:"west",cat:"国家・王朝",rank:2,course:["tankyu"],related:["サルゴン1世","シュメール人","アッカド語"]},
  {term:"アッカド語",yomi:"アッカドご",def:"アッカド人の用いたセム語系の言語。くさび形文字で書かれ、ハンムラビ法典もこの言語で記された。古代オリエントの国際共通語として広く用いられた。",region:"west",cat:"文化・学問",rank:1,course:["tankyu"],related:["アッカド人","くさび形文字","ハンムラビ法典"]},
  {term:"アッコン",yomi:"アッコン",def:"地中海東岸の港市。十字軍の拠点となったが、1291年にマムルーク朝に攻略され、十字軍国家はシリアから一掃された。",year:1291,region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["十字軍","イェルサレム王国","マムルーク朝"]},
  {term:"アッシュルバニパル",yomi:"アッシュルバニパル",def:"アッシリア最盛期の王。都ニネヴェに大図書館をつくり、くさび形文字の粘土板文書を集めたことで知られる。",year:-668,end:-627,region:"west",cat:"人物",rank:1,course:["tankyu"],related:["アッシリア","ニネヴェ","くさび形文字"]},
  {term:"アッシリア",yomi:"アッシリア",def:"北メソポタミアに興った国。鉄製武器と戦車・騎兵で強大となり、前7世紀前半にエジプトを含むオリエントを初めて統一した。しかし圧政に対する反乱をまねき、前612年に滅亡した。",year:-2000,end:-612,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["オリエント統一","アッシュルバニパル","ニネヴェ","4王国分立"]},
  {term:"アッシリア滅亡",yomi:"アッシリアめつぼう",def:"前612年、メディアと新バビロニアの攻撃で都ニネヴェが陥落し、アッシリアが滅んだできごと。その後オリエントは4王国に分立した。",year:-612,region:"west",cat:"事件・戦争",rank:1,course:["tankyu"],related:["アッシリア","4王国分立","メディア","新バビロニア"]},
  {term:"アッバース1世",yomi:"アッバースいっせい",def:"サファヴィー朝の最盛期の王。軍制改革を進めてオスマン帝国と戦い、ポルトガルからホルムズ島を奪った。新都イスファハーンを建設し、「世界の半分」とよばれるほど繁栄した。",year:1587,end:1629,region:"west",cat:"人物",rank:3,course:["tankyu"],related:["サファヴィー朝","イスファハーン","イマームのモスク"]},
  {term:"アッバース朝",yomi:"アッバースちょう",def:"750年にウマイヤ朝を倒して成立したイスラーム王朝。新都バグダードを建設し、アラブ人の特権をなくしてムスリムの平等を実現したイスラーム帝国となった。1258年にモンゴルに滅ぼされた。",year:750,end:1258,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["ウマイヤ朝","バグダード","ハールーン=アッラシード","イスラーム帝国"]},
  {term:"アッバース朝の滅亡",yomi:"アッバースちょうのめつぼう",def:"1258年、モンゴルのフレグがバグダードを攻略し、アッバース朝のカリフを殺害したできごと。フレグはその後イル=ハン国をたてた。",year:1258,region:"west",cat:"事件・戦争",rank:2,course:["tankyu"],related:["フレグ","イル=ハン国","バグダード"]},
  {term:"アテネ",yomi:"アテネ",def:"古代ギリシアの代表的なポリス。ソロン・クレイステネスらの改革を経て民主政を発展させ、ペルシア戦争後はデロス同盟の盟主として繁栄した。ペロポネソス戦争でスパルタに敗れた。",region:"europe",cat:"国家・王朝",rank:3,course:["tankyu"],related:["アテネ民主政","ペリクレス","ペロポネソス戦争","ソクラテス"]},
  {term:"アテネ民主政",yomi:"アテネみんしゅせい",def:"古代アテネで発達した民主政治。前5世紀のペリクレス時代に完成し、成年男性市民が民会で直接政治に参加した。女性・奴隷・在留外国人には参政権がなかった。",year:-508,end:-322,region:"europe",cat:"制度・政策",rank:3,course:["tankyu"],related:["ペリクレス","クレイステネス","民会"]},
  {term:"アデナウアー",yomi:"アデナウアー",def:"西ドイツの初代首相。キリスト教民主同盟を率い、西側陣営との協調を進めてNATO加盟や主権回復を実現した。経済の奇跡とよばれる復興を導いた。",year:1949,end:1963,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["西ドイツ","NATO","EEC"]},
  {term:"アトン",yomi:"アトン",def:"古代エジプトの太陽神。アメンホテプ4世（イクナートン）はアモン神官団をおさえるため、アトンを唯一神とする信仰改革を行った。",region:"west",cat:"思想・宗教",rank:1,course:["tankyu"],related:["アメンホテプ4世","テル=エル=アマルナ","アマルナ美術"]},
  {term:"アドワの戦い",yomi:"アドワのたたかい",def:"1896年、エチオピアがイタリア軍を撃退した戦い。皇帝メネリク2世が勝利し、エチオピアはアフリカ分割のなかで独立を守った。",year:1896,region:"africa",cat:"事件・戦争",rank:2,course:["tankyu"],related:["エチオピア","メネリク2世","アフリカ分割"]},
  {term:"アナトリア",yomi:"アナトリア",def:"小アジアともよばれる、現在のトルコの大部分を占める半島。ヒッタイトなどが栄え、11世紀以降トルコ化・イスラーム化が進み、オスマン帝国の発祥の地となった。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["小アジア","ルーム=セルジューク朝","オスマン帝国"]},
  {term:"アナーニ事件",yomi:"アナーニじけん",def:"1303年、フランス王フィリップ4世が、課税問題で対立した教皇ボニファティウス8世をアナーニで捕らえた事件。教皇はまもなく死に、教皇権の衰えを示した。",year:1303,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["フィリップ4世","ボニファティウス8世","教皇のバビロン捕囚"]},
  {term:"アパルトヘイト",yomi:"アパルトヘイト",def:"南アフリカで行われた人種隔離政策。1948年以降、白人政権が法制化し、非白人の居住・結婚・参政権などを差別した。国際的な批判をあび、1991年に撤廃された。",year:1948,end:1991,region:"africa",cat:"制度・政策",rank:3,course:["sogo","tankyu"],related:["南アフリカ共和国","マンデラ","アフリカ民族会議"]},
  {term:"アフガン戦争",yomi:"アフガンせんそう",def:"イギリスがアフガニスタンに侵攻した戦争。南下するロシアに対抗して19世紀に2度行われ、アフガニスタンを保護国化した。1919年の第3次戦争でアフガニスタンは独立した。",year:1838,end:1919,region:"south",cat:"事件・戦争",rank:2,course:["tankyu"],related:["グレート=ゲーム","イギリス","アフガニスタン"]},
  {term:"アフガン系",yomi:"アフガンけい",def:"アフガニスタン出身の人々のこと。デリー=スルタン朝最後のロディー朝はアフガン系の王朝で、1526年にバーブルに滅ぼされた。",year:1451,end:1526,region:"south",cat:"国家・王朝",rank:1,course:["tankyu"],related:["ロディー朝","デリー=スルタン朝"]},
  {term:"アフリカの年",yomi:"アフリカのとし",def:"17か国のアフリカ諸国が独立した1960年のこと。旧フランス領の国々を中心に多くの国が独立し、アフリカの脱植民地化が大きく進んだ。",year:1960,region:"africa",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["アフリカ統一機構","エンクルマ","脱植民地化"]},
  {term:"アフリカの角",yomi:"アフリカのつの",def:"アフリカ大陸東端のソマリア・エチオピアなどが位置する地域。サイの角のように突き出た形からこうよばれ、19世紀末にイギリス・イタリア・フランスが分割した。",region:"africa",cat:"地名・地域",rank:1,course:["tankyu"],related:["ソマリア","エチオピア"]},
  {term:"アフリカ分割",yomi:"アフリカぶんかつ",def:"19世紀末にヨーロッパ列強がアフリカを分割し植民地化したこと。1884〜85年のベルリン会議で先占権の原則が定められて競争が激化し、20世紀初めにはエチオピアとリベリア以外のほぼ全域が植民地となった。",year:1880,end:1914,region:"africa",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["ベルリン会議（1884〜85）","アフリカ縦断政策","アフリカ横断政策","帝国主義"]},
  {term:"アフリカ探検",yomi:"アフリカたんけん",def:"19世紀に行われたヨーロッパ人によるアフリカ内陸部の探検。リヴィングストンやスタンリーの探検により内陸の事情が知られ、のちのアフリカ分割をうながした。",year:1850,end:1880,region:"africa",cat:"事件・戦争",rank:1,course:["tankyu"],related:["リヴィングストン","スタンリー","アフリカ分割"]},
  {term:"アフリカ民族会議",yomi:"アフリカみんぞくかいぎ",def:"1912年に結成された南アフリカの黒人解放組織。ANCと略す。アパルトヘイトに反対して闘い、非合法化されたがマンデラらの指導で運動を続けた。1994年の全人種選挙で勝利し与党となった。",year:1912,region:"africa",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["マンデラ","アパルトヘイト","南アフリカ共和国"]},
  {term:"アフリカ民族会議（ANC）",yomi:"アフリカみんぞくかいぎ（エーエヌシー）",def:"アフリカ民族会議の略称をそえた表記。南アフリカで人種差別に反対した黒人解放組織で、1994年の全人種選挙で勝利し、マンデラが大統領となった。",year:1912,region:"africa",cat:"組織・運動",rank:2,course:["sogo","tankyu"],related:["アフリカ民族会議","マンデラ","アパルトヘイト"]},
  {term:"アフリカ統一機構",yomi:"アフリカとういつきこう",def:"OAU。1963年、エチオピアのアディスアベバで、アフリカ諸国の連帯と植民地主義の一掃をめざして結成された。2002年にアフリカ連合（AU）へ改組された。",year:1963,end:2002,region:"africa",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["アフリカの年","エンクルマ","アフリカ連合"]},
  {term:"アフリカ縦断政策",yomi:"アフリカじゅうだんせいさく",def:"イギリスがエジプトのカイロと南アフリカのケープタウンを結ぶ地域の支配をめざした政策。ローズらが推進し、フランスのアフリカ横断政策と衝突して1898年のファショダ事件をおこした。",year:1880,end:1914,region:"africa",cat:"制度・政策",rank:3,course:["sogo","tankyu"],related:["3C政策","ローズ","ファショダ事件","アフリカ横断政策"]},
  {term:"アブデュルハミト2世",yomi:"アブデュルハミトにせい",def:"オスマン帝国のスルタン。1876年にミドハト憲法を発布したが、ロシア=トルコ戦争を口実に翌年停止し、専制政治を行った。パン=イスラーム主義を利用したが、1908年の青年トルコ革命で憲法の復活を余儀なくされた。",year:1876,end:1909,region:"west",cat:"人物",rank:3,course:["tankyu"],related:["ミドハト憲法","オスマン帝国","青年トルコ革命"]},
  {term:"アブド=アッラフマーン3世",yomi:"アブド=アッラフマーンさんせい",def:"後ウマイヤ朝の最盛期の君主。929年にカリフを称し、アッバース朝・ファーティマ朝と並んで3人のカリフが並び立つことになった。都コルドバは西方イスラーム世界の中心として繁栄した。",year:912,end:961,region:"europe",cat:"人物",rank:1,course:["tankyu"],related:["後ウマイヤ朝","コルドバ","カリフ"]},
  {term:"アブド=アルカーディル",yomi:"アブド=アルカーディル",def:"フランスのアルジェリア侵略に抵抗した指導者。1830年代から1847年まで、イスラームの聖戦をかかげて抵抗運動を続けたが、降伏した。",year:1832,end:1847,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["アルジェリア出兵","フランス"]},
  {term:"アブー=バクル",yomi:"アブー=バクル",def:"ムハンマドの最初の後継者で、初代の正統カリフ。ムハンマドの死後に信徒の合意で選ばれ、アラビア半島の統一を回復し、征服活動を始めた。",year:632,end:634,region:"west",cat:"人物",rank:2,course:["tankyu"],related:["正統カリフ","ムハンマド","ジハード"]},
  {term:"アヘン",yomi:"アヘン",def:"ケシの実からつくる麻薬。18世紀末からイギリスがインド産アヘンを中国に密輸し、銀が国外へ大量に流出した。清の林則徐がアヘンを没収・廃棄したことがアヘン戦争の原因となった。",region:"east",cat:"経済・社会",rank:2,course:["sogo","tankyu"],related:["アヘン戦争","林則徐","三角貿易"]},
  {term:"アヘン戦争",yomi:"アヘンせんそう",def:"1840年、清のアヘン取り締まりに対しイギリスがおこした戦争。清は敗れて1842年に南京条約を結び、香港島の割譲や5港の開港を認めた。中国の半植民地化の始まりとされる。",year:1840,end:1842,region:"east",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["南京条約","林則徐","三角貿易","アロー戦争"]},
  {term:"アボリジニー",yomi:"アボリジニー",def:"オーストラリアの先住民。18世紀末以降のイギリス人の入植によって土地を奪われ、人口が激減した。長く差別を受け、20世紀後半から権利回復が進んだ。",region:"oceania",cat:"経済・社会",rank:1,course:["tankyu"],related:["オーストラリア","白豪主義","ゴールドラッシュ"]},
  {term:"アポロ11号",yomi:"アポロじゅういちごう",def:"1969年、アメリカのアポロ11号が人類初の月面着陸に成功した。ソ連のスプートニク1号打ち上げで始まった米ソの宇宙開発競争で、アメリカが優位を示した。",year:1969,region:"america",cat:"事件・戦争",rank:1,course:["sogo","tankyu"],related:["宇宙開発","冷戦","スプートニク1号"]},
  {term:"アマルナ文書",yomi:"アマルナぶんしょ",def:"エジプトのテル=エル=アマルナで発見された外交文書。くさび形文字のアッカド語で記され、エジプトとミタンニ・バビロニアなどとの国際関係を伝える。",year:-1350,region:"west",cat:"文化・学問",rank:1,course:["tankyu"],related:["アメンホテプ4世","アッカド語","ミタンニ"]},
  {term:"アマルナ美術",yomi:"アマルナびじゅつ",def:"アメンホテプ4世の時代に生まれた写実的な美術様式。伝統的な形式にとらわれず、王やその家族を自然でのびやかな姿で表現した。王妃ネフェルティティの胸像が代表作として知られる。",year:-1350,region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["アメンホテプ4世","アトン","テル=エル=アマルナ"]},
  {term:"アミン",yomi:"アミン",def:"ウガンダの軍人で大統領。1971年にクーデタで政権をにぎり、独裁政治を行って多くの国民を殺害した。アジア系住民を追放したことでも知られ、1979年に失脚した。",year:1971,end:1979,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["ウガンダ","クーデタ"]},
  {term:"アムステルダム",yomi:"アムステルダム",def:"オランダの都市。17世紀にはオランダ東インド会社の本拠地として、アントウェルペンにかわる国際商業・金融の中心となった。証券取引所や為替銀行が設けられ繁栄した。",region:"europe",cat:"地名・地域",rank:2,course:["tankyu"],related:["オランダ","オランダ東インド会社","商業革命"]},
  {term:"アムル人",yomi:"アムルじん",def:"セム語系の民族。前19世紀ころメソポタミアにバビロン第1王朝（古バビロニア王国）をたて、ハンムラビ王のとき全メソポタミアを統一した。",year:-1900,region:"west",cat:"国家・王朝",rank:2,course:["tankyu"],related:["バビロン第1王朝","ハンムラビ王","セム語系"]},
  {term:"アメリカ=スペイン戦争",yomi:"アメリカ=スペインせんそう",def:"1898年、キューバの独立運動を機にアメリカがスペインと戦った戦争。アメリカは勝利してフィリピン・グアム・プエルトリコを獲得し、キューバを保護国化した。米西戦争ともいう。",year:1898,region:"america",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["キューバ","フィリピン","マッキンリー","プラット条項"]},
  {term:"アメリカ=メキシコ戦争",yomi:"アメリカ=メキシコせんそう",def:"1846〜48年、テキサス併合をめぐってアメリカとメキシコの間でおこった戦争。勝利したアメリカはカリフォルニアなどを獲得し、太平洋岸に達した。",year:1846,end:1848,region:"america",cat:"事件・戦争",rank:2,course:["tankyu"],related:["カリフォルニア","テキサス","ゴールドラッシュ"]},
  {term:"アメリカとソ連の台頭",yomi:"アメリカとソれんのたいとう",def:"第一次世界大戦を機に、債権国となったアメリカと、ロシア革命で生まれた社会主義国ソ連が国際社会で存在感を高めたこと。ヨーロッパ中心の国際秩序がゆらぐきっかけとなった。",year:1917,end:1945,region:"america",cat:"事件・戦争",rank:1,course:["sogo"],related:["第一次世界大戦","ロシア革命","ウィルソン"]},
  {term:"アメリカ合衆国憲法",yomi:"アメリカがっしゅうこくけんぽう",def:"1787年、フィラデルフィアの憲法制定会議で制定された憲法。人民主権・連邦主義・三権分立を原則とし、強い連邦政府を設けた。1789年にワシントンが初代大統領に就任した。",year:1787,region:"america",cat:"条約・宣言",rank:3,course:["sogo","tankyu"],related:["三権分立","連邦主義","ワシントン"]},
  {term:"アメリカ独立宣言",yomi:"アメリカどくりつせんげん",def:"1776年7月4日、大陸会議で採択された宣言。ジェファソンらが起草し、ロックの思想の影響を受けて基本的人権と革命権をうたい、イギリスからの独立を宣言した。",year:1776,region:"america",cat:"条約・宣言",rank:3,course:["sogo","tankyu"],related:["ジェファソン","ロック","アメリカ独立戦争"]},
  {term:"アメリカ独立戦争",yomi:"アメリカどくりつせんそう",def:"北アメリカの13植民地がイギリス本国からの独立をめざして戦った戦争。1775年に始まり、ワシントンが総司令官となった。フランスなどの支援を得て勝利し、1783年のパリ条約で独立が承認された。",year:1775,end:1783,region:"america",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["アメリカ独立宣言","ワシントン","パリ条約（1783）"]},
  {term:"アメリカ連合国",yomi:"アメリカれんごうこく",def:"1861年、奴隷制の存続を求めるアメリカ南部諸州が連邦を離脱して結成した国。ジェファソン=デヴィスを大統領とし、南北戦争で北部と戦ったが、1865年に敗れた。",year:1861,end:1865,region:"america",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["南北戦争","リンカン","奴隷制"]},
  {term:"アメリカ＝スペイン戦争",yomi:"アメリカ＝スペインせんそう",def:"アメリカ=スペイン戦争の別表記。1898年の戦争でアメリカはスペインに勝利し、フィリピンなどを獲得して海外進出を本格化させた。",year:1898,region:"america",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["アメリカ=スペイン戦争","フィリピン","キューバ"]},
  {term:"アメリゴ=ヴェスプッチ",yomi:"アメリゴ=ヴェスプッチ",def:"イタリアの航海者。南アメリカを探検し、そこがアジアではなく「新大陸」であることを主張した。彼の名にちなんで「アメリカ」と名づけられた。",year:1499,end:1504,region:"america",cat:"人物",rank:2,course:["tankyu"],related:["コロンブス","大航海時代","カブラル"]},
  {term:"アメンホテプ4世",yomi:"アメンホテプよんせい",def:"古代エジプト新王国の王。アモン神官団の勢力をおさえるため、唯一神アトンの信仰を強制し、みずからイクナートンと名のってテル=エル=アマルナに遷都した。写実的なアマルナ美術が生まれた。",year:-1351,end:-1334,region:"west",cat:"人物",rank:3,course:["tankyu"],related:["アトン","アマルナ美術","テル=エル=アマルナ"]},
  {term:"アヤクーチョの戦い",yomi:"アヤクーチョのたたかい",def:"1824年、ペルーのアヤクーチョで独立軍がスペイン軍を破った戦い。南アメリカにおけるスペインの支配は事実上終わった。",year:1824,region:"america",cat:"事件・戦争",rank:1,course:["tankyu"],related:["シモン=ボリバル","サン=マルティン","ラテンアメリカ諸国の独立"]},
  {term:"アユタヤ朝",yomi:"アユタヤちょう",def:"1351年、タイのチャオプラヤ川下流に成立した王朝。港市国家として交易で栄え、日本町もつくられた。アンコール朝を攻撃して衰退させたが、1767年にビルマのコンバウン朝に滅ぼされた。",year:1351,end:1767,region:"sea",cat:"国家・王朝",rank:3,course:["tankyu"],related:["タイ","コンバウン朝","アンコール朝"]},
  {term:"アユタヤ朝の滅亡",yomi:"アユタヤちょうのめつぼう",def:"1767年、ビルマのコンバウン朝の攻撃によって都アユタヤが陥落し、アユタヤ朝が滅んだできごと。その後タイではトンブリー朝をへてラタナコーシン朝が成立した。",year:1767,region:"sea",cat:"事件・戦争",rank:1,course:["tankyu"],related:["アユタヤ朝","コンバウン朝","ラタナコーシン朝"]},
  {term:"アラウンパヤー",yomi:"アラウンパヤー",def:"ビルマのコンバウン朝の建国者。1752年に王朝を開き、ビルマを再統一した。",year:1752,end:1760,region:"sea",cat:"人物",rank:1,course:["tankyu"],related:["コンバウン朝","ビルマ"]},
  {term:"アラスカ",yomi:"アラスカ",def:"北アメリカ大陸北西部の地域。18世紀以来ロシアが毛皮交易などで進出したが、1867年にアメリカに売却された。1959年にアメリカの州となった。",region:"america",cat:"地名・地域",rank:1,course:["tankyu"],related:["アラスカ買収","ロシア","アメリカ合衆国"]},
  {term:"アラスカ買収",yomi:"アラスカばいしゅう",def:"1867年、アメリカがロシアからアラスカを720万ドルで購入したこと。当時は「むだな買い物」と批判されたが、のちに金や石油が発見された。",year:1867,region:"america",cat:"事件・戦争",rank:2,course:["tankyu"],related:["アラスカ","ロシア","西部開拓"]},
  {term:"アラファト",yomi:"アラファト",def:"パレスチナの指導者。1969年からPLO議長として対イスラエル闘争を指導した。1993年にオスロ合意を結び、パレスチナ暫定自治政府の議長となった。",year:1969,end:2004,region:"west",cat:"人物",rank:2,course:["sogo","tankyu"],related:["PLO","オスロ合意","パレスチナ問題"]},
  {term:"アラブの春",yomi:"アラブのはる",def:"2010年末のチュニジアに始まり、アラブ諸国に広がった民主化運動。SNSを通じて運動が広がり、チュニジア・エジプト・リビアなどで長期独裁政権が倒れたが、シリアなどでは内戦に発展した。",year:2010,end:2012,region:"west",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["チュニジア","シリア内戦","インターネット"]},
  {term:"アラブ帝国",yomi:"アラブていこく",def:"ウマイヤ朝のように、アラブ人が支配層として特権をもったイスラーム国家をさす言葉。非アラブ人の改宗者（マワーリー）にも税を課したため不満をまねき、アッバース朝の「イスラーム帝国」と対比される。",year:661,end:750,region:"west",cat:"国家・王朝",rank:2,course:["tankyu"],related:["ウマイヤ朝","イスラーム帝国","ジズヤ"]},
  {term:"アラブ民族主義",yomi:"アラブみんぞくしゅぎ",def:"アラブ人の統一と独立をめざす思想・運動。オスマン帝国や欧米の支配に対抗して高まり、第二次世界大戦後はエジプトのナセルが指導者として影響力をもった。",region:"west",cat:"思想・宗教",rank:2,course:["sogo","tankyu"],related:["ナセル","アラブ連合共和国","フセイン・マクマホン協定"]},
  {term:"アラブ連合共和国",yomi:"アラブれんごうきょうわこく",def:"1958年、エジプトとシリアが合併して成立した国家。ナセルが大統領となったが、1961年にシリアが離脱し、事実上解体した。",year:1958,end:1961,region:"west",cat:"国家・王朝",rank:1,course:["tankyu"],related:["ナセル","アラブ民族主義","シリア"]},
  {term:"アラム文字",yomi:"アラムもじ",def:"アラム人が用いた表音文字。フェニキア文字と同系統で、アラム人の内陸交易により広まり、ヘブライ文字・アラビア文字・ソグド文字などの母体となった。",region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["アラム人","フェニキア文字","ソグド文字"]},
  {term:"アラム語",yomi:"アラムご",def:"セム語系のアラム人の言語。アラム人の内陸交易によって広まり、アケメネス朝などで公用語として用いられ、オリエントの国際語となった。",region:"west",cat:"文化・学問",rank:1,course:["tankyu"],related:["アラム人","アラム文字","ダマスクス"]},
  {term:"アラーウッディーン",yomi:"アラーウッディーン",def:"デリー=スルタン朝のハルジー朝の君主。モンゴルの侵入を撃退し、南インドに遠征して支配を広げた。地租の金納化など財政改革も行った。",year:1296,end:1316,region:"south",cat:"人物",rank:1,course:["tankyu"],related:["ハルジー朝","デリー=スルタン朝"]},
  {term:"アリウス派",yomi:"アリウスは",def:"イエスの神性を否定し、人間性を強調した派。アリウスが唱え、325年のニケーア公会議で異端とされたが、ゴート人などゲルマン人の間に広まった。",year:325,region:"europe",cat:"思想・宗教",rank:3,course:["tankyu"],related:["ニケーア公会議","アタナシウス派","ゲルマン人の大移動"]},
  {term:"アリストテレス",yomi:"アリストテレス",def:"古代ギリシアの哲学者。プラトンに学び、アレクサンドロス大王の家庭教師をつとめた。自然科学から政治学まで諸学問を体系化し「万学の祖」とよばれる。イスラーム世界や中世ヨーロッパのスコラ学に大きな影響を与えた。",year:-384,end:-322,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["プラトン","アレクサンドロス大王","『政治学』","イブン=ルシュド"]},
  {term:"アリストテレス哲学",yomi:"アリストテレスてつがく",def:"アリストテレスが体系化した哲学。アラビア語に翻訳されてイスラーム世界で研究され、12世紀以降ラテン語訳を通じて西ヨーロッパに伝わり、スコラ学の基礎となった。",region:"europe",cat:"思想・宗教",rank:1,course:["tankyu"],related:["アリストテレス","スコラ学","イスラーム科学"]},
  {term:"アリストテレス注釈",yomi:"アリストテレスちゅうしゃく",def:"コルドバ出身のイブン=ルシュドが行ったアリストテレスの著作への注釈。ラテン語に翻訳されて中世ヨーロッパのスコラ学に大きな影響を与えた。",region:"west",cat:"文化・学問",rank:1,course:["tankyu"],related:["イブン=ルシュド","アリストテレス","スコラ学"]},
  {term:"アリー",yomi:"アリー",def:"ムハンマドのいとこで娘婿。第4代の正統カリフとなったが、ムアーウィヤと対立し暗殺された。アリーとその子孫のみを正統な指導者とする人々がシーア派となった。",year:656,end:661,region:"west",cat:"人物",rank:2,course:["tankyu"],related:["正統カリフ","シーア派","ウマイヤ朝"]},
  {term:"アルクイン",yomi:"アルクイン",def:"イングランド出身の学者。カール大帝に招かれて宮廷で学問を指導し、ラテン語文芸の復興であるカロリング=ルネサンスの中心となった。",region:"europe",cat:"人物",rank:1,course:["tankyu"],related:["カール大帝","カロリング=ルネサンス"]},
  {term:"アルサケス",yomi:"アルサケス",def:"イラン系遊牧民の族長。前3世紀半ば、セレウコス朝から独立してパルティアを建国した。中国では王朝名が「安息」と記された。",year:-247,region:"west",cat:"人物",rank:1,course:["tankyu"],related:["パルティア","セレウコス朝"]},
  {term:"アルザス・ロレーヌ",yomi:"アルザス・ロレーヌ",def:"フランス北東部の地方。鉄鉱石・石炭が豊富で、1871年プロイセン=フランス戦争の結果ドイツに割譲された。第一次世界大戦後のヴェルサイユ条約でフランスに返還された。",year:1871,end:1919,region:"europe",cat:"地名・地域",rank:2,course:["sogo","tankyu"],related:["ドイツ帝国","プロイセン=フランス戦争","ヴェルサイユ条約"]},
  {term:"アルジェリア出兵",yomi:"アルジェリアしゅっぺい",def:"1830年、フランス国王シャルル10世が国民の不満をそらすために行ったアルジェリアへの出兵。これをきっかけにフランスのアルジェリア植民地化が進んだ。",year:1830,region:"africa",cat:"事件・戦争",rank:2,course:["tankyu"],related:["シャルル10世","七月革命","アルジェリア戦争"]},
  {term:"アルジェリア戦争",yomi:"アルジェリアせんそう",def:"1954年に始まったアルジェリアのフランスからの独立戦争。民族解放戦線（FLN）が武装闘争を展開し、フランスでは第四共和政が倒れた。ド=ゴールのもとで1962年に独立が認められた。",year:1954,end:1962,region:"africa",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ド=ゴール","第五共和政","民族解放戦線"]},
  {term:"アルジェリア独立",yomi:"アルジェリアどくりつ",def:"1962年、エヴィアン協定にもとづき、アルジェリアがフランスから独立したこと。ド=ゴール大統領が独立を承認し、長いアルジェリア戦争が終わった。",year:1962,region:"africa",cat:"事件・戦争",rank:1,course:["sogo","tankyu"],related:["アルジェリア戦争","ド=ゴール","エヴィアン協定"]},
  {term:"アルゼンチン",yomi:"アルゼンチン",def:"南アメリカ南部の国。1816年にスペインから独立し、サン=マルティンが拠点とした。19世紀後半以降、牛肉・小麦などの輸出で発展した。",year:1816,region:"america",cat:"国家・王朝",rank:1,course:["tankyu"],related:["サン=マルティン","ラテンアメリカ諸国の独立","ペロン"]},
  {term:"アルタン=ハン",yomi:"アルタン=ハン",def:"16世紀のモンゴル（タタール）の指導者。たびたび明に侵入し、1550年には北京を包囲した（北虜）。チベット仏教に帰依し、ダライ=ラマの称号を贈った。",year:1550,region:"inner",cat:"人物",rank:2,course:["tankyu"],related:["北虜南倭","チベット仏教","明"]},
  {term:"アルダシール1世",yomi:"アルダシールいっせい",def:"ササン朝ペルシアの建国者。224年にパルティアを倒して王朝を開き、都をクテシフォンに置いた。ゾロアスター教を国教とし、イラン人の伝統の復興をかかげた。",year:224,end:241,region:"west",cat:"人物",rank:2,course:["tankyu"],related:["ササン朝","パルティア","ゾロアスター教"]},
  {term:"アルハンブラ宮殿",yomi:"アルハンブラきゅうでん",def:"イベリア半島南部のグラナダにあるナスル朝の宮殿。13〜14世紀に造営され、精巧なアラベスクの装飾をもつイスラーム建築の代表作である。",region:"europe",cat:"文化・学問",rank:2,course:["tankyu"],related:["ナスル朝","グラナダ","レコンキスタ"]},
  {term:"アルファベット",yomi:"アルファベット",def:"フェニキア人の表音文字をもとに、ギリシア人が母音字を加えてつくった文字体系。ラテン文字（ローマ字）を経てヨーロッパ諸言語に広まった。",region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["フェニキア文字","ギリシア人","アラム文字"]},
  {term:"アレクサンドリア",yomi:"アレクサンドリア",def:"アレクサンドロス大王がエジプトのナイル河口に建設した都市。プトレマイオス朝の都として栄え、王立研究所ムセイオンが置かれてヘレニズム文化の中心となった。",year:-331,region:"africa",cat:"地名・地域",rank:3,course:["tankyu"],related:["プトレマイオス朝","ムセイオン","ヘレニズム"]},
  {term:"アレクサンドロス",yomi:"アレクサンドロス",def:"アレクサンドロス大王の名の表記。マケドニア王としてアケメネス朝を滅ぼし、ギリシアからインダス川におよぶ大帝国を築いた。",year:-336,end:-323,region:"europe",cat:"人物",rank:1,course:["tankyu"],related:["アレクサンドロス大王","アリストテレス"]},
  {term:"アレクサンドロス大王",yomi:"アレクサンドロスだいおう",def:"マケドニア王。前334年に東方遠征を開始し、イッソスの戦いなどでアケメネス朝を滅ぼし、インダス川流域にいたる大帝国を築いた。東西文化の融合をうながし、ヘレニズム時代を開いた。",year:-336,end:-323,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["アケメネス朝","イッソスの戦い","ヘレニズム","アリストテレス"]},
  {term:"アンカラの戦い",yomi:"アンカラのたたかい",def:"1402年、ティムールがオスマン帝国のバヤジット1世を破った戦い。バヤジット1世は捕虜となり、オスマン帝国は一時的に混乱した。",year:1402,region:"west",cat:"事件・戦争",rank:3,course:["tankyu"],related:["ティムール","バヤジット1世","オスマン帝国"]},
  {term:"アングロ=サクソン人",yomi:"アングロ=サクソンじん",def:"ゲルマン人の一派。5世紀にブリテン島に渡り、七王国（ヘプターキー）を建てた。9世紀にエグバートが統一し、イングランド王国の基礎ができた。",year:449,region:"europe",cat:"国家・王朝",rank:2,course:["tankyu"],related:["ゲルマン人の大移動","七王国","エグバート"]},
  {term:"アンコール=トム",yomi:"アンコール=トム",def:"カンボジアのアンコール朝の都城。12世紀末、ジャヤヴァルマン7世が造営し、中心には観音菩薩の顔をもつ仏教寺院バイヨンがある。",region:"sea",cat:"文化・学問",rank:2,course:["tankyu"],related:["ジャヤヴァルマン7世","アンコール朝","アンコール=ワット"]},
  {term:"アンコール=ワット",yomi:"アンコール=ワット",def:"カンボジアのアンコール朝で、12世紀前半に建てられたヒンドゥー教寺院。のちに仏教寺院となった。東南アジアの代表的な石造建築である。",region:"sea",cat:"文化・学問",rank:3,course:["tankyu"],related:["アンコール朝","ヒンドゥー教","アンコール=トム"]},
  {term:"アンコール朝",yomi:"アンコールちょう",def:"9世紀から15世紀にカンボジアで栄えたクメール人の王朝。12世紀にアンコール=ワットやアンコール=トムが建設されたが、タイのアユタヤ朝の攻撃で衰えた。",year:802,end:1432,region:"sea",cat:"国家・王朝",rank:3,course:["tankyu"],related:["カンボジア","クメール人","アンコール=ワット"]},
  {term:"アンゴラ内戦",yomi:"アンゴラないせん",def:"1975年のアンゴラ独立後に始まった内戦。ソ連・キューバが支援する政府と、アメリカ・南アフリカが支援する勢力が争う冷戦の代理戦争となった。2002年に終結した。",year:1975,end:2002,region:"africa",cat:"事件・戦争",rank:1,course:["tankyu"],related:["アンゴラ独立戦争","冷戦","カーネーション革命"]},
  {term:"アンゴラ独立戦争",yomi:"アンゴラどくりつせんそう",def:"ポルトガルの植民地アンゴラで1961年に始まった独立闘争。1974年のポルトガルのカーネーション革命により、翌年アンゴラは独立した。",year:1961,end:1974,region:"africa",cat:"事件・戦争",rank:1,course:["tankyu"],related:["カーネーション革命","ポルトガル","アンゴラ内戦"]},
  {term:"アンティオキア",yomi:"アンティオキア",def:"シリア北部の都市。セレウコス朝の都として繁栄し、ローマ時代も東方の大都市であった。初期キリスト教の中心地の一つで、十字軍の時代にはアンティオキア公国が置かれた。",year:-300,region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["セレウコス朝","十字軍","ヘレニズム"]},
  {term:"アンデス文明",yomi:"アンデスぶんめい",def:"南アメリカのアンデス山脈地帯に栄えた文明の総称。チャビン文化などをへて、15世紀にインカ帝国が成立した。ジャガイモやトウモロコシの栽培を基盤とした。",region:"america",cat:"文化・学問",rank:2,course:["tankyu"],related:["インカ帝国","チャビン文化","キープ"]},
  {term:"アントニウス",yomi:"アントニウス",def:"古代ローマの政治家・軍人。カエサルの部下で、オクタウィアヌス・レピドゥスと第2回三頭政治を行った。エジプトのクレオパトラと結んだが、アクティウムの海戦で敗れ自殺した。",year:-43,end:-30,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["第2回三頭政治","クレオパトラ","アクティウムの海戦"]},
  {term:"アヴィケンナ",yomi:"アヴィケンナ",def:"イブン=シーナーのラテン語名。『医学典範』を著したイスラーム世界の医学者・哲学者で、中世ヨーロッパではこの名で知られた。",region:"west",cat:"人物",rank:1,course:["tankyu"],related:["イブン=シーナー","『医学典範』","イスラーム科学"]},
  {term:"アーリヤ人",yomi:"アーリヤじん",def:"インド=ヨーロッパ語系の人々。前1500年ころ中央アジアからインド北西部に進入し、のちガンジス川流域に移った。ヴェーダを生み、ヴァルナ制とバラモン教を形づくった。",year:-1500,region:"south",cat:"国家・王朝",rank:3,course:["tankyu"],related:["ヴェーダ","ヴァルナ制","バラモン教"]},
  {term:"イェニチェリ",yomi:"イェニチェリ",def:"オスマン帝国のスルタン直属の常備歩兵軍団。キリスト教徒の子弟をデヴシルメで徴用し、イスラームに改宗させて編成した。のちに特権化して改革の障害となり、1826年に廃止された。",region:"west",cat:"制度・政策",rank:3,course:["tankyu"],related:["オスマン帝国","デヴシルメ","マフムト2世"]},
  {term:"イェルサレム",yomi:"イェルサレム",def:"パレスチナの都市。ユダヤ教・キリスト教・イスラームの共通の聖地であり、十字軍による争奪の対象となった。現代でもイスラエルとパレスチナの間で帰属が争われている。",region:"west",cat:"地名・地域",rank:3,course:["tankyu"],related:["ヘブライ人","十字軍","岩のドーム","パレスチナ問題"]},
  {term:"イェルサレム奪回",yomi:"イェルサレムだっかい",def:"1187年、アイユーブ朝のサラーフ=アッディーンが十字軍のイェルサレム王国から聖地イェルサレムを奪い返したできごと。これを機に第3回十字軍がおこされた。",year:1187,region:"west",cat:"事件・戦争",rank:1,course:["tankyu"],related:["サラーフ=アッディーン","十字軍","アイユーブ朝"]},
  {term:"イェルサレム王国",yomi:"イェルサレムおうこく",def:"第1回十字軍がイェルサレムを占領して1099年にたてた国家。1187年にイェルサレムを失ったのちもアッコンなどを拠点に存続したが、1291年に滅んだ。",year:1099,end:1291,region:"west",cat:"国家・王朝",rank:2,course:["tankyu"],related:["十字軍","ウルバヌス2世","アッコン"]},
  {term:"イエス",yomi:"イエス",def:"キリスト教の始祖。パレスチナでユダヤ教の律法主義を批判し、神の絶対愛と隣人愛を説いた。ローマへの反逆者として十字架刑に処されたが、弟子たちは彼の復活を信じ、救世主（キリスト）とした。",year:-4,end:30,region:"west",cat:"人物",rank:3,course:["tankyu"],related:["キリスト教","パウロ","『新約聖書』"]},
  {term:"イエズス会",yomi:"イエズスかい",def:"1534年、イグナティウス=ロヨラらが結成したカトリックの修道会。対抗宗教改革の中心となり、ザビエルやマテオ=リッチらがアジアやアメリカ大陸で布教した。",year:1534,region:"europe",cat:"組織・運動",rank:3,course:["tankyu"],related:["ロヨラ","ザビエル","マテオ=リッチ","対抗宗教改革"]},
  {term:"イエメン統一",yomi:"イエメンとういつ",def:"1990年、北イエメン（イエメン=アラブ共和国）と南イエメン（イエメン人民民主共和国）が統一し、イエメン共和国が成立したこと。冷戦の終結と同時期のできごとである。",year:1990,region:"west",cat:"事件・戦争",rank:1,course:["tankyu"],related:["冷戦の終結","ドイツ統一"]},
  {term:"イギリス",yomi:"イギリス",def:"ヨーロッパ北西部の島国。イングランドを中心に1707年にスコットランドと合同してグレートブリテン王国となった。いち早く産業革命を達成し、19世紀には世界に植民地を広げて「世界の工場」とよばれた。",region:"europe",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["イギリス東インド会社","産業革命","イギリス連邦"]},
  {term:"イギリス=ビルマ戦争",yomi:"イギリス=ビルマせんそう",def:"19世紀にイギリスとビルマのコンバウン朝が3度にわたって戦った戦争。1885年に王朝は滅び、翌年ビルマはイギリス領インドに併合された。",year:1824,end:1885,region:"sea",cat:"事件・戦争",rank:2,course:["tankyu"],related:["コンバウン朝","イギリス領インド"]},
  {term:"イギリスのスエズ以東撤退",yomi:"イギリスのスエズいとうてったい",def:"1960年代末にイギリスが財政難から発表した、スエズ運河以東からの軍事撤退。1971年までにペルシア湾から撤退し、同年アラブ首長国連邦などが独立した。",year:1971,region:"west",cat:"事件・戦争",rank:1,course:["tankyu"],related:["イギリス","ペルシア湾","アラブ首長国連邦"]},
  {term:"イギリス南アフリカ会社",yomi:"イギリスみなみアフリカがいしゃ",def:"1889年にローズが設立した特許会社。南アフリカの北方に進出して植民地支配を行い、その地域はローズにちなんでローデシアとよばれた。",year:1889,region:"africa",cat:"組織・運動",rank:1,course:["tankyu"],related:["ローズ","ローデシア","アフリカ縦断政策"]},
  {term:"イギリス国教会",yomi:"イギリスこっきょうかい",def:"1534年の首長法でヘンリ8世がローマ教会から独立させたイギリスの教会。国王を首長とし、エリザベス1世の統一法で制度が確立した。教義はプロテスタント、儀式はカトリック的な要素を残した。",year:1534,region:"europe",cat:"思想・宗教",rank:3,course:["tankyu"],related:["ヘンリ8世","首長法","エリザベス1世","統一法"]},
  {term:"イギリス東インド会社",yomi:"イギリスひがしインドがいしゃ",def:"1600年にエリザベス1世の特許状を受けて設立された会社。アジア貿易を独占し、18世紀後半からインドの植民地支配を進めた。1833年に商業活動を停止し、インド大反乱後の1858年に解散した。",year:1600,end:1858,region:"south",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["プラッシーの戦い","インド大反乱","ラッフルズ","シンガポール"]},
  {term:"イギリス経験論",yomi:"イギリスけいけんろん",def:"知識の源泉を経験に求め、観察と実験から一般的法則を導く帰納法を重んじる哲学。フランシス=ベーコンが創始し、ロックやヒュームが発展させた。大陸合理論と対比される。",region:"europe",cat:"思想・宗教",rank:2,course:["tankyu"],related:["フランシス=ベーコン","ロック","大陸合理論"]},
  {term:"イギリス連邦",yomi:"イギリスれんぽう",def:"イギリス本国と旧植民地などで構成されるゆるやかな連合体。1931年のウェストミンスター憲章で自治領が本国と対等とされて成立し、第二次世界大戦後は多くの独立国が加わった。",year:1931,region:"europe",cat:"組織・運動",rank:2,course:["sogo","tankyu"],related:["ウェストミンスター憲章","カナダ","オーストラリア"]},
  {term:"イクター制",yomi:"イクターせい",def:"軍人に俸給のかわりに土地の徴税権（イクター）を与える制度。ブワイフ朝が始め、セルジューク朝で広く用いられ、その後のイスラーム諸王朝に受けつがれた。",year:946,region:"west",cat:"制度・政策",rank:3,course:["tankyu"],related:["ブワイフ朝","セルジューク朝","マムルーク"]},
  {term:"イサベル",yomi:"イサベル",def:"カスティリャの女王。アラゴンの王子フェルナンドと結婚し、1479年にスペイン王国が成立した。1492年にグラナダを陥落させてレコンキスタを完了し、同年コロンブスの航海を援助した。",year:1474,end:1504,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["カスティリャ王国","レコンキスタ","コロンブス"]},
  {term:"イスタンブル",yomi:"イスタンブル",def:"旧コンスタンティノープル。1453年にメフメト2世がビザンツ帝国を滅ぼして占領し、オスマン帝国の都とした。東西交易の中心として栄えた。",year:1453,region:"west",cat:"地名・地域",rank:3,course:["tankyu"],related:["コンスタンティノープル","メフメト2世","オスマン帝国"]},
  {term:"イスパニョーラ島",yomi:"イスパニョーラとう",def:"カリブ海の大アンティル諸島の島。1492年にコロンブスが到達し、スペインの最初の植民の拠点となった。現在は西側をハイチ、東側をドミニカ共和国が占める。",year:1492,region:"america",cat:"地名・地域",rank:1,course:["tankyu"],related:["コロンブス","ハイチ","カリブ海"]},
  {term:"イスファハーン",yomi:"イスファハーン",def:"イラン中部の都市。サファヴィー朝のアッバース1世が都とし、イマームのモスクなどが建設された。「イスファハーンは世界の半分」といわれるほど繁栄した。",year:1597,region:"west",cat:"地名・地域",rank:2,course:["tankyu"],related:["アッバース1世","サファヴィー朝","イマームのモスク"]},
  {term:"イスマーイール1世",yomi:"イスマーイールいっせい",def:"サファヴィー朝の建国者。神秘主義教団を率いて1501年にタブリーズで即位し、シャーの称号を用いた。十二イマーム派のシーア派を国教とした。",year:1501,end:1524,region:"west",cat:"人物",rank:2,course:["tankyu"],related:["サファヴィー朝","シーア派","シャー"]},
  {term:"イスマーイール派",yomi:"イスマーイールは",def:"シーア派の一派。10世紀に北アフリカでファーティマ朝をたて、エジプトを支配してカリフを称した。",region:"west",cat:"思想・宗教",rank:1,course:["tankyu"],related:["シーア派","ファーティマ朝"]},
  {term:"イスラーム",yomi:"イスラーム",def:"7世紀初め、ムハンマドがアラビア半島で唯一神アッラーの啓示を受けて始めた一神教。神への絶対的帰依を説き、聖典『コーラン（クルアーン）』にもとづき、六信五行を信者の義務とする。",year:610,region:"west",cat:"思想・宗教",rank:3,course:["sogo","tankyu"],related:["ムハンマド","コーラン（クルアーン）","ウンマ","カリフ"]},
  {term:"イスラームの広まり",yomi:"イスラームのひろまり",def:"7世紀のアラビア半島に始まったイスラームが、征服活動や商人・神秘主義教団の活動を通じて、西アジアから北アフリカ・中央アジア・インド・東南アジア・西アフリカへと広がっていったこと。",region:"west",cat:"経済・社会",rank:1,course:["tankyu"],related:["イスラーム","イスラーム化","ムスリム商人"]},
  {term:"イスラーム・ネットワーク",yomi:"イスラーム・ネットワーク",def:"イスラーム世界の各地を結ぶ交易・学問・信仰のつながり。共通の言語（アラビア語）や法、メッカ巡礼などに支えられ、14世紀のイブン=バットゥータはこれを利用してアジア・アフリカを旅した。",region:"west",cat:"経済・社会",rank:1,course:["tankyu"],related:["イブン=バットゥータ","ムスリム商人","インド洋交易"]},
  {term:"イスラーム化",yomi:"イスラームか",def:"ある地域の人々がイスラームを受け入れていく過程。中央アジアではトルコ人のカラハン朝、東南アジアではマラッカ王国などの港市国家、西アフリカではマリ王国などで進んだ。",region:"west",cat:"経済・社会",rank:2,course:["tankyu"],related:["イスラーム","イスラームの広まり","ムスリム商人"]},
  {term:"イスラーム帝国",yomi:"イスラームていこく",def:"アッバース朝のように、アラブ人の特権を廃し、民族をこえたムスリムの平等をはかったイスラーム国家をさす言葉。改宗者はジズヤを免除され、アラブ人も土地をもてばハラージュを負担した。",year:750,end:1258,region:"west",cat:"国家・王朝",rank:2,course:["tankyu"],related:["アッバース朝","アラブ帝国","ジズヤ"]},
  {term:"イスラーム法",yomi:"イスラームほう",def:"シャリーアともいう。コーランとハディース（ムハンマドの言行の伝承）にもとづく法で、信仰儀礼から婚姻・相続・商取引・刑罰まで生活全般を規定する。ウラマーとよばれる学者が解釈した。",region:"west",cat:"制度・政策",rank:2,course:["tankyu"],related:["シャリーア","コーラン（クルアーン）","ウラマー"]},
  {term:"イスラーム科学",yomi:"イスラームかがく",def:"ギリシア語文献の翻訳を通じて古代ギリシアやインドの学問を受けつぎ、イスラーム世界で発達した学問。数学・天文学・医学・化学などが発展し、のちにヨーロッパに伝わった。",region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["イブン=シーナー","ギリシア語文献の翻訳","フワーリズミー"]},
  {term:"イタリア=トルコ戦争",yomi:"イタリア=トルコせんそう",def:"1911〜12年、イタリアがオスマン帝国と戦い、北アフリカのリビア（トリポリ・キレナイカ）を獲得した戦争。オスマン帝国の弱体化を示し、バルカン戦争のきっかけとなった。",year:1911,end:1912,region:"africa",cat:"事件・戦争",rank:2,course:["tankyu"],related:["リビア","オスマン帝国","バルカン戦争"]},
  {term:"イタリアの占領",yomi:"イタリアのせんりょう",def:"1939年、ムッソリーニのイタリアがアルバニアに侵攻し、併合したこと。イタリアはすでに1920年代からアルバニアを保護国化していた。",year:1939,region:"europe",cat:"事件・戦争",rank:1,course:["tankyu"],related:["ムッソリーニ","アルバニア","ファシスト党"]},
  {term:"イタリア戦争",yomi:"イタリアせんそう",def:"1494年から1559年まで、イタリアの支配をめぐってフランスのヴァロワ朝と神聖ローマ皇帝・スペインのハプスブルク家が争った戦争。主権国家体制が形成される契機となった。",year:1494,end:1559,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["カール5世","ハプスブルク家","ヴァロワ朝"]},
  {term:"イタリア王国",yomi:"イタリアおうこく",def:"1861年、サルデーニャ王国を中心に成立した統一国家。ヴィットーリオ=エマヌエーレ2世が初代国王となった。1866年にヴェネツィア、1870年に教皇領を併合したが、「未回収のイタリア」が残った。",year:1861,end:1946,region:"europe",cat:"国家・王朝",rank:3,course:["sogo","tankyu"],related:["イタリア統一","サルデーニャ王国","ヴィットーリオ=エマヌエーレ2世"]},
  {term:"イタリア統一",yomi:"イタリアとういつ",def:"19世紀に分裂していたイタリアが一つの国家にまとまった過程。サルデーニャ王国のカヴールの外交とガリバルディの両シチリア王国征服によって1861年にイタリア王国が成立し、1870年に教皇領を併合した。",year:1859,end:1870,region:"europe",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["カヴール","ガリバルディ","サルデーニャ王国","イタリア王国"]},
  {term:"イダルゴ",yomi:"イダルゴ",def:"メキシコの神父。1810年、インディオやメスティーソを率いてスペインからの独立を求めて蜂起したが、処刑された。メキシコはのち1821年に独立した。",year:1810,region:"america",cat:"人物",rank:1,course:["tankyu"],related:["メキシコ","クリオーリョ","ラテンアメリカ諸国の独立"]},
  {term:"イッソスの戦い",yomi:"イッソスのたたかい",def:"前333年、アレクサンドロス大王がアケメネス朝のダレイオス3世を破った戦い。小アジア南東部で行われ、大王の東方遠征の勝利を決定づけた。",year:-333,region:"west",cat:"事件・戦争",rank:2,course:["tankyu"],related:["アレクサンドロス大王","ダレイオス3世","アケメネス朝"]},
  {term:"イデア",yomi:"イデア",def:"プラトンの哲学で、感覚でとらえられる現実の事物をこえて存在する永遠不変の本質のこと。理性によってのみ認識できるとされた。",region:"europe",cat:"思想・宗教",rank:1,course:["tankyu"],related:["プラトン","イデア論"]},
  {term:"イデア論",yomi:"イデアろん",def:"プラトンが説いた哲学。現実の世界はイデアの影にすぎず、真の実在であるイデアは理性によってのみとらえられるとした。弟子のアリストテレスはこれを批判した。",region:"europe",cat:"思想・宗教",rank:2,course:["tankyu"],related:["プラトン","イデア","アリストテレス"]},
  {term:"イブン=サウード",yomi:"イブン=サウード",def:"サウジアラビア王国の建国者。サウード家の出身で、ワッハーブ派と結んでアラビア半島の大部分を統一し、1932年に国名をサウジアラビアとした。",year:1932,end:1953,region:"west",cat:"人物",rank:2,course:["tankyu"],related:["サウジアラビア","ワッハーブ派","サウード家"]},
  {term:"イブン=ハルドゥーン",yomi:"イブン=ハルドゥーン",def:"チュニス出身の歴史家。『世界史序説』（『歴史序説』）で、都市と遊牧民の関係から王朝の興亡を説明する独自の歴史理論を示した。",year:1332,end:1406,region:"africa",cat:"人物",rank:2,course:["tankyu"],related:["『世界史序説』","マムルーク朝","イスラーム科学"]},
  {term:"イブン=バットゥータ",yomi:"イブン=バットゥータ",def:"モロッコ出身の旅行家。14世紀にメッカ巡礼を出発点として、西アジア・インド・中国・西アフリカなどを旅し、その見聞を『大旅行記』にまとめた。",year:1325,end:1354,region:"africa",cat:"人物",rank:3,course:["tankyu"],related:["『大旅行記（三大陸周遊記）』","マンサ=ムーサ","イスラーム・ネットワーク"]},
  {term:"イブン=ルシュド",yomi:"イブン=ルシュド",def:"コルドバ出身のイスラーム哲学者・医学者。ラテン名アヴェロエス。アリストテレスの著作に注釈をつけ、そのラテン語訳はスコラ学に大きな影響を与えた。",year:1126,end:1198,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["アリストテレス","コルドバ","スコラ学"]},
  {term:"イベリア半島",yomi:"イベリアはんとう",def:"ヨーロッパ南西部の半島で、現在のスペイン・ポルトガルがある。8世紀にイスラーム勢力に征服され、後ウマイヤ朝などが栄えたが、キリスト教徒によるレコンキスタで奪回された。",region:"europe",cat:"地名・地域",rank:2,course:["tankyu"],related:["レコンキスタ","後ウマイヤ朝","スペイン"]},
  {term:"イマームのモスク",yomi:"イマームのモスク",def:"サファヴィー朝のアッバース1世が新都イスファハーンの広場に建てたモスク。美しい彩釉タイルで装飾された、イラン=イスラーム建築の代表作である。旧称は王のモスク。",year:1612,region:"west",cat:"文化・学問",rank:1,course:["tankyu"],related:["イスファハーン","アッバース1世","サファヴィー朝"]},
  {term:"イラク戦争",yomi:"イラクせんそう",def:"2003年、大量破壊兵器の保有を理由に、アメリカ・イギリスがイラクを攻撃した戦争。サダム=フセイン政権は崩壊したが、大量破壊兵器は見つからず、イラク国内の混乱が続いた。",year:2003,region:"west",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["サダム=フセイン","同時多発テロ事件","湾岸戦争"]},
  {term:"イラク革命",yomi:"イラクかくめい",def:"1958年、イラクで軍人が王政を倒した革命。共和政が成立し、イラクは翌年バグダード条約機構を脱退した。",year:1958,region:"west",cat:"事件・戦争",rank:1,course:["tankyu"],related:["イラク","アラブ民族主義","バグダード条約機構"]},
  {term:"イラン",yomi:"イラン",def:"西アジアの国。古くからペルシアとよばれ、1935年にパフレヴィー朝のレザー=シャーが国号をイランと改めた。1979年のイラン革命でイスラーム共和国となった。",region:"west",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["レザー=ハーン","パフレヴィー朝","イラン革命"]},
  {term:"イラン=イスラーム共和国",yomi:"イラン=イスラームきょうわこく",def:"1979年のイラン革命によって成立した国家。ホメイニを最高指導者とし、シーア派の法学者が国家を指導するイスラーム体制をとった。アメリカと対立した。",year:1979,region:"west",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["イラン革命","ホメイニ","シーア派"]},
  {term:"イラン=イスラーム文化",yomi:"イラン=イスラームぶんか",def:"イランの伝統文化とイスラーム文化が融合した文化。サーマーン朝のころからペルシア語文学が復興し、イル=ハン国やサファヴィー朝のもとで細密画（ミニアチュール）や建築が発達した。",region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["サーマーン朝","ペルシア語","ミニアチュール"]},
  {term:"イラン=イラク戦争",yomi:"イラン=イラクせんそう",def:"1980年、イラクのサダム=フセイン政権がイラン革命の混乱に乗じてイランに侵攻した戦争。1988年に停戦した。戦後、イラクの財政難がクウェート侵攻の背景となった。",year:1980,end:1988,region:"west",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["イラン革命","サダム=フセイン","湾岸戦争"]},
  {term:"イラン立憲革命",yomi:"イランりっけんかくめい",def:"1905年、カージャール朝の専制と外国の利権獲得に反対しておこった革命。1906年に議会が開かれ憲法が制定されたが、ロシア・イギリスの干渉で1911年に挫折した。",year:1905,end:1911,region:"west",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["カージャール朝","日露戦争","青年トルコ革命"]},
  {term:"イラン革命",yomi:"イランかくめい",def:"1979年、パフレヴィー朝の国王による上からの近代化（白色革命）と独裁に反対しておこった革命。国王は亡命し、ホメイニを指導者とするイスラーム共和国が成立した。第2次石油危機をひきおこした。",year:1979,region:"west",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["ホメイニ","パフレヴィー朝","第2次石油危機"]},
  {term:"イリ地方",yomi:"イリちほう",def:"中央アジア東部、イリ川流域の地方。古くは烏孫の根拠地であった。清の支配下にあったが、19世紀にロシアが一時占領し、1881年のイリ条約で大部分が清に返還された。",region:"inner",cat:"地名・地域",rank:1,course:["tankyu"],related:["イリ条約","烏孫","清"]},
  {term:"イル=ハン国",yomi:"イル=ハンこく",def:"モンゴルのフレグがアッバース朝を滅ぼしてイランにたてた国。第7代のガザン=ハンがイスラームに改宗し、宰相ラシード=アッディーンを用いて改革を行った。",year:1258,end:1353,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["フレグ","ガザン=ハン","ラシード=アッディーン"]},
  {term:"インカ帝国",yomi:"インカていこく",def:"15世紀にアンデス地帯を統一した帝国。都クスコを中心に道路網を整え、キープ（結縄）で情報を記録した。1533年にスペインのピサロに征服された。",year:1438,end:1533,region:"america",cat:"国家・王朝",rank:3,course:["tankyu"],related:["ピサロ","クスコ","キープ","アンデス文明"]},
  {term:"インターネット",yomi:"インターネット",def:"世界中のコンピュータを結ぶ通信網。アメリカの軍事研究から生まれ、1990年代に民間で普及した。情報の大量・瞬時の流通を可能にし、グローバル化を加速させた。",year:1990,region:"america",cat:"経済・社会",rank:2,course:["sogo","tankyu"],related:["グローバル化","情報通信技術","アラブの春"]},
  {term:"インディアス",yomi:"インディアス",def:"大航海時代のスペイン人が、アメリカ大陸やその周辺を指して用いた呼び名。コロンブスが到達地をインドと考えたことに由来する。ラス=カサスは『インディアスの破壊についての簡潔な報告』を著した。",region:"america",cat:"地名・地域",rank:1,course:["tankyu"],related:["ラス=カサス","コロンブス","インディオ"]},
  {term:"インディオ",yomi:"インディオ",def:"ラテンアメリカの先住民をさすスペイン語の呼び名。スペインの征服後、エンコミエンダ制のもとで鉱山や農園で酷使され、ヨーロッパから持ちこまれた伝染病もあって人口が激減した。",region:"america",cat:"経済・社会",rank:2,course:["tankyu"],related:["エンコミエンダ制","ラス=カサス","コロンブス"]},
  {term:"インド=イスラーム文化",yomi:"インド=イスラームぶんか",def:"インド古来の文化とイスラーム文化が融合した文化。ムガル帝国のもとで栄え、タージ=マハルなどの建築、細密画、ウルドゥー語、シク教などを生んだ。",region:"south",cat:"文化・学問",rank:3,course:["tankyu"],related:["ムガル帝国","タージ=マハル","シク教","ウルドゥー語"]},
  {term:"インド=ヨーロッパ語系",yomi:"インド=ヨーロッパごけい",def:"インドからヨーロッパにかけて分布する諸言語の系統。ヒッタイト人・アーリヤ人・イラン人・ギリシア人・ゲルマン人などがこの系統の言語を話した。",region:"europe",cat:"経済・社会",rank:2,course:["tankyu"],related:["ヒッタイト","アーリヤ人","ギリシア人"]},
  {term:"インドの独立",yomi:"インドのどくりつ",def:"1947年、インドがイギリスから独立したこと。インド独立法にもとづき、ヒンドゥー教徒が多数のインドと、ムスリムが多数のパキスタンに分かれて独立した。",year:1947,region:"south",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["ガンディー","ネルー","インド・パキスタンの分離独立"]},
  {term:"インドシナ共産党",yomi:"インドシナきょうさんとう",def:"1930年、ホー=チ=ミンが結成した共産党（当初はベトナム共産党）。フランスからの独立をめざし、1941年にはベトナム独立同盟（ベトミン）を組織した。",year:1930,region:"sea",cat:"組織・運動",rank:2,course:["tankyu"],related:["ホー=チ=ミン","ベトナム独立同盟","インドシナ戦争"]},
  {term:"インドシナ戦争",yomi:"インドシナせんそう",def:"ベトナム民主共和国と、植民地支配の回復をはかるフランスとの戦争。1954年にディエンビエンフーでフランス軍が大敗し、ジュネーヴ休戦協定が結ばれた。",year:1946,end:1954,region:"sea",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["ジュネーヴ休戦協定","ホー=チ=ミン","ディエンビエンフー"]},
  {term:"インドシナ連邦",yomi:"インドシナれんぽう",def:"1887年、フランスがベトナムとカンボジアを合わせて成立させた植民地。1899年にラオスも加えた。総督府はハノイに置かれた。",year:1887,end:1945,region:"sea",cat:"国家・王朝",rank:2,course:["tankyu"],related:["清仏戦争","フランス","ベトナム"]},
  {term:"インドネシア国民党",yomi:"インドネシアこくみんとう",def:"1927年、スカルノらが結成した民族主義政党。オランダからの完全独立をかかげ、民族運動の中心となったが、オランダ当局に弾圧されてスカルノは逮捕・流刑となった。",year:1927,region:"sea",cat:"組織・運動",rank:2,course:["tankyu"],related:["スカルノ","オランダ領東インド","インドネシア独立"]},
  {term:"インドネシア独立",yomi:"インドネシアどくりつ",def:"1945年、日本の降伏直後にスカルノらがインドネシア共和国の独立を宣言したこと。再支配をはかるオランダとの独立戦争をへて、1949年に独立が認められた。",year:1945,end:1949,region:"sea",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["スカルノ","インドネシア独立宣言","オランダ"]},
  {term:"インドネシア独立宣言",yomi:"インドネシアどくりつせんげん",def:"1945年8月17日、スカルノとハッタが発表したインドネシア共和国の独立宣言。オランダはこれを認めず独立戦争となったが、1949年に独立が承認された。",year:1945,region:"sea",cat:"条約・宣言",rank:1,course:["sogo","tankyu"],related:["スカルノ","インドネシア独立","オランダ"]},
  {term:"インド・パキスタンの分離独立",yomi:"インド・パキスタンのぶんりどくりつ",def:"1947年、イギリス領インドがヒンドゥー教徒中心のインドとムスリム中心のパキスタンに分かれて独立したこと。分離の過程で大規模な住民移動と宗教対立による衝突がおこった。",year:1947,region:"south",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["インドの独立","ジンナー","ガンディー","カシミール問題"]},
  {term:"インド化",yomi:"インドか",def:"東南アジアの諸地域が、インドから宗教・文字・王権の思想・建築などを受け入れたこと。4世紀末から5世紀ころに進み、扶南やチャンパーなどにヒンドゥー教や仏教が広まった。",region:"sea",cat:"文化・学問",rank:2,course:["tankyu"],related:["扶南","チャンパー","ヒンドゥー教"]},
  {term:"インド国民会議",yomi:"インドこくみんかいぎ",def:"1885年、イギリスの協力で結成されたインド人の政治組織。当初は穏健だったが、ベンガル分割令に反発して1906年のカルカッタ大会で4綱領を決議し、反英闘争を指導するようになった。",year:1885,region:"south",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["カルカッタ大会","ガンディー","ネルー","ティラク"]},
  {term:"インド大反乱",yomi:"インドだいはんらん",def:"1857年、東インド会社のインド人傭兵（シパーヒー）の反乱から始まった反英闘争。全インドに広がったが鎮圧された。イギリスはムガル帝国を滅ぼし、東インド会社を解散して直接統治を始めた。",year:1857,end:1859,region:"south",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["シパーヒー","ムガル帝国","インド帝国"]},
  {term:"インド帝国",yomi:"インドていこく",def:"1877年、イギリスのヴィクトリア女王がインド皇帝を兼ねて成立した、イギリス領インドの体制。1947年のインド・パキスタンの独立まで続いた。",year:1877,end:1947,region:"south",cat:"国家・王朝",rank:3,course:["sogo","tankyu"],related:["ヴィクトリア女王","インド大反乱","ディズレーリ"]},
  {term:"インド数字",yomi:"インドすうじ",def:"インドで生まれた数字と記数法。ゼロの概念と位取りの方法をもち、イスラーム世界に伝わってアラビア数字となり、ヨーロッパに広まった。",region:"south",cat:"文化・学問",rank:1,course:["tankyu"],related:["ゼロの概念","フワーリズミー","アラビア数字"]},
  {term:"インド洋交易",yomi:"インドようこうえき",def:"インド洋を舞台に、季節風を利用して行われた交易。ダウ船を用いたムスリム商人が東アフリカから東南アジア・中国までを結び、東アフリカにはスワヒリ文化が生まれた。",region:"south",cat:"経済・社会",rank:2,course:["tankyu"],related:["ダウ船","ムスリム商人","季節風貿易","スワヒリ文化"]},
  {term:"インド系移民",yomi:"インドけいいみん",def:"19世紀、奴隷制廃止後の労働力不足を補うため、イギリス植民地などへ契約労働者として渡ったインド人。カリブ海・南アフリカ・東南アジアなどに定住した。",region:"south",cat:"経済・社会",rank:1,course:["tankyu"],related:["奴隷制廃止","年季契約労働者","ガンディー"]},
  {term:"インド航路",yomi:"インドこうろ",def:"ヨーロッパからアフリカ南端の喜望峰を回ってインドに至る航路。1498年、ポルトガルのヴァスコ=ダ=ガマがカリカットに到達して開拓し、香辛料の直接取引が可能になった。",year:1498,region:"africa",cat:"事件・戦争",rank:3,course:["tankyu"],related:["ヴァスコ=ダ=ガマ","喜望峰","カリカット","エンリケ航海王子"]},
  {term:"インフレーション",yomi:"インフレーション",def:"物価が継続して上昇し、貨幣の価値が下がること。ドイツでは1923年のフランスによるルール占領を機に天文学的なインフレーションがおこり、シュトレーゼマン政権が新紙幣レンテンマルクで収束させた。",year:1923,region:"europe",cat:"経済・社会",rank:2,course:["sogo","tankyu"],related:["ヴァイマル共和国","ルール占領","シュトレーゼマン"]},
  {term:"イヴァン3世",yomi:"イヴァンさんせい",def:"モスクワ大公。1480年にキプチャク=ハン国の支配から自立した。ビザンツ皇帝の姪と結婚し、ツァーリの称号を用いはじめた。",year:1462,end:1505,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["モスクワ大公国","ツァーリ","キプチャク=ハン国"]},
  {term:"イヴァン4世",yomi:"イヴァンよんせい",def:"モスクワ大公で、正式にツァーリの称号を用いた。大貴族をおさえて専制政治をしき、「雷帝」とよばれた。カザン=ハン国を征服し、シベリアへの進出を始めた。",year:1533,end:1584,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["ツァーリ","カザン=ハン国","シベリア"]},
  {term:"ウィクリフ",yomi:"ウィクリフ",def:"14世紀イギリスの神学者。聖書を信仰の根本とし、教会の腐敗を批判して聖書を英語に訳した。その主張はベーメンのフスに影響を与え、宗教改革の先駆となった。",year:1320,end:1384,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["フス","宗教改革","聖書"]},
  {term:"ウィーン会議",yomi:"ウィーンかいぎ",def:"ナポレオン戦争後のヨーロッパの秩序を再建するため、1814〜15年に開かれた国際会議。オーストリアのメッテルニヒが議長をつとめ、正統主義と勢力均衡を原則とするウィーン議定書を結んだ。",year:1814,end:1815,region:"europe",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["メッテルニヒ","ウィーン体制","正統主義"]},
  {term:"ウィーン体制",yomi:"ウィーンたいせい",def:"ウィーン会議で成立したヨーロッパの国際秩序。正統主義と勢力均衡を原則とし、四国同盟などで自由主義・ナショナリズムをおさえたが、1848年革命で崩壊した。",year:1815,end:1848,region:"europe",cat:"制度・政策",rank:3,course:["sogo","tankyu"],related:["ウィーン会議","メッテルニヒ","1848年革命","四国同盟"]},
  {term:"ウィーン包囲",yomi:"ウィーンほうい",def:"オスマン帝国によるウィーン包囲。1529年にスレイマン1世が第1次包囲を行い、ヨーロッパに脅威を与えた。1683年の第2次包囲は失敗し、オスマン帝国の後退が始まった。",year:1529,end:1683,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["スレイマン1世","オスマン帝国","カルロヴィッツ条約"]},
  {term:"ウイグル",yomi:"ウイグル",def:"トルコ系の遊牧民族。744年に突厥を滅ぼしてモンゴル高原に国家をたて、安史の乱では唐を助けた。ソグド人の影響でマニ教を信仰したが、840年キルギスに敗れて四散した。",year:744,end:840,region:"inner",cat:"国家・王朝",rank:3,course:["tankyu"],related:["突厥","安史の乱","キルギス","ソグド人"]},
  {term:"ウェストファリア条約",yomi:"ウェストファリアじょうやく",def:"1648年、三十年戦争を終結させた講和条約。カルヴァン派が公認され、スイス・オランダの独立が承認された。ドイツの諸邦がほぼ完全な主権を認められ、ヨーロッパの主権国家体制が確立した。",year:1648,region:"europe",cat:"条約・宣言",rank:3,course:["tankyu"],related:["三十年戦争","主権国家体制","神聖ローマ帝国"]},
  {term:"ウェストミンスター憲章",yomi:"ウェストミンスターけんしょう",def:"1931年、イギリス議会が制定した法律。カナダ・オーストラリアなどの自治領を本国と対等の地位にあると認め、イギリス連邦が成立した。",year:1931,region:"europe",cat:"条約・宣言",rank:2,course:["sogo","tankyu"],related:["イギリス連邦","カナダ","アイルランド自由国"]},
  {term:"ウォーターゲート事件",yomi:"ウォーターゲートじけん",def:"1972年、ニクソン大統領の再選委員会の関係者が、民主党本部に盗聴器を仕掛けようとした事件。大統領のもみ消し工作が発覚し、1974年にニクソンは辞任した。",year:1972,end:1974,region:"america",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ニクソン","ベトナム戦争"]},
  {term:"ウガンダ鉄道",yomi:"ウガンダてつどう",def:"イギリスが東アフリカのモンバサからヴィクトリア湖まで建設した鉄道。工事にはインド人労働者が多く用いられ、ケニアの植民地化を進めた。",year:1896,end:1901,region:"africa",cat:"経済・社会",rank:1,course:["tankyu"],related:["ケニア","イギリス","アフリカ分割"]},
  {term:"ウクライナ侵攻",yomi:"ウクライナしんこう",def:"2022年、ロシアがウクライナに対して開始した全面的な軍事侵攻。2014年のクリミア併合以来の対立が背景にあり、国際社会はロシアに経済制裁を科した。",year:2022,region:"europe",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ロシア","NATO","クリミア"]},
  {term:"ウズベク",yomi:"ウズベク",def:"トルコ系の遊牧集団。16世紀初めにティムール朝を滅ぼしてシャイバーニー朝をたて、のちブハラ・ヒヴァ・コーカンドの3ハン国が分立した。",region:"inner",cat:"国家・王朝",rank:2,course:["tankyu"],related:["ティムール朝","シャイバーニー朝","ブハラ=ハン国"]},
  {term:"ウマイヤ朝",yomi:"ウマイヤちょう",def:"661年、ムアーウィヤがダマスクスを都として開いたイスラーム王朝。カリフ位を世襲化し、イベリア半島から中央アジアにまで領土を広げたが、アラブ人優遇への不満から750年に倒された。",year:661,end:750,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["ムアーウィヤ","ダマスクス","アッバース朝","トゥール・ポワティエ間の戦い"]},
  {term:"ウラディミル1世",yomi:"ウラディミルいっせい",def:"キエフ公国の君主。988年ころギリシア正教に改宗し、これを国教とした。以後ロシアはビザンツ文化の影響を強く受けた。",year:980,end:1015,region:"europe",cat:"人物",rank:1,course:["tankyu"],related:["キエフ公国","ギリシア正教","ビザンツ帝国"]},
  {term:"ウラービー運動",yomi:"ウラービーうんどう",def:"1881年、エジプトの軍人ウラービーが「エジプト人のためのエジプト」を唱えておこした民族運動。立憲制と外国支配の排除を求めたが、イギリス軍に鎮圧され、エジプトは事実上イギリスの保護下に入った。",year:1881,end:1882,region:"africa",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["エジプト","スエズ運河","イギリス"]},
  {term:"ウル",yomi:"ウル",def:"メソポタミア南部のシュメール人の都市国家。前3千年紀に繁栄し、ウル第3王朝はウル=ナンム法典を定めた。大規模なジッグラトの遺構が残る。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["シュメール人","ウル=ナンム法典","ジッグラト"]},
  {term:"ウル=ナンム法典",yomi:"ウル=ナンムほうてん",def:"ウル第3王朝の創始者ウル=ナンムが定めたとされる法典。ハンムラビ法典より古い、現存最古の法典の一つである。",year:-2100,region:"west",cat:"文化・学問",rank:1,course:["tankyu"],related:["ウル","シュメール人","ハンムラビ法典"]},
  {term:"ウルク",yomi:"ウルク",def:"メソポタミア南部のシュメール人の都市国家。前4千年紀後半に大規模な都市が成立し、初期の文字資料が出土した。ギルガメシュ叙事詩の主人公はこの都市の王とされる。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["シュメール人","くさび形文字","ギルガメシュ叙事詩"]},
  {term:"ウルグ=ベク",yomi:"ウルグ=ベク",def:"ティムール朝の君主で、ティムールの孫。学問を保護し、サマルカンドに天文台を建てて精密な天文表をつくった。",year:1447,end:1449,region:"inner",cat:"人物",rank:1,course:["tankyu"],related:["ティムール朝","サマルカンド","天文台"]},
  {term:"ウルバヌス2世",yomi:"ウルバヌスにせい",def:"ローマ教皇。ビザンツ皇帝の救援要請を受け、1095年のクレルモン宗教会議で聖地イェルサレム奪回のための十字軍をよびかけた。",year:1088,end:1099,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["クレルモン宗教会議","十字軍","クリュニー修道院"]},
  {term:"ウンマ",yomi:"ウンマ",def:"イスラーム教徒の共同体。622年のヒジュラ後、ムハンマドがメディナで建設した。部族や血縁をこえた信仰による結びつきを特徴とする。",year:622,region:"west",cat:"制度・政策",rank:2,course:["tankyu"],related:["ムハンマド","ヒジュラ","メディナ"]},
  {term:"エカチェリーナ2世",yomi:"エカチェリーナにせい",def:"ロシアの女帝。啓蒙専制君主として知られるが、プガチョフの農民反乱後は農奴制を強化した。オスマン帝国からクリミア半島を奪い、ポーランド分割に加わって領土を拡大した。",year:1762,end:1796,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["啓蒙専制君主","ポーランド分割","プガチョフの乱","クリミア半島"]},
  {term:"エクバタナ",yomi:"エクバタナ",def:"イラン高原西部の都市。メディア王国の都であり、アケメネス朝のもとでも王の居所の一つとして重要であった。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["メディア","アケメネス朝"]},
  {term:"エグバート",yomi:"エグバート",def:"ウェセックス王。829年ころアングロ=サクソンの七王国をほぼ統一し、イングランド王国の基礎を築いた。",year:802,end:839,region:"europe",cat:"人物",rank:1,course:["tankyu"],related:["アングロ=サクソン人","七王国","イングランド"]},
  {term:"エジプト",yomi:"エジプト",def:"アフリカ北東部の国。ナイル川流域に古代文明が栄え、のちイスラーム諸王朝やオスマン帝国の支配を受けた。1882年にイギリスの保護下に入り、1922年に王国として独立し、1952年のエジプト革命で共和国となった。",region:"africa",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["ナイル川","エジプト革命","スエズ運河"]},
  {term:"エジプト=イスラエル平和条約",yomi:"エジプト=イスラエルへいわじょうやく",def:"1979年、アメリカの仲介でエジプトとイスラエルが結んだ平和条約。エジプトはアラブ諸国で初めてイスラエルを承認し、シナイ半島の返還を受けた。サダト大統領はのちに暗殺された。",year:1979,region:"west",cat:"条約・宣言",rank:2,course:["sogo","tankyu"],related:["サダト","キャンプ=デーヴィッド合意","第4次中東戦争"]},
  {term:"エジプト=トルコ戦争",yomi:"エジプト=トルコせんそう",def:"ムハンマド=アリーがシリアの領有を求めてオスマン帝国と2度戦った戦争。列強が介入し、1840年のロンドン会議でエジプト・スーダンの総督位の世襲のみが認められた。",year:1831,end:1840,region:"west",cat:"事件・戦争",rank:2,course:["tankyu"],related:["ムハンマド=アリー","東方問題","ロンドン会議"]},
  {term:"エジプトの近代化",yomi:"エジプトのきんだいか",def:"19世紀前半、ムハンマド=アリーが進めたエジプトの富国強兵策。マムルークを一掃し、西洋式の軍隊・工場・学校をつくり、綿花の専売などで財政を強化した。",year:1805,end:1848,region:"africa",cat:"制度・政策",rank:1,course:["tankyu"],related:["ムハンマド=アリー","エジプト=トルコ戦争","スエズ運河"]},
  {term:"エジプト第25王朝",yomi:"エジプトだいにじゅうごおうちょう",def:"ナイル川上流のクシュ王国がエジプトを征服してたてた王朝。前8世紀後半からエジプトを支配したが、アッシリアの侵攻を受けて南方へ退いた。",year:-747,end:-656,region:"africa",cat:"国家・王朝",rank:1,course:["tankyu"],related:["クシュ王国","アッシリア","メロエ"]},
  {term:"エジプト革命",yomi:"エジプトかくめい",def:"1952年、ナギブやナセルら自由将校団が王政を倒した革命。翌年共和国が成立し、ナセルはのち大統領となってスエズ運河国有化などを行った。",year:1952,region:"west",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ナセル","スエズ運河国有化","アラブ民族主義"]},
  {term:"エセン=ハン",yomi:"エセン=ハン",def:"15世紀半ばのオイラトの指導者。モンゴル高原の支配を広げて明と対立し、1449年の土木の変で明の正統帝を捕虜にした。のち内紛で殺害された。",year:1449,region:"inner",cat:"人物",rank:2,course:["tankyu"],related:["オイラト","土木の変","明"]},
  {term:"エチオピア",yomi:"エチオピア",def:"アフリカ北東部の国。古代のアクスム王国以来キリスト教を受けつぎ、1896年のアドワの戦いでイタリアを破って独立を守った。1935年にイタリアに侵略されたが、1941年に解放された。",region:"africa",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["アドワの戦い","メネリク2世","エチオピア侵攻"]},
  {term:"エチオピア侵攻",yomi:"エチオピアしんこう",def:"1935年、ムッソリーニのイタリアがエチオピアに侵攻し、翌年併合したこと。国際連盟はイタリアに経済制裁を科したが効果は小さく、連盟の無力さが明らかとなった。",year:1935,end:1936,region:"africa",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ムッソリーニ","国際連盟","エチオピア"]},
  {term:"エチオピア侵略",yomi:"エチオピアしんりゃく",def:"エチオピア侵攻と同じ。1935〜36年、ファシスト政権のイタリアがエチオピアを侵略・併合した。国際連盟の経済制裁は石油を対象外とし不十分に終わった。",year:1935,end:1936,region:"africa",cat:"事件・戦争",rank:1,course:["sogo","tankyu"],related:["エチオピア侵攻","ムッソリーニ","国際連盟"]},
  {term:"エチオピア革命",yomi:"エチオピアかくめい",def:"1974年、エチオピアで軍部が皇帝ハイレ=セラシエを廃位した革命。帝政が廃止され、ソ連に接近した社会主義的な軍事政権が成立した。",year:1974,region:"africa",cat:"事件・戦争",rank:1,course:["tankyu"],related:["エチオピア","ハイレ=セラシエ","社会主義"]},
  {term:"エフタル",yomi:"エフタル",def:"5世紀に中央アジアで台頭した遊牧民。ササン朝をおびやかし、グプタ朝の衰退の一因となった。6世紀半ばにササン朝と突厥に挟撃されて滅んだ。",region:"inner",cat:"国家・王朝",rank:2,course:["tankyu"],related:["ササン朝","突厥","グプタ朝"]},
  {term:"エリザベス1世",yomi:"エリザベスいっせい",def:"イングランドの女王。1559年の統一法でイギリス国教会を確立した。1588年にスペインの無敵艦隊を破り、1600年に東インド会社を設立するなど、絶対王政の最盛期を築いた。",year:1558,end:1603,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["統一法","イギリス国教会","無敵艦隊","イギリス東インド会社"]},
  {term:"エリツィン",yomi:"エリツィン",def:"ロシア連邦の初代大統領。1991年の保守派のクーデタに抵抗して指導力を示し、同年のソ連解体とCISの結成を進めた。急速な市場経済化を行った。",year:1991,end:1999,region:"europe",cat:"人物",rank:2,course:["sogo","tankyu"],related:["ソ連の解体","CIS","ゴルバチョフ"]},
  {term:"エローラ",yomi:"エローラ",def:"インドのデカン高原にある石窟寺院群。仏教・ヒンドゥー教・ジャイナ教の石窟があり、ラーシュトラクータ朝が造営したカイラーサナータ寺院が名高い。",region:"south",cat:"文化・学問",rank:1,course:["tankyu"],related:["アジャンター","ヒンドゥー教","ジャイナ教"]},
  {term:"エンクルマ",yomi:"エンクルマ",def:"ガーナの独立運動の指導者で初代大統領。1957年に黄金海岸を指導して、サハラ以南で最初の黒人共和国として独立させた。アフリカ統一機構の結成にも尽力した。",year:1957,end:1966,region:"africa",cat:"人物",rank:3,course:["sogo","tankyu"],related:["ガーナ独立","アフリカ統一機構","パン=アフリカ主義"]},
  {term:"エンゲルス",yomi:"エンゲルス",def:"ドイツの社会主義者。マルクスの協力者として1848年に『共産党宣言』を共同で発表し、マルクスの死後に『資本論』の残りを編集・刊行した。",year:1820,end:1895,region:"europe",cat:"人物",rank:2,course:["sogo","tankyu"],related:["マルクス","『共産党宣言』","社会主義"]},
  {term:"エンコミエンダ制",yomi:"エンコミエンダせい",def:"スペイン国王が植民者に、先住民のキリスト教化を条件として、その支配と労働力利用を委ねた制度。先住民の酷使をまねき、ラス=カサスらに批判された。",year:1503,region:"america",cat:"制度・政策",rank:3,course:["tankyu"],related:["インディオ","ラス=カサス","アシエンダ制"]},
  {term:"エンリケ航海王子",yomi:"エンリケこうかいおうじ",def:"15世紀のポルトガルの王子。アフリカ西岸の探検を積極的に後援し、航海者の育成にも努めて、ポルトガルの海外進出とインド航路開拓の基礎を築いた。",year:1415,end:1460,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["インド航路","ポルトガル","大航海時代"]},
  {term:"エーヤワディー川",yomi:"エーヤワディーがわ",def:"ミャンマー（ビルマ）を南北に流れる川。イラワディ川ともいう。流域にはパガン朝などビルマ人の王朝が栄えた。",region:"sea",cat:"地名・地域",rank:1,course:["tankyu"],related:["パガン朝","ビルマ","コンバウン朝"]},
  {term:"オアシスの道",yomi:"オアシスのみち",def:"中央アジアのオアシス都市を結ぶ東西交易路。中国の絹が西方へ運ばれたためシルクロード（絹の道）ともよばれ、ソグド人などの商人が活躍した。",region:"inner",cat:"地名・地域",rank:2,course:["tankyu"],related:["シルクロード","オアシス都市","ソグド人"]},
  {term:"オアシス都市",yomi:"オアシスとし",def:"中央アジアの乾燥地帯で、泉や河川の水が得られる地に発達した都市。東西交易の中継地として栄え、サマルカンドや敦煌などがある。",region:"inner",cat:"地名・地域",rank:2,course:["tankyu"],related:["オアシスの道","ソグド人","サマルカンド"]},
  {term:"オイラト",yomi:"オイラト",def:"モンゴル系の遊牧集団。15世紀にエセン=ハンのもとで強大となり、土木の変で明の皇帝を捕らえた。17世紀にはその一部族からジュンガルが台頭した。",region:"inner",cat:"国家・王朝",rank:2,course:["tankyu"],related:["エセン=ハン","土木の変","ジュンガル"]},
  {term:"オケオ",yomi:"オケオ",def:"メコン川下流域にある扶南の港市の遺跡。ローマの金貨やインドの神像、漢の鏡などが出土し、東西交易の拠点であったことを示している。",region:"sea",cat:"地名・地域",rank:1,course:["tankyu"],related:["扶南","インド化","港市国家"]},
  {term:"オゴタイ",yomi:"オゴタイ",def:"モンゴル帝国第2代皇帝オゴデイの別表記。金を滅ぼし、都カラコルムを建設した。",year:1229,end:1241,region:"inner",cat:"人物",rank:1,course:["tankyu"],related:["オゴデイ","モンゴル帝国","カラコルム"]},
  {term:"オゴデイ",yomi:"オゴデイ",def:"モンゴル帝国第2代皇帝で、チンギス=カンの子。1234年に金を滅ぼし、都カラコルムを建設した。バトゥにヨーロッパ遠征を行わせ、ジャムチ（駅伝制）を整えた。",year:1229,end:1241,region:"inner",cat:"人物",rank:2,course:["tankyu"],related:["チンギス=カン","カラコルム","バトゥ","金"]},
  {term:"オスマン帝国",yomi:"オスマンていこく",def:"13世紀末にアナトリアに建国されたトルコ系イスラーム国家。1453年にビザンツ帝国を滅ぼし、16世紀のスレイマン1世のとき最盛期を迎えた。19世紀には東方問題で列強に圧迫され、1922年に滅亡した。",year:1299,end:1922,region:"west",cat:"国家・王朝",rank:3,course:["sogo","tankyu"],related:["スレイマン1世","メフメト2世","イェニチェリ","タンジマート"]},
  {term:"オスロ合意",yomi:"オスロごうい",def:"1993年、ノルウェーの仲介でイスラエルとPLOが結んだ合意。相互承認とパレスチナ暫定自治の開始が定められたが、その後も和平は進まなかった。",year:1993,region:"west",cat:"条約・宣言",rank:3,course:["sogo","tankyu"],related:["PLO","アラファト","パレスチナ問題"]},
  {term:"オットー1世",yomi:"オットーいっせい",def:"東フランク王（ドイツ王）。955年のレヒフェルトの戦いでマジャール人を破り、962年に教皇からローマ皇帝の冠を受けた。これが神聖ローマ帝国の始まりとされる。",year:936,end:973,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["神聖ローマ帝国","レヒフェルトの戦い","マジャール人"]},
  {term:"オドアケル",yomi:"オドアケル",def:"ゲルマン人の傭兵隊長。476年に西ローマ皇帝ロムルス=アウグストゥルスを退位させ、西ローマ帝国を滅ぼした。のち東ゴートのテオドリックに倒された。",year:476,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["西ローマ帝国","東ゴート人","ゲルマン人の大移動"]},
  {term:"オランダ",yomi:"オランダ",def:"ヨーロッパ北西部の国。スペインからの独立戦争をへて1581年に独立を宣言し、17世紀には東インド会社などを通じてアジア貿易を支配し、アムステルダムが国際金融の中心となった。",year:1581,region:"europe",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["オランダ独立戦争","オランダ東インド会社","アムステルダム"]},
  {term:"オランダ東インド会社",yomi:"オランダひがしインドがいしゃ",def:"1602年に設立されたオランダの貿易会社。世界初の株式会社といわれ、ジャワ島のバタヴィアを拠点として香辛料貿易を支配した。アンボイナ事件でイギリス勢力を排除した。",year:1602,end:1799,region:"sea",cat:"組織・運動",rank:3,course:["tankyu"],related:["バタヴィア","アンボイナ事件","オランダ"]},
  {term:"オランダ独立戦争",yomi:"オランダどくりつせんそう",def:"スペインのフェリペ2世の支配に対し、ネーデルラントのカルヴァン派などがおこした戦争。北部7州はユトレヒト同盟を結んで1581年に独立を宣言し、1648年のウェストファリア条約で国際的に承認された。",year:1568,end:1609,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["フェリペ2世","ユトレヒト同盟","ウェストファリア条約"]},
  {term:"オランダ領東インド",yomi:"オランダりょうひがしインド",def:"オランダ東インド会社の解散後に成立した、現在のインドネシアにあたるオランダの植民地。強制栽培制度で多くの利益をあげた。第二次世界大戦中は日本に占領され、戦後インドネシアとして独立した。",year:1800,end:1942,region:"sea",cat:"国家・王朝",rank:2,course:["tankyu"],related:["強制栽培制度","スカルノ","インドネシア独立"]},
  {term:"オリエント統一",yomi:"オリエントとういつ",def:"古代オリエント世界を一つの国家がまとめたこと。前7世紀にアッシリアが初めてこれを実現し、前6世紀にはアケメネス朝がより大規模に統一した。",year:-670,region:"west",cat:"事件・戦争",rank:1,course:["tankyu"],related:["アッシリア","アケメネス朝","4王国分立"]},
  {term:"オルホン碑文",yomi:"オルホンひぶん",def:"モンゴル高原のオルホン川流域で発見された、突厥文字で書かれた碑文。8世紀の突厥の歴史を伝え、遊牧民がつくった最古の文字資料の一つである。",region:"inner",cat:"文化・学問",rank:1,course:["tankyu"],related:["突厥","突厥文字","ウイグル"]},
  {term:"オルメカ文明",yomi:"オルメカぶんめい",def:"前1200年ころからメキシコ湾岸に栄えた、メソアメリカ最古の文明。巨石人頭像やジャガー信仰で知られ、のちの文明に影響を与えた。",year:-1200,end:-400,region:"america",cat:"文化・学問",rank:2,course:["tankyu"],related:["メソアメリカ文明","ジャガー信仰","マヤ文明"]},
  {term:"オルレアン",yomi:"オルレアン",def:"フランス中部の都市。百年戦争中の1429年、イギリス軍に包囲されたが、ジャンヌ=ダルクの活躍で解放され、フランスの反撃のきっかけとなった。",year:1429,region:"europe",cat:"地名・地域",rank:1,course:["tankyu"],related:["ジャンヌ=ダルク","百年戦争","シャルル7世"]},
  {term:"オーストリア併合",yomi:"オーストリアへいごう",def:"1938年、ナチス=ドイツがオーストリアを併合したこと。ヒトラーはドイツ民族の統合を名目とし、続いてチェコスロヴァキアのズデーテン地方を要求した。",year:1938,region:"europe",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ヒトラー","ミュンヘン会談","ナチ党"]},
  {term:"オーストリア国家条約",yomi:"オーストリアこっかじょうやく",def:"1955年、米英仏ソの4か国とオーストリアの間で結ばれた条約。連合国による占領が終わり、オーストリアは永世中立国として主権を回復した。",year:1955,region:"europe",cat:"条約・宣言",rank:1,course:["tankyu"],related:["永世中立","冷戦","雪どけ"]},
  {term:"オーストリア継承戦争",yomi:"オーストリアけいしょうせんそう",def:"1740年、マリア=テレジアのハプスブルク家継承に対し、プロイセンなどが異議を唱えておこった戦争。プロイセンのフリードリヒ2世はシュレジエンを獲得した。",year:1740,end:1748,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["マリア=テレジア","フリードリヒ2世","シュレジエン"]},
  {term:"カアン（大ハーン）",yomi:"カアン（だいハーン）",def:"モンゴル帝国の皇帝の称号。オゴデイ以降の皇帝が名のり、各地のハン国の君主（ハン）の上に立つ存在とされた。",region:"inner",cat:"制度・政策",rank:1,course:["tankyu"],related:["モンゴル帝国","クビライ","クリルタイ"]},
  {term:"カイラワーン",yomi:"カイラワーン",def:"チュニジアの都市。7世紀にアラブの軍営都市として建設され、北アフリカにおけるイスラームの拠点となった。",year:670,region:"africa",cat:"地名・地域",rank:1,course:["tankyu"],related:["ウマイヤ朝","アグラブ朝","イスラーム"]},
  {term:"カイロ",yomi:"カイロ",def:"ナイル川下流の都市。969年にファーティマ朝が建設し、マムルーク朝のもとでイスラーム世界の政治・経済・文化の中心として繁栄した。",year:969,region:"africa",cat:"地名・地域",rank:2,course:["tankyu"],related:["ファーティマ朝","マムルーク朝","アズハル=モスク"]},
  {term:"カイロネイアの戦い",yomi:"カイロネイアのたたかい",def:"前338年、マケドニアのフィリッポス2世がアテネ・テーベの連合軍を破った戦い。マケドニアはギリシアの覇権をにぎり、コリントス同盟を結成した。",year:-338,region:"europe",cat:"事件・戦争",rank:2,course:["tankyu"],related:["マケドニア","フィリッポス2世","コリントス同盟"]},
  {term:"カウンダ",yomi:"カウンダ",def:"ザンビアの独立運動の指導者で、1964年の独立から1991年まで初代大統領をつとめた。",year:1964,end:1991,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["ザンビア","アフリカの年"]},
  {term:"カエサル",yomi:"カエサル",def:"古代ローマの政治家・軍人。ポンペイウス・クラッススと第1回三頭政治を行い、ガリア遠征で名声を得た。独裁官として権力を握ったが、前44年に暗殺された。ユリウス暦を定めた。",year:-60,end:-44,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["第1回三頭政治","ガリア遠征","ユリウス暦","クレオパトラ"]},
  {term:"カカオ",yomi:"カカオ",def:"チョコレートの原料となる作物。アメリカ大陸原産で、植民地時代以降西アフリカで大規模に栽培され、ガーナなどのモノカルチャー経済を形づくった。",region:"africa",cat:"経済・社会",rank:1,course:["tankyu"],related:["モノカルチャー経済","ガーナ独立","プランテーション"]},
  {term:"カザフ",yomi:"カザフ",def:"トルコ系の遊牧集団。15世紀にウズベクから分かれて中央アジアの草原地帯で勢力を築いたが、18〜19世紀にロシアに服属した。",region:"inner",cat:"国家・王朝",rank:1,course:["tankyu"],related:["ウズベク","中央アジア","ロシア"]},
  {term:"カシミール問題",yomi:"カシミールもんだい",def:"インドとパキスタンの間のカシミール地方の帰属をめぐる紛争。分離独立の際、住民の多くがムスリムなのに藩王がヒンドゥー教徒であったため紛争となり、たびたび戦争がおこった。",year:1947,region:"south",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["インド・パキスタンの分離独立","インド=パキスタン戦争"]},
  {term:"カジミェシュ大王",yomi:"カジミェシュだいおう",def:"ポーランド王。国内の統一と法の整備を進め、1364年にクラクフ大学を創設した。ユダヤ人を保護したことでも知られる。",year:1333,end:1370,region:"europe",cat:"人物",rank:1,course:["tankyu"],related:["ポーランド","クラクフ大学"]},
  {term:"カスティリャ王国",yomi:"カスティリャおうこく",def:"イベリア半島中央部のキリスト教国。レコンキスタの中心となって領土を南へ広げた。1479年、イサベルとフェルナンドの結婚を機にアラゴン王国と合同してスペイン王国となった。",year:1035,end:1479,region:"europe",cat:"国家・王朝",rank:2,course:["tankyu"],related:["イサベル","レコンキスタ","アラゴン王国"]},
  {term:"カストロ",yomi:"カストロ",def:"キューバの革命家・政治家。1959年にゲバラらとともに親米のバティスタ政権を倒し、のち社会主義を宣言してソ連に接近した。キューバ危機の際の首相であった。",year:1959,end:2008,region:"america",cat:"人物",rank:3,course:["sogo","tankyu"],related:["キューバ革命","キューバ危機","ゲバラ"]},
  {term:"カタラウヌムの戦い",yomi:"カタラウヌムのたたかい",def:"451年、北フランスのカタラウヌムで、西ローマ帝国とゲルマン人の連合軍がアッティラの率いるフン人を破った戦い。フン人の西進は阻まれ、アッティラの死後その勢力は崩壊した。",year:451,region:"europe",cat:"事件・戦争",rank:2,course:["tankyu"],related:["アッティラ","フン人","西ローマ帝国"]},
  {term:"カタンガ",yomi:"カタンガ",def:"コンゴ南部の銅などの鉱産資源が豊かな州。1960年のコンゴ独立直後、ベルギーの支援で分離独立を宣言し、コンゴ動乱の一因となった。",year:1960,region:"africa",cat:"地名・地域",rank:1,course:["tankyu"],related:["コンゴ動乱","ベルギー"]},
  {term:"カダフィ",yomi:"カダフィ",def:"リビアの軍人・政治家。1969年のクーデタで王政を倒し、長期独裁を行った。2011年の「アラブの春」の際の内戦で殺害された。",year:1969,end:2011,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["リビア","アラブの春"]},
  {term:"カッシート人",yomi:"カッシートじん",def:"ザグロス山脈方面からメソポタミアに進出した民族。前16世紀ころバビロン第1王朝の滅亡後にバビロニアを支配した。",year:-1600,region:"west",cat:"国家・王朝",rank:1,course:["tankyu"],related:["バビロン第1王朝","ヒッタイト","アマルナ文書"]},
  {term:"カデシュの戦い",yomi:"カデシュのたたかい",def:"前13世紀、エジプト新王国のラメス2世とヒッタイトがシリアのカデシュで戦った戦い。勝敗はつかず、のちに両国は世界最古の平和条約といわれる条約を結んだ。",year:-1286,region:"west",cat:"事件・戦争",rank:2,course:["tankyu"],related:["ラメス2世","ヒッタイト","新王国"]},
  {term:"カトリック",yomi:"カトリック",def:"ローマ教皇を首長とするキリスト教の教派。「普遍的」の意。中世西ヨーロッパで大きな権威をもち、宗教改革後も対抗宗教改革を進めて南欧やラテンアメリカ、フィリピンなどに広まった。",region:"europe",cat:"思想・宗教",rank:2,course:["sogo","tankyu"],related:["ローマ教皇","宗教改革","イエズス会"]},
  {term:"カナウジ",yomi:"カナウジ",def:"北インドのガンジス川流域の都市。7世紀にヴァルダナ朝のハルシャ王が都とし、その後もプラティハーラ朝の都として栄えた。",region:"south",cat:"地名・地域",rank:1,course:["tankyu"],related:["ヴァルダナ朝","ハルシャ王","プラティハーラ朝"]},
  {term:"カニシカ王",yomi:"カニシカおう",def:"2世紀ころのクシャーナ朝の最盛期の王。中央アジアから北インドにわたる地域を支配し、仏教を保護した。その時代にガンダーラ美術や大乗仏教が発展した。",region:"south",cat:"人物",rank:3,course:["tankyu"],related:["クシャーナ朝","ガンダーラ美術","大乗仏教"]},
  {term:"カノッサの屈辱",yomi:"カノッサのくつじょく",def:"1077年、叙任権闘争で教皇グレゴリウス7世に破門された神聖ローマ皇帝ハインリヒ4世が、北イタリアのカノッサで許しを請うたできごと。教皇権の強さを示した。",year:1077,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["叙任権闘争","グレゴリウス7世","ハインリヒ4世"]},
  {term:"カピチュレーション",yomi:"カピチュレーション",def:"オスマン帝国がヨーロッパ諸国の商人に与えた通商上の特権。領事裁判権などを含み、16世紀にはフランスに与えられた。のちに列強の進出に利用され、不平等条約の性格をもった。",year:1535,region:"west",cat:"制度・政策",rank:2,course:["tankyu"],related:["オスマン帝国","スレイマン1世","不平等条約"]},
  {term:"カブラル",yomi:"カブラル",def:"ポルトガルの航海者。1500年、インドへ向かう途中で大西洋を西に流されてブラジルに漂着し、ポルトガル領と宣言した。その後ブラジルはポルトガルの植民地となった。",year:1500,region:"america",cat:"人物",rank:2,course:["tankyu"],related:["ブラジル","ポルトガル","インド航路"]},
  {term:"カペー朝",yomi:"カペーちょう",def:"987年、ユーグ=カペーがフランス王に選ばれて開いた王朝。当初の王権は弱かったが、フィリップ2世・ルイ9世・フィリップ4世らのもとで王権が強化された。1328年にヴァロワ朝にかわった。",year:987,end:1328,region:"europe",cat:"国家・王朝",rank:3,course:["tankyu"],related:["フィリップ2世","フィリップ4世","ヴァロワ朝"]},
  {term:"カラキタイ",yomi:"カラキタイ",def:"西遼ともいう。遼の滅亡に際し、王族の耶律大石が中央アジアに移ってたてた国。カラハン朝を服属させたが、ナイマンに奪われ、のちモンゴルに滅ぼされた。",year:1132,end:1211,region:"inner",cat:"国家・王朝",rank:1,course:["tankyu"],related:["西遼","耶律大石","遼"]},
  {term:"カラコルム",yomi:"カラコルム",def:"モンゴル高原のオルホン川流域に建設されたモンゴル帝国の都。オゴデイが建設し、ジャムチ（駅伝制）によって各地と結ばれた。フビライが大都に遷都すると衰えた。",year:1235,region:"inner",cat:"地名・地域",rank:2,course:["tankyu"],related:["オゴデイ","モンゴル帝国","ジャムチ"]},
  {term:"カラハン朝",yomi:"カラハンちょう",def:"中央アジアにたてられたトルコ系の王朝。10世紀にイスラームを受け入れ、999年にサーマーン朝を滅ぼした。中央アジアのトルコ化・イスラーム化を進めた。",year:940,end:1212,region:"inner",cat:"国家・王朝",rank:2,course:["tankyu"],related:["サーマーン朝","トルコ人","イスラーム化"]},
  {term:"カリカット",yomi:"カリカット",def:"インド西海岸南部の港市。香辛料貿易で栄え、1498年にヴァスコ=ダ=ガマが到達して、ヨーロッパとインドを直接結ぶ航路が開かれた。明の鄭和の艦隊も寄港した。",year:1498,region:"south",cat:"地名・地域",rank:2,course:["tankyu"],related:["ヴァスコ=ダ=ガマ","インド航路","鄭和"]},
  {term:"カリフ",yomi:"カリフ",def:"ムハンマドの後継者で、イスラーム共同体（ウンマ）の最高指導者。アラビア語で「代理人」の意。正統カリフの後、ウマイヤ朝・アッバース朝で世襲された。1924年にトルコ共和国により廃止された。",year:632,end:1924,region:"west",cat:"制度・政策",rank:3,course:["tankyu"],related:["正統カリフ","ウマイヤ朝","アッバース朝","カリフ制廃止"]},
  {term:"カリフの世襲",yomi:"カリフのせしゅう",def:"661年、ムアーウィヤがウマイヤ朝を開き、カリフ位を一族で世襲したこと。選挙で選ばれた正統カリフ時代は終わり、これに反対する人々からシーア派が形成された。",year:661,region:"west",cat:"制度・政策",rank:1,course:["tankyu"],related:["ムアーウィヤ","ウマイヤ朝","正統カリフ"]},
  {term:"カリフ制の廃止",yomi:"カリフせいのはいし",def:"1924年、トルコ共和国のムスタファ=ケマルがカリフ制を廃止したこと。スルタン制はすでに1922年に廃止されており、トルコの政教分離と近代化が進められた。",year:1924,region:"west",cat:"制度・政策",rank:1,course:["sogo","tankyu"],related:["ムスタファ=ケマル","トルコ共和国","政教分離"]},
  {term:"カリフ制廃止",yomi:"カリフせいはいし",def:"カリフ制の廃止と同じ。1924年、トルコ大国民議会がカリフ制を廃止し、ムスタファ=ケマルはイスラームを国教からはずして政教分離を進めた。",year:1924,region:"west",cat:"制度・政策",rank:2,course:["sogo","tankyu"],related:["ムスタファ=ケマル","トルコ共和国","カリフ"]},
  {term:"カリブ海",yomi:"カリブかい",def:"中央アメリカと南アメリカに囲まれた海。コロンブス到達後、スペインなどが植民し、アフリカから奴隷を導入してサトウキビのプランテーションが広がった。",region:"america",cat:"地名・地域",rank:1,course:["tankyu"],related:["コロンブス","サトウキビ","大西洋三角貿易"]},
  {term:"カリンガ",yomi:"カリンガ",def:"インド東部の地方。前3世紀にアショーカ王が征服したが、多くの犠牲者を出したことが王の仏教への帰依のきっかけになったとされる。",year:-261,region:"south",cat:"地名・地域",rank:1,course:["tankyu"],related:["アショーカ王","マウリヤ朝"]},
  {term:"カルカッタ大会",yomi:"カルカッタたいかい",def:"1906年、インド国民会議がカルカッタで開いた大会。ベンガル分割令に反対し、英貨排斥・スワデーシ・スワラージ・民族教育の4綱領を決議した。",year:1906,region:"south",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["インド国民会議","ベンガル分割令","ティラク"]},
  {term:"カルタゴ",yomi:"カルタゴ",def:"フェニキア人が北アフリカに建設した植民市。西地中海の交易で繁栄したが、ローマとのポエニ戦争に敗れ、前146年に滅ぼされた。",year:-814,end:-146,region:"africa",cat:"国家・王朝",rank:3,course:["tankyu"],related:["ポエニ戦争","ハンニバル","フェニキア"]},
  {term:"カルデア人",yomi:"カルデアじん",def:"セム語系の民族。前7世紀に新バビロニア（カルデア）王国をたて、ネブカドネザル2世のときユダ王国を滅ぼしてバビロン捕囚を行った。",year:-626,region:"west",cat:"国家・王朝",rank:1,course:["tankyu"],related:["新バビロニア","バビロン捕囚","4王国分立"]},
  {term:"カルマル同盟",yomi:"カルマルどうめい",def:"1397年、デンマーク・スウェーデン・ノルウェーの3国がデンマーク女王マルグレーテの主導で結んだ同君連合。1523年にスウェーデンが離脱した。",year:1397,end:1523,region:"europe",cat:"条約・宣言",rank:2,course:["tankyu"],related:["デンマーク","スウェーデン","ノルウェー"]},
  {term:"カルロス1世",yomi:"カルロスいっせい",def:"スペイン王。ハプスブルク家出身で、1519年に神聖ローマ皇帝に選ばれカール5世となった。広大な領土を支配し、マゼランの世界周航を援助した。",year:1516,end:1556,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["カール5世","ハプスブルク家","マゼラン"]},
  {term:"カルロヴィッツ条約",yomi:"カルロヴィッツじょうやく",def:"1699年、オスマン帝国がオーストリアなどと結んだ条約。第2次ウィーン包囲の失敗後の戦争の結果、ハンガリーやトランシルヴァニアをオーストリアに割譲した。オスマン帝国が領土を失う転機となった。",year:1699,region:"europe",cat:"条約・宣言",rank:2,course:["tankyu"],related:["ウィーン包囲","オスマン帝国","ハンガリー"]},
  {term:"カルヴァン",yomi:"カルヴァン",def:"フランス出身の宗教改革者。ジュネーヴで神権政治を行い、予定説を説いた。勤労と蓄財を肯定する教えは商工業者に広まり、ゴイセン・ユグノー・ピューリタン・プレスビテリアンとよばれた。",year:1509,end:1564,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["予定説","ジュネーヴ","『キリスト教綱要』","ゴイセン"]},
  {term:"カロリング=ルネサンス",yomi:"カロリング=ルネサンス",def:"カール大帝の宮廷を中心におこったラテン語の文芸復興。イングランドのアルクインらの学者が招かれ、古典の写本や聖職者の教育が進められた。",region:"europe",cat:"文化・学問",rank:2,course:["tankyu"],related:["カール大帝","アルクイン","ラテン語"]},
  {term:"カンネーの戦い",yomi:"カンネーのたたかい",def:"前216年、第2回ポエニ戦争でハンニバルがローマ軍を包囲殲滅した戦い。",year:-216,region:"europe",cat:"事件・戦争",rank:1,course:["tankyu"],related:["ハンニバル","ポエニ戦争","ザマの戦い"]},
  {term:"カンボジア内戦",yomi:"カンボジアないせん",def:"1970年のクーデタから始まったカンボジアの内戦。1975年にポル=ポトの政権が成立し多数の住民を虐殺した。その後のベトナム軍侵攻をへて1991年に和平協定が結ばれた。",year:1970,end:1991,region:"sea",cat:"事件・戦争",rank:2,course:["tankyu"],related:["ポル=ポト","シハヌーク","ベトナム戦争"]},
  {term:"カヴール",yomi:"カヴール",def:"サルデーニャ王国の首相。クリミア戦争に参戦してフランスに接近し、イタリア統一戦争でオーストリアからロンバルディアを獲得した。ガリバルディの南部征服とあわせ1861年のイタリア王国成立を実現した。",year:1852,end:1861,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["サルデーニャ王国","イタリア統一","クリミア戦争","ガリバルディ"]},
  {term:"カージャール朝",yomi:"カージャールちょう",def:"18世紀末にイランにたてられたトルコ系の王朝。ロシアとのトルコマンチャーイ条約で領土と治外法権を失い、英露の進出を受けた。タバコ=ボイコット運動や立憲革命がおこった。",year:1796,end:1925,region:"west",cat:"国家・王朝",rank:3,course:["sogo","tankyu"],related:["イラン立憲革命","トルコマンチャーイ条約","ガージャール朝"]},
  {term:"カーストの否定",yomi:"カーストのひてい",def:"インドの宗教改革者たちが、生まれによる身分差別を否定したこと。15世紀末のナーナクは、カーストを否定し唯一神への信仰を説いてシク教を開いた。",region:"south",cat:"思想・宗教",rank:1,course:["tankyu"],related:["ナーナク","シク教","カースト制度"]},
  {term:"カーネーション革命",yomi:"カーネーションかくめい",def:"1974年、ポルトガルで軍が独裁体制を倒した無血革命。兵士の銃にカーネーションがさされたことから名づけられた。その後アンゴラ・モザンビークなどの植民地が独立した。",year:1974,region:"europe",cat:"事件・戦争",rank:1,course:["tankyu"],related:["サラザール","アンゴラ独立戦争","ポルトガル"]},
  {term:"カーリミー商人",yomi:"カーリミーしょうにん",def:"アイユーブ朝・マムルーク朝の保護のもと、紅海を通じてインド洋と地中海を結ぶ香辛料交易で活躍したムスリム商人。カイロやアレクサンドリアを拠点とした。",region:"west",cat:"経済・社会",rank:2,course:["tankyu"],related:["マムルーク朝","アイユーブ朝","香辛料"]},
  {term:"カール5世",yomi:"カールごせい",def:"神聖ローマ皇帝。スペイン王カルロス1世でもあり、広大な領土を支配した。フランスとイタリア戦争を戦い、ルター派に対しては1555年にアウクスブルクの和議を認めた。",year:1519,end:1556,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["カルロス1世","イタリア戦争","アウクスブルクの和議","ルター"]},
  {term:"カール=マルテル",yomi:"カール=マルテル",def:"フランク王国メロヴィング朝の宮宰。732年、トゥール・ポワティエ間の戦いでイベリア半島から進入したウマイヤ朝の軍を撃退し、キリスト教世界を守ったとされる。",year:714,end:741,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["フランク王国","トゥール・ポワティエ間の戦い","宮宰"]},
  {term:"カールの戴冠",yomi:"カールのたいかん",def:"800年、教皇レオ3世がフランク王カールにローマ皇帝の冠を与えたできごと。西ヨーロッパ世界がビザンツ帝国から自立し、ローマ・ゲルマン・キリスト教が融合した西欧世界が成立した。",year:800,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["カール大帝","レオ3世","西ローマ帝国"]},
  {term:"カール大帝",yomi:"カールたいてい",def:"フランク王国カロリング朝の王。西ヨーロッパの大部分を統一し、各地に伯を置いて支配した。800年に教皇からローマ皇帝の冠を受け、カロリング=ルネサンスを主導した。",year:768,end:814,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["カールの戴冠","カロリング=ルネサンス","フランク王国"]},
  {term:"カーンチー",yomi:"カーンチー",def:"南インド東部の都市。パッラヴァ朝の都として栄え、多くのヒンドゥー教寺院がある。",region:"south",cat:"地名・地域",rank:1,course:["tankyu"],related:["パッラヴァ朝","南インド","ヒンドゥー教"]},
  {term:"ガウタマ=シッダールタ",yomi:"ガウタマ=シッダールタ",def:"仏教の開祖。シャカ族の王子（クシャトリヤ）として生まれ、出家して悟りを開き、ブッダ（覚者）とよばれた。ヴァルナ制を否定し、八正道の実践によって苦しみから解放されると説いた。生没年には諸説ある。",year:-563,end:-483,region:"south",cat:"人物",rank:3,course:["tankyu"],related:["仏教","クシャトリヤ","ヴァルナ制"]},
  {term:"ガオ",yomi:"ガオ",def:"西アフリカのニジェール川中流の都市。ソンガイ王国の都としてサハラ交易で栄えたが、1591年にモロッコのサアド朝の侵攻を受けた。",region:"africa",cat:"地名・地域",rank:1,course:["tankyu"],related:["ソンガイ王国","ニジェール川","サハラ交易"]},
  {term:"ガザン=ハン",yomi:"ガザン=ハン",def:"イル=ハン国第7代の君主。イスラームに改宗してこれを国教とし、宰相ラシード=アッディーンを用いて税制などの改革を行い、国力を回復させた。",year:1295,end:1304,region:"west",cat:"人物",rank:2,course:["tankyu"],related:["イル=ハン国","ラシード=アッディーン","イスラーム化"]},
  {term:"ガザ地区",yomi:"ガザちく",def:"地中海東岸のパレスチナ人居住地域。第3次中東戦争でイスラエルが占領し、オスロ合意後にパレスチナ暫定自治区となった。その後もイスラエルとの衝突が続いている。",region:"west",cat:"地名・地域",rank:2,course:["sogo","tankyu"],related:["パレスチナ問題","PLO","オスロ合意"]},
  {term:"ガズナ朝",yomi:"ガズナちょう",def:"アフガニスタンのガズナを都としたトルコ系イスラーム王朝。マムルーク出身者がたて、たびたび北インドに侵入してイスラーム勢力の進出の先がけとなった。のちゴール朝に滅ぼされた。",year:977,end:1186,region:"south",cat:"国家・王朝",rank:2,course:["tankyu"],related:["ゴール朝","マムルーク","北インド"]},
  {term:"ガリア戦記",yomi:"ガリアせんき",def:"カエサルがみずからのガリア遠征について記した記録。簡潔なラテン語の名文として知られ、当時のケルト人やゲルマン人の社会を伝える史料でもある。",region:"europe",cat:"文化・学問",rank:2,course:["tankyu"],related:["カエサル","ガリア遠征","ラテン文学"]},
  {term:"ガリア遠征",yomi:"ガリアえんせい",def:"前58〜前51年、カエサルが現在のフランスにあたるガリアを征服した遠征。カエサルは軍事的名声と財力を得て、ローマでの権力掌握の基盤とした。",year:-58,end:-51,region:"europe",cat:"事件・戦争",rank:2,course:["tankyu"],related:["カエサル","ガリア戦記","ケルト人"]},
  {term:"ガリバルディ",yomi:"ガリバルディ",def:"イタリア統一運動の指導者。青年イタリアに加わり、1860年に義勇軍の千人隊（赤シャツ隊）を率いて両シチリア王国を征服し、これをサルデーニャ王に献上した。",year:1807,end:1882,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["イタリア統一","青年イタリア","カヴール","両シチリア王国"]},
  {term:"ガリポリの戦い",yomi:"ガリポリのたたかい",def:"第一次世界大戦中の1915年、イギリス・フランスなどがダーダネルス海峡のガリポリ半島に上陸した作戦。オスマン帝国軍が撃退し、指揮官ムスタファ=ケマルが名声を得た。",year:1915,end:1916,region:"west",cat:"事件・戦争",rank:1,course:["tankyu"],related:["第一次世界大戦","ムスタファ=ケマル","オスマン帝国"]},
  {term:"ガリレイ",yomi:"ガリレイ",def:"イタリアの科学者。自作の望遠鏡で天体を観測して地動説を支持し、落体の法則を発見した。地動説を唱えたため宗教裁判にかけられ、その説を捨てることを強いられた。",year:1564,end:1642,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["地動説","『天文対話』","科学革命","コペルニクス"]},
  {term:"ガレオン貿易",yomi:"ガレオンぼうえき",def:"スペインがマニラとメキシコのアカプルコの間で行った貿易。大型帆船ガレオン船でメキシコ銀をアジアに運び、中国の絹や陶磁器と交換した。大量の銀が中国に流入した。",year:1571,end:1815,region:"sea",cat:"経済・社会",rank:3,course:["tankyu"],related:["マニラ","メキシコ銀","スペイン"]},
  {term:"ガンジス川",yomi:"ガンジスがわ",def:"インド北部を流れる大河。前1000年ころからアーリヤ人がこの流域に進出し、のちマガダ国など多くの国家が栄えた。ヒンドゥー教の聖なる川とされる。",region:"south",cat:"地名・地域",rank:2,course:["tankyu"],related:["アーリヤ人","マガダ国","インダス川"]},
  {term:"ガンダーラ",yomi:"ガンダーラ",def:"インド北西部、現在のパキスタン北部の地方。クシャーナ朝の中心地で、ギリシア文化の影響を受けたガンダーラ美術が生まれた。",region:"south",cat:"地名・地域",rank:1,course:["tankyu"],related:["ガンダーラ美術","クシャーナ朝","バクトリア"]},
  {term:"ガンダーラ美術",yomi:"ガンダーラびじゅつ",def:"クシャーナ朝時代にガンダーラ地方で栄えた仏教美術。ヘレニズム文化の影響を受けて仏像が初めてつくられ、中国・日本の仏教美術にも影響を与えた。",region:"south",cat:"文化・学問",rank:3,course:["tankyu"],related:["クシャーナ朝","カニシカ王","ヘレニズム","仏像"]},
  {term:"ガンディー",yomi:"ガンディー",def:"インドの民族運動の指導者。非暴力・不服従（サティヤーグラハ）を唱えて反英運動を指導し、1930年には塩の行進を行った。ヒンドゥー教徒とムスリムの融和を説いたが、1948年に暗殺された。",year:1869,end:1948,region:"south",cat:"人物",rank:3,course:["sogo","tankyu"],related:["サティヤーグラハ","非暴力・不服従","塩の行進","インド国民会議"]},
  {term:"ガージャール朝",yomi:"ガージャールちょう",def:"カージャール朝の別表記。18世紀末から1925年までイランを支配したトルコ系の王朝で、19世紀にはロシア・イギリスの進出を受けた。",year:1796,end:1925,region:"west",cat:"国家・王朝",rank:2,course:["tankyu"],related:["カージャール朝","イラン立憲革命"]},
  {term:"ガーナ独立",yomi:"ガーナどくりつ",def:"1957年、イギリス領黄金海岸がエンクルマの指導でガーナとして独立したこと。サハラ以南のアフリカで最初の黒人国家の独立であり、その後の独立運動をはげました。",year:1957,region:"africa",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["エンクルマ","黄金海岸","アフリカの年"]},
  {term:"ガーナ王国",yomi:"ガーナおうこく",def:"西アフリカのニジェール川上流域に栄えた王国。サハラ砂漠を越えて金と岩塩を交換するサハラ交易で繁栄したが、11世紀にムラービト朝の攻撃を受けて衰退した。",region:"africa",cat:"国家・王朝",rank:3,course:["tankyu"],related:["サハラ交易","ムラービト朝","マリ王国"]},
  {term:"キプチャク=ハン国",yomi:"キプチャク=ハンこく",def:"モンゴルのバトゥが南ロシアにたてた国。ジョチ=ウルスともいう。都はサライで、ロシア諸侯を支配した（タタールのくびき）。15世紀に分裂し、モスクワ大公国が自立した。",year:1243,end:1502,region:"europe",cat:"国家・王朝",rank:3,course:["tankyu"],related:["バトゥ","ワールシュタットの戦い","ジョチ=ウルス","イヴァン3世"]},
  {term:"キプロス問題",yomi:"キプロスもんだい",def:"1960年に独立したキプロスで、ギリシア系住民とトルコ系住民が対立した問題。1974年にトルコ軍が侵攻し、島は南北に分断された。",year:1974,region:"europe",cat:"事件・戦争",rank:1,course:["tankyu"],related:["ギリシア","トルコ","冷戦"]},
  {term:"キャラコ",yomi:"キャラコ",def:"インド産の綿布。17世紀以降イギリス東インド会社によって輸入されてヨーロッパで人気を博し、その国産化をめざして綿工業の技術革新が進み、産業革命につながった。",region:"south",cat:"経済・社会",rank:2,course:["tankyu"],related:["綿織物","産業革命","イギリス東インド会社"]},
  {term:"キュロス2世",yomi:"キュロスにせい",def:"アケメネス朝の創始者。メディア・リディア・新バビロニアを征服してオリエントの大部分を統一した。バビロンに捕囚されていたユダヤ人を解放した。",year:-559,end:-530,region:"west",cat:"人物",rank:3,course:["tankyu"],related:["アケメネス朝","バビロン捕囚","メディア"]},
  {term:"キューバ危機",yomi:"キューバきき",def:"1962年、ソ連がキューバにミサイル基地を建設したことから、米ソが核戦争の危機に直面した事件。ケネディ大統領が海上封鎖を行い、フルシチョフがミサイルを撤去して回避された。翌年ホットラインが設けられた。",year:1962,region:"america",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["ケネディ","フルシチョフ","カストロ","部分的核実験禁止条約"]},
  {term:"キューバ革命",yomi:"キューバかくめい",def:"1959年、カストロらが親米のバティスタ独裁政権を倒した革命。土地改革やアメリカ系企業の国有化を進め、アメリカと断交してソ連に接近し、1961年に社会主義を宣言した。",year:1959,region:"america",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["カストロ","ゲバラ","キューバ危機"]},
  {term:"キリスト教",yomi:"キリストきょう",def:"イエスを救世主（キリスト）と信じる宗教。1世紀にパレスチナでおこり、パウロらの伝道でローマ帝国内に広まった。迫害を受けたが313年に公認され、392年に国教となった。",region:"west",cat:"思想・宗教",rank:3,course:["sogo","tankyu"],related:["イエス","パウロ","ローマ=カトリック教会","ギリシア正教"]},
  {term:"キリスト教の伝来",yomi:"キリストきょうのでんらい",def:"1549年、イエズス会のフランシスコ=ザビエルが鹿児島に上陸し、日本にキリスト教を伝えたこと。キリシタン大名も現れたが、のち江戸幕府は禁教を進めた。",year:1549,region:"east",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ザビエル","イエズス会","「鎖国」"]},
  {term:"キリスト教の国教化",yomi:"キリストきょうのこっきょうか",def:"392年、ローマ皇帝テオドシウスがアタナシウス派のキリスト教を国教とし、ほかの宗教を禁止したこと。313年のミラノ勅令による公認から約80年後のことであった。",year:392,region:"europe",cat:"事件・戦争",rank:2,course:["tankyu"],related:["テオドシウス帝","ミラノ勅令","ローマ帝国"]},
  {term:"キリスト教徒の迫害",yomi:"キリストきょうとのはくがい",def:"ローマ帝国でのキリスト教徒への弾圧。皇帝崇拝を拒んだことなどから、ネロ帝や4世紀初めのディオクレティアヌス帝による大迫害が行われた。313年のミラノ勅令で公認された。",region:"europe",cat:"事件・戦争",rank:2,course:["tankyu"],related:["ネロ","ディオクレティアヌス","ミラノ勅令"]},
  {term:"キルギス",yomi:"キルギス",def:"トルコ系の遊牧民族。840年にウイグルを滅ぼしたが、モンゴル高原に長くとどまらず、その後この地域は遊牧諸勢力の争う場となった。",year:840,region:"inner",cat:"国家・王朝",rank:1,course:["tankyu"],related:["ウイグル","モンゴル高原","トルコ系"]},
  {term:"キルワ",yomi:"キルワ",def:"アフリカ東岸、現在のタンザニアにあった港市。インド洋交易の拠点として栄え、ジンバブエ方面の金を輸出した。イブン=バットゥータも訪れた。",region:"africa",cat:"地名・地域",rank:1,course:["tankyu"],related:["スワヒリ文化","インド洋交易","ムスリム商人"]},
  {term:"キープ",yomi:"キープ",def:"インカ帝国で用いられた結縄（けつじょう）。ひもの結び目の位置や数・色で数量などを記録し、文字の代わりとして統治に用いた。",region:"america",cat:"文化・学問",rank:2,course:["tankyu"],related:["インカ帝国","アンデス文明"]},
  {term:"ギニア湾",yomi:"ギニアわん",def:"アフリカ西岸の湾。沿岸は黄金海岸・奴隷海岸などとよばれ、大西洋の奴隷貿易の拠点となった。",region:"africa",cat:"地名・地域",rank:1,course:["tankyu"],related:["奴隷貿易","黄金海岸","大西洋三角貿易"]},
  {term:"ギリシア=トルコ戦争",yomi:"ギリシア=トルコせんそう",def:"第一次世界大戦後、ギリシアが小アジアに侵攻した戦争。ムスタファ=ケマルの率いるトルコ軍が撃退し、1923年のローザンヌ条約で住民交換が行われた。",year:1919,end:1922,region:"europe",cat:"事件・戦争",rank:1,course:["tankyu"],related:["ムスタファ=ケマル","ローザンヌ条約","トルコ共和国"]},
  {term:"ギリシア人",yomi:"ギリシアじん",def:"インド=ヨーロッパ語系の民族。前8世紀ころからポリスを形成し、地中海・黒海沿岸に植民市を建設した。アレクサンドロス大王の遠征後はバクトリアなど東方にもギリシア人国家が成立した。",region:"europe",cat:"国家・王朝",rank:2,course:["tankyu"],related:["ポリス","ヘレニズム","バクトリア"]},
  {term:"ギリシア正教",yomi:"ギリシアせいきょう",def:"ビザンツ帝国で発達したキリスト教の教派。皇帝が教会を支配する体制をとり、1054年にローマ=カトリック教会と分離した。ロシアや東欧のスラヴ人に広まった。",year:1054,region:"europe",cat:"思想・宗教",rank:3,course:["tankyu"],related:["ビザンツ帝国","ローマ=カトリック教会","キエフ公国"]},
  {term:"ギリシア独立戦争",yomi:"ギリシアどくりつせんそう",def:"1821年、ギリシアがオスマン帝国からの独立をめざしておこした戦争。イギリス・フランス・ロシアが支援し、1829年に独立が認められ、1830年のロンドン会議で国際的に承認された。ウィーン体制をゆるがせた。",year:1821,end:1829,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["ウィーン体制","オスマン帝国","ロマン主義"]},
  {term:"ギリシア語文献の翻訳",yomi:"ギリシアごぶんけんのほんやく",def:"アッバース朝のカリフ、マームーンがバグダードに設けた「知恵の館」などで、ギリシア語の哲学・医学・天文学などの文献をアラビア語に翻訳した事業。イスラーム科学の発展の基礎となった。",region:"west",cat:"文化・学問",rank:1,course:["tankyu"],related:["知恵の館","マームーン","イスラーム科学"]},
  {term:"クシャトリヤ",yomi:"クシャトリヤ",def:"ヴァルナ制の第2の身分で、王侯・武士。ガンジス川流域の国家の成長とともに力を強め、バラモンの権威に反発する仏教やジャイナ教を支持した。",region:"south",cat:"制度・政策",rank:2,course:["tankyu"],related:["ヴァルナ制","バラモン","ガウタマ=シッダールタ"]},
  {term:"クシャーナ朝",yomi:"クシャーナちょう",def:"1世紀に中央アジアから北インドに進出したイラン系の王朝。2世紀のカニシカ王のとき最盛期を迎え、仏教を保護した。東西交易の要地を支配して繁栄した。",region:"south",cat:"国家・王朝",rank:3,course:["tankyu"],related:["カニシカ王","ガンダーラ美術","大乗仏教"]},
  {term:"クシュ王国",yomi:"クシュおうこく",def:"ナイル川上流のヌビアに栄えた黒人王国。前8世紀にエジプトを支配した。のち都をメロエに移して製鉄で栄えたが、4世紀にアクスム王国に滅ぼされた。",region:"africa",cat:"国家・王朝",rank:2,course:["tankyu"],related:["メロエ","エジプト第25王朝","アクスム王国"]},
  {term:"クスコ",yomi:"クスコ",def:"ペルー南部のアンデス高地の都市。インカ帝国の都として栄え、精巧な石組みの建築が残る。1533年にスペインのピサロに占領された。",region:"america",cat:"地名・地域",rank:1,course:["tankyu"],related:["インカ帝国","ピサロ","アンデス文明"]},
  {term:"クテシフォン",yomi:"クテシフォン",def:"ティグリス川東岸の都市。パルティアとササン朝の都として栄えたが、7世紀にアラブ軍に征服された。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["パルティア","ササン朝","ティグリス川"]},
  {term:"クトゥブ=ミナール",yomi:"クトゥブ=ミナール",def:"デリーにあるインド最古のイスラーム建築の塔。奴隷王朝の建国者アイバクが建設を始めた、勝利の記念塔である。",region:"south",cat:"文化・学問",rank:1,course:["tankyu"],related:["奴隷王朝","アイバク","デリー"]},
  {term:"クヌート",yomi:"クヌート",def:"デンマークの王子。1016年にイングランドを征服して王となり、のちデンマーク・ノルウェーの王も兼ね、北海帝国を築いた。",year:1016,end:1035,region:"europe",cat:"人物",rank:1,course:["tankyu"],related:["ノルマン人","デーン人","イングランド"]},
  {term:"クメール人",yomi:"クメールじん",def:"カンボジアの主要民族。6世紀に真臘をたて、扶南を併合した。9世紀以降のアンコール朝のもとで、アンコール=ワットなど大規模な寺院を建設した。",region:"sea",cat:"国家・王朝",rank:2,course:["tankyu"],related:["アンコール朝","真臘","カンボジア"]},
  {term:"クリオーリョ",yomi:"クリオーリョ",def:"ラテンアメリカの植民地生まれの白人。本国生まれの白人（ペニンスラール）に比べ政治的に差別され、19世紀初めの独立運動の中心となった。",region:"america",cat:"経済・社会",rank:3,course:["tankyu"],related:["ラテンアメリカ諸国の独立","シモン=ボリバル","メスティーソ"]},
  {term:"クリミア",yomi:"クリミア",def:"黒海に突き出たクリミア半島とその地域。ソ連時代の1954年にウクライナに移管されたが、2014年にロシアが一方的に併合し、国際的な非難を受けた。",year:2014,region:"europe",cat:"地名・地域",rank:2,course:["sogo","tankyu"],related:["クリミア半島","ウクライナ侵攻","ロシア"]},
  {term:"クリミア半島",yomi:"クリミアはんとう",def:"黒海北岸に突き出た半島。15世紀以降クリミア=ハン国がオスマン帝国の保護下にあったが、1783年にエカチェリーナ2世のロシアが併合した。",year:1783,region:"europe",cat:"地名・地域",rank:1,course:["tankyu"],related:["エカチェリーナ2世","クリミア=ハン国","クリミア戦争"]},
  {term:"クリミア戦争",yomi:"クリミアせんそう",def:"1853〜56年、ロシアとオスマン帝国・イギリス・フランス・サルデーニャの間でおこった戦争。ロシアが敗れて南下政策は挫折し、アレクサンドル2世による農奴解放などの改革が始まった。",year:1853,end:1856,region:"europe",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["ナイティンゲール","パリ条約（1856）","東方問題","アレクサンドル2世"]},
  {term:"クリュニー修道院",yomi:"クリュニーしゅうどういん",def:"910年にフランス東部に創設された修道院。聖職売買や聖職者の妻帯を批判する教会改革運動の中心となり、教皇グレゴリウス7世らの改革に影響を与えた。",year:910,region:"europe",cat:"組織・運動",rank:2,course:["tankyu"],related:["教会改革","グレゴリウス7世","ベネディクト派"]},
  {term:"クリルタイ",yomi:"クリルタイ",def:"モンゴルの有力者の集会。君主の選出や遠征などの重要事項を決定した。1206年のクリルタイでテムジンがチンギス=カンの称号を受けた。",year:1206,region:"inner",cat:"制度・政策",rank:2,course:["tankyu"],related:["チンギス=カン","モンゴル帝国","カアン（大ハーン）"]},
  {term:"クルド人",yomi:"クルドじん",def:"トルコ・イラン・イラクなどにまたがる山岳地帯に住む民族。アイユーブ朝を開いたサラーフ=アッディーンはクルド人である。現在は独自の国家をもたず、各国で少数民族として独立や自治を求めている。",region:"west",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["サラーフ=アッディーン","民族問題","イラク"]},
  {term:"クレイステネス",yomi:"クレイステネス",def:"前6世紀末のアテネの政治家。血縁による4部族を地縁による10部族に再編し、僭主の出現を防ぐ陶片追放（オストラキスモス）を定めて、民主政の基礎を築いた。",year:-508,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["陶片追放","アテネ民主政","僭主"]},
  {term:"クレオパトラ",yomi:"クレオパトラ",def:"プトレマイオス朝エジプトの最後の女王。カエサル、ついでアントニウスと結んだが、アクティウムの海戦で敗れ、前30年に自殺した。プトレマイオス朝はローマに併合された。",year:-51,end:-30,region:"africa",cat:"人物",rank:2,course:["tankyu"],related:["プトレマイオス朝","アクティウムの海戦","カエサル","アントニウス"]},
  {term:"クレルモン宗教会議",yomi:"クレルモンしゅうきょうかいぎ",def:"1095年、教皇ウルバヌス2世がフランスのクレルモンで開いた会議。セルジューク朝の圧迫を受けたビザンツ皇帝の救援要請にこたえ、聖地奪回の十字軍をよびかけた。",year:1095,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["ウルバヌス2世","十字軍","セルジューク朝"]},
  {term:"クローヴィス",yomi:"クローヴィス",def:"フランク王国メロヴィング朝の創始者。481年に即位してフランク人を統一し、496年ころアタナシウス派のキリスト教に改宗して、ローマ人やローマ教会の支持を得た。",year:481,end:511,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["フランク王国","メロヴィング朝","アタナシウス派"]},
  {term:"グスタフ=アドルフ",yomi:"グスタフ=アドルフ",def:"スウェーデン王。三十年戦争に新教側として参戦してドイツで戦い、勝利を重ねたが、1632年のリュッツェンの戦いで戦死した。スウェーデンを北欧の強国とした。",year:1611,end:1632,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["三十年戦争","スウェーデン","プロテスタント"]},
  {term:"グプタ朝",yomi:"グプタちょう",def:"4世紀にチャンドラグプタ1世が建てた北インドの王朝。チャンドラグプタ2世のとき最盛期を迎え、ヒンドゥー教が定着し、サンスクリット文学やグプタ様式の美術が栄えた。エフタルの侵入などで衰えた。",year:320,end:550,region:"south",cat:"国家・王朝",rank:3,course:["tankyu"],related:["チャンドラグプタ2世","グプタ様式","サンスクリット文学","エフタル"]},
  {term:"グプタ様式",yomi:"グプタようしき",def:"グプタ朝時代に完成したインド独自の美術様式。純インド的な仏像が特徴で、アジャンター石窟寺院の壁画などが代表例である。東南アジアや中国・日本にも影響を与えた。",region:"south",cat:"文化・学問",rank:2,course:["tankyu"],related:["グプタ朝","ガンダーラ美術","アジャンター"]},
  {term:"グラスノスチ",yomi:"グラスノスチ",def:"ゴルバチョフが進めた情報公開政策。1986年のチェルノブイリ原発事故を機に本格化し、言論の自由化が進んだ。ペレストロイカとともにソ連の改革の柱となった。",year:1986,region:"europe",cat:"制度・政策",rank:3,course:["sogo","tankyu"],related:["ゴルバチョフ","ペレストロイカ","チェルノブイリ原子力発電所事故"]},
  {term:"グラッドストン",yomi:"グラッドストン",def:"イギリス自由党の政治家。4度首相となり、選挙法改正や教育法制定などの自由主義的改革を進めた。アイルランド自治法案を提出したが成立しなかった。保守党のディズレーリと二大政党制を担った。",year:1868,end:1894,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["自由党","アイルランド自治法","ディズレーリ"]},
  {term:"グラナダ",yomi:"グラナダ",def:"イベリア半島南部の都市。ナスル朝の都としてアルハンブラ宮殿が建てられた。1492年にスペインに攻略され、レコンキスタが完了した。",year:1492,region:"europe",cat:"地名・地域",rank:2,course:["tankyu"],related:["ナスル朝","レコンキスタ","アルハンブラ宮殿"]},
  {term:"グルカ兵",yomi:"グルカへい",def:"ネパール出身の兵士。19世紀初めのイギリスとの戦争後、イギリス軍に雇われるようになり、勇猛さで知られた。",region:"south",cat:"経済・社会",rank:1,course:["tankyu"],related:["ネパール","イギリス","インド大反乱"]},
  {term:"グレート=ゲーム",yomi:"グレート=ゲーム",def:"19世紀から20世紀初めにかけて、中央アジアやアフガニスタンをめぐってイギリスとロシアが繰り広げた勢力争い。1907年の英露協商で一応の決着をみた。",region:"inner",cat:"事件・戦争",rank:2,course:["tankyu"],related:["アフガン戦争","南下政策","英露協商"]},
  {term:"グレートゲーム",yomi:"グレートゲーム",def:"グレート=ゲームの別表記。19世紀にイギリスとロシアが中央アジア・アフガニスタンをめぐって争った覇権争いをさす。",region:"inner",cat:"事件・戦争",rank:1,course:["tankyu"],related:["グレート=ゲーム","アフガン戦争","英露協商"]},
  {term:"グレートブリテン王国",yomi:"グレートブリテンおうこく",def:"1707年、イングランドとスコットランドが合同して成立した王国。アン女王の時代に成立し、1801年にはアイルランドを併合してグレートブリテン=アイルランド連合王国となった。",year:1707,end:1801,region:"europe",cat:"国家・王朝",rank:2,course:["tankyu"],related:["スコットランド","イギリス","アン女王"]},
  {term:"グローバル化",yomi:"グローバルか",def:"ヒト・モノ・カネ・情報が国境をこえて地球規模で移動し、世界の一体化が進むこと。冷戦終結後と情報通信技術の発達により加速したが、格差の拡大などの問題も生んだ。",region:"oceania",cat:"経済・社会",rank:3,course:["sogo","tankyu"],related:["インターネット","WTO","冷戦の終結"]},
  {term:"ケニア独立",yomi:"ケニアどくりつ",def:"1963年、ケニアがイギリスから独立したこと。1950年代のマウマウの反乱をへて独立し、ケニヤッタが初代首相（のち大統領）となった。",year:1963,region:"africa",cat:"事件・戦争",rank:1,course:["tankyu"],related:["ケニヤッタ","マウマウの反乱","イギリス"]},
  {term:"ケニヤッタ",yomi:"ケニヤッタ",def:"ケニアの独立運動の指導者で、1963年の独立後、初代首相・大統領となった。",year:1963,end:1978,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["ケニア独立","アフリカの年"]},
  {term:"ケベック",yomi:"ケベック",def:"カナダ東部の都市・州。1608年にフランスが建設し、ヌーヴェル=フランスの中心となった。1763年にイギリス領となったが、現在もフランス系住民が多い。",year:1608,region:"america",cat:"地名・地域",rank:1,course:["tankyu"],related:["ヌーヴェル=フランス","フレンチ=インディアン戦争","カナダ"]},
  {term:"ケルト人",yomi:"ケルトじん",def:"インド=ヨーロッパ語系の民族。前1000年ころからヨーロッパ中西部に広がったが、ローマやゲルマン人に圧迫され、アイルランドやスコットランドなどにその文化が残った。",region:"europe",cat:"国家・王朝",rank:2,course:["tankyu"],related:["ガリア遠征","アングロ=サクソン人","アイルランド"]},
  {term:"ケープ植民地",yomi:"ケープしょくみんち",def:"アフリカ南端の植民地。1652年にオランダが建設し、ウィーン会議でイギリス領となった。のちローズが首相をつとめ、アフリカ縦断政策の拠点となった。",year:1652,region:"africa",cat:"国家・王朝",rank:2,course:["tankyu"],related:["南アフリカ戦争","ローズ","ウィーン会議"]},
  {term:"ゲティスバーグ演説",yomi:"ゲティスバーグえんぜつ",def:"1863年、南北戦争の激戦地ゲティスバーグでリンカン大統領が行った演説。「人民の、人民による、人民のための政治」という言葉で民主主義の理念を示した。",year:1863,region:"america",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["リンカン","南北戦争","奴隷解放宣言"]},
  {term:"ゲバラ",yomi:"ゲバラ",def:"アルゼンチン出身の革命家。カストロとともにキューバ革命を指導した。のちボリビアでゲリラ闘争中に捕らえられ、殺害された。",year:1928,end:1967,region:"america",cat:"人物",rank:1,course:["tankyu"],related:["カストロ","キューバ革命"]},
  {term:"ゲルニカ",yomi:"ゲルニカ",def:"スペイン北部の町。1937年、スペイン内戦でフランコ側を支援するドイツ空軍の無差別爆撃を受けた。ピカソはこれに抗議して大作「ゲルニカ」を描いた。",year:1937,region:"europe",cat:"文化・学問",rank:2,course:["sogo","tankyu"],related:["スペイン内戦","ピカソ","フランコ"]},
  {term:"ゲルマン人の大移動",yomi:"ゲルマンじんのだいいどう",def:"375年、フン人に圧迫された西ゴート人がドナウ川を渡ってローマ帝国領内に移動したことに始まる、ゲルマン人の大規模な移動。各地にゲルマン人の国家が建てられ、西ローマ帝国が滅ぶ一因となった。",year:375,end:568,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["フン人","西ゴート人","オドアケル","西ローマ帝国"]},
  {term:"コシューシコ",yomi:"コシューシコ",def:"ポーランドの軍人。アメリカ独立戦争に義勇兵として参加した。1794年、ポーランド分割に抵抗して蜂起したが、ロシア・プロイセン軍に敗れ、翌年ポーランドは消滅した。",year:1794,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["ポーランド分割","アメリカ独立戦争"]},
  {term:"コソヴォ",yomi:"コソヴォ",def:"バルカン半島の地域で、アルバニア系住民が多数を占める。セルビア人にとっても歴史的な土地であり、紛争をへて2008年にセルビアからの独立を宣言した。",year:2008,region:"europe",cat:"地名・地域",rank:1,course:["tankyu"],related:["コソヴォ紛争","セルビア","アルバニア人"]},
  {term:"コソヴォの戦い",yomi:"コソヴォのたたかい",def:"1389年、オスマン帝国がセルビアなどバルカン諸国の連合軍を破った戦い。オスマン帝国のバルカン半島支配が進んだ。",year:1389,region:"europe",cat:"事件・戦争",rank:1,course:["tankyu"],related:["オスマン帝国","セルビア","バルカン半島"]},
  {term:"コソヴォ紛争",yomi:"コソヴォふんそう",def:"ユーゴスラヴィア（セルビア）のコソヴォ自治州で、独立を求めるアルバニア系住民とセルビア政府が衝突した紛争。1999年にNATOがセルビアを空爆した。",year:1998,end:1999,region:"europe",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["NATO空爆","ユーゴスラヴィア","民族問題"]},
  {term:"コペルニクス",yomi:"コペルニクス",def:"ポーランドの天文学者。天動説に疑問をもち、太陽を中心とする地動説を唱えた。その説はのちケプラー・ガリレイによって発展させられた。",year:1473,end:1543,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["地動説","ガリレイ","ケプラー"]},
  {term:"コミンフォルム除名",yomi:"コミンフォルムじょめい",def:"1948年、ソ連と対立したユーゴスラヴィアがコミンフォルムから除名されたこと。ティトーはその後、独自の社会主義路線と非同盟外交を進めた。",year:1948,region:"europe",cat:"事件・戦争",rank:1,course:["tankyu"],related:["ティトー","ユーゴスラヴィア","スターリン"]},
  {term:"コリントス同盟",yomi:"コリントスどうめい",def:"前337年、カイロネイアの戦いの翌年に、マケドニアのフィリッポス2世がスパルタを除くギリシアのポリスを結集させた同盟。ヘラス同盟ともいう。",year:-337,region:"europe",cat:"組織・運動",rank:1,course:["tankyu"],related:["カイロネイアの戦い","マケドニア","フィリッポス2世"]},
  {term:"コルテス",yomi:"コルテス",def:"スペインの征服者（コンキスタドール）。1519年にメキシコに上陸し、先住民の対立を利用して1521年にアステカ王国を征服した。その地はスペイン領ヌエバ=エスパーニャとなった。",year:1519,end:1521,region:"america",cat:"人物",rank:3,course:["tankyu"],related:["アステカ王国","コンキスタドール","ピサロ"]},
  {term:"コルドバ",yomi:"コルドバ",def:"イベリア半島南部の都市。後ウマイヤ朝の都として繁栄し、10世紀には大モスクや図書館をもつ西方イスラーム世界の学問・文化の中心となった。",year:756,region:"europe",cat:"地名・地域",rank:2,course:["tankyu"],related:["後ウマイヤ朝","イブン=ルシュド","イベリア半島"]},
  {term:"コルベール",yomi:"コルベール",def:"ルイ14世の財務総監。重商主義政策を進め、王立マニュファクチュアの設立、関税の引き上げ、東インド会社の再建などを行って国家財政の強化をはかった。",year:1665,end:1683,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["ルイ14世","重商主義","フランス東インド会社"]},
  {term:"コルホーズ",yomi:"コルホーズ",def:"ソ連の集団農場。スターリンが第1次五か年計画で農業集団化を強行して普及した。国営農場ソフホーズとともにソ連の農業の中心となった。",year:1929,region:"europe",cat:"制度・政策",rank:2,course:["tankyu"],related:["スターリン","五か年計画","ソフホーズ"]},
  {term:"コロナトゥス",yomi:"コロナトゥス",def:"ローマ帝国末期に広まった小作制。没落した農民などがコロヌスとして大土地所有者の土地を耕作した。コンスタンティヌス帝はコロヌスの移動を禁じ、中世の農奴の起源の一つとされる。",region:"europe",cat:"制度・政策",rank:2,course:["tankyu"],related:["コロヌス","ラティフンディア","封建制度"]},
  {term:"コロンブス",yomi:"コロンブス",def:"ジェノヴァ出身の航海者。地球球体説を信じて大西洋を西に向かい、スペイン女王イサベルの援助を受けて1492年にサンサルバドル島に到達した。アメリカ大陸到達の端緒を開いた。",year:1492,end:1504,region:"america",cat:"人物",rank:3,course:["tankyu"],related:["イサベル","サンサルバドル島","大航海時代","コロンブス交換"]},
  {term:"コロンブス交換",yomi:"コロンブスこうかん",def:"コロンブス以後、アメリカ大陸とヨーロッパ・アフリカ・アジアの間で起こった動植物や病原体の交換。ジャガイモ・トウモロコシがユーラシアに伝わり、天然痘などがアメリカ先住民の人口を激減させた。",region:"america",cat:"経済・社会",rank:2,course:["tankyu"],related:["コロンブス","ジャガイモ","天然痘"]},
  {term:"コンキスタドール",yomi:"コンキスタドール",def:"スペイン語で「征服者」の意。16世紀にアメリカ大陸に渡り、アステカ王国を征服したコルテスやインカ帝国を征服したピサロなどをさす。",region:"america",cat:"経済・社会",rank:2,course:["tankyu"],related:["コルテス","ピサロ","アステカ王国"]},
  {term:"コンゴ",yomi:"コンゴ",def:"アフリカ中部のコンゴ川流域の地域。スタンリーの探検後ベルギー王レオポルド2世が私有地とし、これをめぐってベルリン会議が開かれた。1960年に独立した。",region:"africa",cat:"地名・地域",rank:2,course:["tankyu"],related:["スタンリー","レオポルド2世","ベルリン会議（1884〜85）"]},
  {term:"コンゴ動乱",yomi:"コンゴどうらん",def:"1960年のコンゴ独立直後におこった内乱。旧宗主国ベルギーの介入やカタンガ州の分離独立をめぐって混乱し、国連軍が派遣された。",year:1960,end:1965,region:"africa",cat:"事件・戦争",rank:2,course:["tankyu"],related:["アフリカの年","カタンガ","国際連合"]},
  {term:"コンスタンツ公会議",yomi:"コンスタンツこうかいぎ",def:"1414〜18年に神聖ローマ皇帝のよびかけで開かれた宗教会議。教会大分裂（大シスマ）を終わらせ、ウィクリフとフスを異端とし、フスを火刑に処した。",year:1414,end:1418,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["教会大分裂","フス","ウィクリフ"]},
  {term:"コンスタンティヌス",yomi:"コンスタンティヌス",def:"ローマ皇帝。313年のミラノ勅令でキリスト教を公認し、325年にニケーア公会議を開いた。330年にビザンティウムに遷都してコンスタンティノープルと改称し、専制君主政を強化した。",year:306,end:337,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["ミラノ勅令","ニケーア公会議","コンスタンティノープル","コロナトゥス"]},
  {term:"コンスタンティノープル",yomi:"コンスタンティノープル",def:"330年、コンスタンティヌス帝がビザンティウムに遷都して改称した都市。ビザンツ帝国の都として東西交易で繁栄したが、1453年にオスマン帝国に攻略され、イスタンブルとよばれるようになった。",year:330,end:1453,region:"europe",cat:"地名・地域",rank:3,course:["tankyu"],related:["コンスタンティヌス","ビザンツ帝国","イスタンブル"]},
  {term:"コンスタンティノープル攻略",yomi:"コンスタンティノープルこうりゃく",def:"1453年、オスマン帝国のメフメト2世がコンスタンティノープルを攻略したできごと。ビザンツ帝国は滅亡し、この都市はオスマン帝国の首都となった。",year:1453,region:"europe",cat:"事件・戦争",rank:2,course:["tankyu"],related:["メフメト2世","ビザンツ帝国","オスマン帝国"]},
  {term:"コンバウン朝",yomi:"コンバウンちょう",def:"1752年にアラウンパヤーがビルマにたてた王朝。1767年にタイのアユタヤ朝を滅ぼしたが、3度のイギリス=ビルマ戦争に敗れ、1885年に滅亡した。",year:1752,end:1885,region:"sea",cat:"国家・王朝",rank:2,course:["tankyu"],related:["アラウンパヤー","アユタヤ朝の滅亡","イギリス=ビルマ戦争"]},
  {term:"コンヤ",yomi:"コンヤ",def:"アナトリア中部の都市。ルーム=セルジューク朝の都として栄えた。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["ルーム=セルジューク朝","アナトリア"]},
  {term:"コーヒー",yomi:"コーヒー",def:"アフリカ原産の作物で、イスラーム世界を経てヨーロッパに広まった。19世紀にはブラジルなど中南米やジャワでプランテーション栽培が拡大し、モノカルチャー経済の形成につながった。",region:"america",cat:"経済・社会",rank:1,course:["tankyu"],related:["プランテーション","モノカルチャー経済","強制栽培制度"]},
  {term:"コーラン（クルアーン）",yomi:"コーラン（クルアーン）",def:"イスラームの聖典。ムハンマドが受けた神の啓示をまとめたもので、アラビア語で記された。信仰だけでなく、生活全般を規定するイスラーム法の根本とされる。",region:"west",cat:"文化・学問",rank:3,course:["tankyu"],related:["ムハンマド","イスラーム","イスラーム法"]},
  {term:"コール",yomi:"コール",def:"西ドイツの首相。1990年のドイツ統一を実現し、統一ドイツの初代首相となった。EUの成立にも力を尽くした。",year:1982,end:1998,region:"europe",cat:"人物",rank:1,course:["sogo","tankyu"],related:["ドイツ統一","西ドイツ","EU"]},
  {term:"ゴ=ディン=ジエム",yomi:"ゴ=ディン=ジエム",def:"ベトナム共和国（南ベトナム）の初代大統領。アメリカの支援を受けて独裁政治を行い、仏教徒などの反発を受けた。1963年のクーデタで殺害された。",year:1955,end:1963,region:"sea",cat:"人物",rank:1,course:["tankyu"],related:["ベトナム共和国","南ベトナム解放民族戦線","ベトナム戦争"]},
  {term:"ゴア",yomi:"ゴア",def:"インド西海岸の都市。1510年にポルトガルが占領し、アジア貿易とカトリック布教の拠点とした。1961年にインドに併合された。",year:1510,region:"south",cat:"地名・地域",rank:2,course:["tankyu"],related:["ポルトガル","ザビエル","インド航路"]},
  {term:"ゴイセン",yomi:"ゴイセン",def:"ネーデルラントのカルヴァン派の呼び名で、「乞食」の意。スペインのフェリペ2世の支配とカトリック強制に抵抗し、オランダ独立戦争の中心勢力となった。",region:"europe",cat:"思想・宗教",rank:2,course:["tankyu"],related:["カルヴァン","オランダ独立戦争"]},
  {term:"ゴム",yomi:"ゴム",def:"ゴムの木からとれる樹液を原料とする工業原料。19世紀末に自動車の普及で需要が高まり、イギリス領マレー半島などでインド人労働者を用いたプランテーションが広がった。",region:"sea",cat:"経済・社会",rank:1,course:["tankyu"],related:["すず","マレー連合州","プランテーション"]},
  {term:"ゴルバチョフ",yomi:"ゴルバチョフ",def:"ソ連共産党書記長・大統領。ペレストロイカ（改革）とグラスノスチ（情報公開）を進め、新思考外交で冷戦の終結に貢献した。1991年のソ連解体で辞任した。",year:1985,end:1991,region:"europe",cat:"人物",rank:3,course:["sogo","tankyu"],related:["ペレストロイカ","グラスノスチ","マルタ会談","INF全廃条約"]},
  {term:"ゴードン",yomi:"ゴードン",def:"イギリスの軍人。中国では常勝軍を率いて太平天国の鎮圧に協力した。スーダンでマフディー運動の鎮圧にあたったが、1885年にハルツームで戦死した。",year:1885,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["太平天国","マフディー運動","常勝軍"]},
  {term:"ゴールコンダ",yomi:"ゴールコンダ",def:"インドのデカン地方にあった王国とその城塞都市。ダイヤモンドの産地として知られたが、1687年にアウラングゼーブのムガル帝国に併合された。",region:"south",cat:"地名・地域",rank:1,course:["tankyu"],related:["デカン=スルタン朝","アウラングゼーブ"]},
  {term:"ゴールドラッシュ",yomi:"ゴールドラッシュ",def:"金鉱の発見により人々が殺到したこと。1848年のカリフォルニアの金鉱発見で多くの移民が西部に流入した。オーストラリアでも19世紀半ばにおこった。",year:1848,region:"america",cat:"経済・社会",rank:2,course:["tankyu"],related:["カリフォルニア","西部開拓","移民"]},
  {term:"ゴール朝",yomi:"ゴールちょう",def:"アフガニスタンのゴール地方におこったイスラーム王朝。ガズナ朝を倒して北インドに進出し、その部将アイバクがデリーで奴隷王朝を開いた。",year:1148,end:1215,region:"south",cat:"国家・王朝",rank:1,course:["tankyu"],related:["ガズナ朝","奴隷王朝","アイバク"]},
  {term:"サアド朝",yomi:"サアドちょう",def:"16世紀にモロッコにたてられたイスラーム王朝。サハラ交易の利益を求めて1591年にソンガイ王国を攻撃し、これを崩壊させた。",year:1549,end:1659,region:"africa",cat:"国家・王朝",rank:1,course:["tankyu"],related:["ソンガイ王国","モロッコ","サハラ交易"]},
  {term:"サイクス=ピコ協定",yomi:"サイクス=ピコきょうてい",def:"1916年、イギリス・フランス・ロシアがオスマン帝国領の分割を取り決めた秘密協定。アラブ人に独立を約束したフセイン・マクマホン協定などと矛盾し、戦後の中東問題の原因となった。",year:1916,region:"west",cat:"条約・宣言",rank:3,course:["sogo","tankyu"],related:["フセイン・マクマホン協定","バルフォア宣言","委任統治"]},
  {term:"サイゴン陥落",yomi:"サイゴンかんらく",def:"1975年、北ベトナム軍と解放戦線が南ベトナムの首都サイゴンを占領したできごと。ベトナム戦争が終結し、翌年ベトナム社会主義共和国が成立した。サイゴンはホーチミン市と改称された。",year:1975,region:"sea",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ベトナム戦争","ベトナム共和国","ベトナム社会主義共和国"]},
  {term:"サイス",yomi:"サイス",def:"ナイル川デルタの都市。アッシリアの支配から自立したエジプト第26王朝（サイス朝）の都となったが、前525年にアケメネス朝に征服された。",year:-664,end:-525,region:"africa",cat:"地名・地域",rank:1,course:["tankyu"],related:["エジプト","アッシリア","アケメネス朝"]},
  {term:"サウジアラビア",yomi:"サウジアラビア",def:"1932年、イブン=サウードがアラビア半島の大部分を統一して成立した王国。ワッハーブ派を国家の基盤とし、石油の発見後は世界有数の産油国としてOPECの中心となった。",year:1932,region:"west",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["イブン=サウード","ワッハーブ派","OPEC"]},
  {term:"サウード家",yomi:"サウードけ",def:"アラビア半島中部の豪族。18世紀にワッハーブ派と結んでワッハーブ王国をたて、20世紀にはイブン=サウードがサウジアラビア王国を建国した。",year:1744,region:"west",cat:"国家・王朝",rank:1,course:["tankyu"],related:["ワッハーブ派","イブン=サウード","サウジアラビア"]},
  {term:"ササン朝",yomi:"ササンちょう",def:"224年、アルダシール1世がパルティアを倒してたてたイランの王朝。ゾロアスター教を国教とし、ローマ・ビザンツ帝国と抗争した。6世紀のホスロー1世のとき最盛期を迎え、651年にイスラーム勢力に滅ぼされた。",year:224,end:651,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["アルダシール1世","シャープール1世","ホスロー1世","ゾロアスター教"]},
  {term:"サダト",yomi:"サダト",def:"ナセルの後継のエジプト大統領。1973年に第4次中東戦争をおこしたのち、アメリカに接近し、1979年にイスラエルと平和条約を結んだ。1981年に暗殺された。",year:1970,end:1981,region:"west",cat:"人物",rank:2,course:["sogo","tankyu"],related:["エジプト=イスラエル平和条約","第4次中東戦争","ナセル"]},
  {term:"サダム=フセイン",yomi:"サダム=フセイン",def:"イラクの大統領。イラン=イラク戦争をおこし、1990年にはクウェートに侵攻して湾岸戦争をまねいた。2003年のイラク戦争で政権は崩壊し、のちに処刑された。",year:1979,end:2003,region:"west",cat:"人物",rank:2,course:["sogo","tankyu"],related:["イラン=イラク戦争","湾岸戦争","イラク戦争"]},
  {term:"サッチャー",yomi:"サッチャー",def:"イギリスの首相（保守党）。国有企業の民営化や規制緩和など新自由主義的な改革を進め、「小さな政府」をめざした。1982年のフォークランド戦争でアルゼンチンに勝利した。",year:1979,end:1990,region:"europe",cat:"人物",rank:2,course:["sogo","tankyu"],related:["新自由主義","フォークランド戦争","レーガン"]},
  {term:"サティヤーグラハ",yomi:"サティヤーグラハ",def:"ガンディーが唱えた運動の理念で、「真理の把握」の意。非暴力・不服従によって不正な支配に抵抗するもので、インドの反英独立運動の基本となった。",region:"south",cat:"思想・宗教",rank:2,course:["sogo","tankyu"],related:["ガンディー","非暴力・不服従","塩の行進"]},
  {term:"サトウキビ",yomi:"サトウキビ",def:"砂糖の原料となる作物。16世紀以降、ブラジルやカリブ海地域で黒人奴隷を用いたプランテーションで大規模に栽培され、大西洋三角貿易の主要な商品となった。",region:"america",cat:"経済・社会",rank:2,course:["tankyu"],related:["プランテーション","大西洋三角貿易","奴隷貿易"]},
  {term:"サトラップ",yomi:"サトラップ",def:"アケメネス朝の知事。ダレイオス1世は全国を約20の州に分けてサトラップを置き、「王の目」「王の耳」とよばれる監察官に監視させて中央集権体制を整えた。",region:"west",cat:"制度・政策",rank:3,course:["tankyu"],related:["アケメネス朝","ダレイオス1世","「王の目」「王の耳」"]},
  {term:"サハラ交易",yomi:"サハラこうえき",def:"サハラ砂漠を越えて行われた交易。ラクダを用いたムスリム商人が北アフリカの岩塩と西アフリカの金を交換し、ガーナ・マリ・ソンガイなどの王国が繁栄した。",region:"africa",cat:"経済・社会",rank:3,course:["tankyu"],related:["ガーナ王国","マリ王国","ソンガイ王国","トンブクトゥ"]},
  {term:"サファヴィー朝",yomi:"サファヴィーちょう",def:"1501年、イスマーイール1世がイランにたてた王朝。シーア派（十二イマーム派）を国教とし、君主はシャーの称号を用いた。アッバース1世のとき最盛期を迎えた。",year:1501,end:1736,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["イスマーイール1世","アッバース1世","イスファハーン","シーア派"]},
  {term:"サマルカンド",yomi:"サマルカンド",def:"中央アジアのオアシス都市。古くからソグド人の交易の拠点として栄えた。14世紀にティムール朝の都となり、壮麗なモスクやウルグ=ベクの天文台が建てられた。",region:"inner",cat:"地名・地域",rank:3,course:["tankyu"],related:["ティムール朝","ソグド人","オアシス都市"]},
  {term:"サミット",yomi:"サミット",def:"主要国首脳会議。1975年、石油危機後の世界経済の問題に対処するため、フランスの提唱で始まった。のちロシアも加わったが、2014年のクリミア併合で参加資格を停止された。",year:1975,region:"europe",cat:"組織・運動",rank:2,course:["sogo","tankyu"],related:["石油危機","主要国首脳会議","グローバル化"]},
  {term:"サモリ=トゥーレ",yomi:"サモリ=トゥーレ",def:"西アフリカの指導者。イスラーム国家をたてて19世紀末にフランスの侵略に抵抗したが、1898年に捕らえられた。",year:1870,end:1898,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["アフリカ分割","フランス","西アフリカ"]},
  {term:"サライ",yomi:"サライ",def:"ヴォルガ川下流に建設されたキプチャク=ハン国の都。東西交易の中継地として栄えた。",region:"europe",cat:"地名・地域",rank:1,course:["tankyu"],related:["キプチャク=ハン国","バトゥ","ヴォルガ川"]},
  {term:"サライェヴォ事件",yomi:"サライェヴォじけん",def:"1914年6月、ボスニアの都サライェヴォで、オーストリアの帝位継承者夫妻がセルビア人青年に暗殺された事件。オーストリアがセルビアに宣戦し、第一次世界大戦の発端となった。",year:1914,region:"europe",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["第一次世界大戦","パン=スラヴ主義","ボスニア・ヘルツェゴヴィナ"]},
  {term:"サラザール",yomi:"サラザール",def:"ポルトガルの首相。1932年から独裁的な「新国家」体制をしき、植民地支配を維持しようとした。体制はカーネーション革命で崩壊した。",year:1932,end:1968,region:"europe",cat:"人物",rank:1,course:["tankyu"],related:["カーネーション革命","ポルトガル","独裁"]},
  {term:"サラミスの海戦",yomi:"サラミスのかいせん",def:"前480年、ペルシア戦争でアテネのテミストクレスの率いるギリシア海軍がペルシア海軍を破った海戦。三段櫂船の漕ぎ手となった無産市民の発言力が高まった。",year:-480,region:"europe",cat:"事件・戦争",rank:3,course:["tankyu"],related:["ペルシア戦争","テミストクレス","三段櫂船"]},
  {term:"サラーフ=アッディーン",yomi:"サラーフ=アッディーン",def:"アイユーブ朝の創始者。クルド人の出身で、ファーティマ朝を倒してエジプトにスンナ派を復興した。1187年にイェルサレムを奪回し、第3回十字軍と戦った。サラディンとも表記される。",year:1169,end:1193,region:"west",cat:"人物",rank:3,course:["tankyu"],related:["アイユーブ朝","イェルサレム奪回","十字軍","ファーティマ朝"]},
  {term:"サルゴン1世",yomi:"サルゴンいっせい",def:"アッカド人の王。前24世紀ころシュメールの都市国家を征服し、メソポタミアを初めて統一した。その支配はシリアやイラン高原西部にまで及んだ。",year:-2350,region:"west",cat:"人物",rank:2,course:["tankyu"],related:["アッカド人","シュメール人","メソポタミア"]},
  {term:"サルデス",yomi:"サルデス",def:"小アジア西部の都市。リディア王国の都で、アケメネス朝のもとでは首都スサとを結ぶ「王の道」の起点となった。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["リディア","「王の道」","アケメネス朝"]},
  {term:"サルデーニャ王国",yomi:"サルデーニャおうこく",def:"サヴォイア家が北イタリアのピエモンテとサルデーニャ島を支配した王国。19世紀にカヴールのもとで近代化を進め、イタリア統一の中心となり、1861年にイタリア王国となった。",year:1720,end:1861,region:"europe",cat:"国家・王朝",rank:3,course:["tankyu"],related:["カヴール","イタリア統一","ヴィットーリオ=エマヌエーレ2世"]},
  {term:"サルフの戦い",yomi:"サルフのたたかい",def:"1619年、ヌルハチの率いる後金（のちの清）が、遼東に侵攻した明の大軍をサルフで破った戦い。後金は遼東に勢力を拡大し、明は守勢に立たされた。",year:1619,region:"east",cat:"事件・戦争",rank:2,course:["tankyu"],related:["ヌルハチ","後金","明"]},
  {term:"サレカット=イスラーム",yomi:"サレカット=イスラーム",def:"1911年ころオランダ領東インドで結成されたイスラーム同盟。当初は商人の相互扶助組織であったが、民族運動の大衆組織に発展した。",year:1911,region:"sea",cat:"組織・運動",rank:2,course:["tankyu"],related:["オランダ領東インド","インドネシア国民党","民族運動"]},
  {term:"サン=ジェルマン条約",yomi:"サン=ジェルマンじょうやく",def:"1919年、連合国がオーストリアと結んだ講和条約。オーストリア=ハンガリー帝国は解体され、ハンガリー・チェコスロヴァキアなどの独立が承認された。ドイツとの合併は禁止された。",year:1919,region:"europe",cat:"条約・宣言",rank:2,course:["sogo","tankyu"],related:["パリ講和会議","ヴェルサイユ体制","オーストリア"]},
  {term:"サン=ステファノ条約",yomi:"サン=ステファノじょうやく",def:"1878年、ロシア=トルコ戦争の講和条約。ブルガリアを大国としてロシアの保護下に置いたため、イギリス・オーストリアが反対し、ベルリン会議で修正された。",year:1878,region:"europe",cat:"条約・宣言",rank:3,course:["tankyu"],related:["ロシア=トルコ戦争","ベルリン会議（1878）","ブルガリア"]},
  {term:"サン=マルティン",yomi:"サン=マルティン",def:"アルゼンチン出身の独立運動の指導者。アルゼンチンの独立に貢献したのち、アンデス山脈を越えて進軍し、チリ・ペルーの独立を指導した。",year:1778,end:1850,region:"america",cat:"人物",rank:2,course:["tankyu"],related:["シモン=ボリバル","クリオーリョ","ラテンアメリカ諸国の独立"]},
  {term:"サンクトペテルブルク",yomi:"サンクトペテルブルク",def:"ピョートル1世が北方戦争中にバルト海沿岸に建設したロシアの新都。「西欧への窓」とよばれた。1914年にペトログラード、1924年にレニングラードと改称され、1991年に旧名に戻った。",year:1703,region:"europe",cat:"地名・地域",rank:2,course:["tankyu"],related:["ピョートル1世","北方戦争","ロシア革命"]},
  {term:"サンゴール",yomi:"サンゴール",def:"セネガルの詩人・政治家で、1960年の独立後の初代大統領。黒人文化の価値を主張するネグリチュード運動の中心人物でもあった。",year:1960,end:1980,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["セネガル","アフリカの年","ネグリチュード"]},
  {term:"サンサルバドル島",yomi:"サンサルバドルとう",def:"カリブ海、バハマ諸島の島。1492年、コロンブスが大西洋横断ののち最初に到達した島で、スペイン語で「聖なる救世主」を意味する名をつけた。",year:1492,region:"america",cat:"地名・地域",rank:2,course:["tankyu"],related:["コロンブス","カリブ海","大航海時代"]},
  {term:"サンスクリット文学",yomi:"サンスクリットぶんがく",def:"サンスクリット語で書かれた文学。グプタ朝のもとで公用語化されて栄え、カーリダーサの戯曲『シャクンタラー』や二大叙事詩『マハーバーラタ』『ラーマーヤナ』が完成した。",region:"south",cat:"文化・学問",rank:2,course:["tankyu"],related:["グプタ朝","カーリダーサ","『マハーバーラタ』"]},
  {term:"サンスーシ宮殿",yomi:"サンスーシきゅうでん",def:"プロイセンのフリードリヒ2世がポツダムに建てた宮殿。ロココ様式の代表的建築で、ヴォルテールも招かれた。",year:1747,region:"europe",cat:"文化・学問",rank:1,course:["tankyu"],related:["フリードリヒ2世","ロココ様式","ヴォルテール"]},
  {term:"サンディニスタ",yomi:"サンディニスタ",def:"ニカラグアの左翼の民族解放戦線。1979年に親米独裁政権を倒して革命政権をたてたが、アメリカのレーガン政権が反政府勢力を支援して内戦となった。",year:1979,region:"america",cat:"組織・運動",rank:1,course:["tankyu"],related:["ニカラグア","冷戦","レーガン"]},
  {term:"サンフランシスコ平和条約",yomi:"サンフランシスコへいわじょうやく",def:"1951年、日本と48か国が調印した第二次世界大戦の講和条約。翌年発効し、日本は独立を回復した。ソ連などは調印せず、同時に日米安全保障条約が結ばれた。",year:1951,region:"east",cat:"条約・宣言",rank:3,course:["sogo"],related:["吉田茂","日米安全保障条約","GHQ"]},
  {term:"サヴォイア家",yomi:"サヴォイアけ",def:"北イタリアからフランス東南部にかけての地域を支配した家系。サルデーニャ王国の王家となり、のちイタリア王国の王家となったが、1946年に王制は廃止された。",region:"europe",cat:"国家・王朝",rank:1,course:["tankyu"],related:["サルデーニャ王国","イタリア王国"]},
  {term:"サーマーン朝",yomi:"サーマーンちょう",def:"中央アジアにたてられたイラン系イスラーム王朝。都ブハラを中心に繁栄し、ペルシア語文学が復興した。トルコ人奴隷をマムルークとして輸出した。999年にカラハン朝に滅ぼされた。",year:875,end:999,region:"inner",cat:"国家・王朝",rank:2,course:["tankyu"],related:["イラン=イスラーム文化","ブハラ","カラハン朝"]},
  {term:"ザマの戦い",yomi:"ザマのたたかい",def:"前202年、第2回ポエニ戦争で、ローマのスキピオがカルタゴのハンニバルを北アフリカのザマで破った戦い。ローマは西地中海の覇権を確立した。",year:-202,region:"africa",cat:"事件・戦争",rank:2,course:["tankyu"],related:["ハンニバル","スキピオ","ポエニ戦争"]},
  {term:"ザミンダーリー制",yomi:"ザミンダーリーせい",def:"イギリス東インド会社がベンガルなどで導入した徴税制度。ザミンダール（地主・領主層）に土地の所有権を認め、彼らから地税を徴収した。",year:1793,region:"south",cat:"制度・政策",rank:2,course:["tankyu"],related:["イギリス東インド会社","ライヤットワーリー制"]},
  {term:"ザンジバル",yomi:"ザンジバル",def:"東アフリカ沖の島。インド洋交易の拠点で、19世紀にはオマーンの支配下で奴隷や香辛料の取引で栄えた。1964年にタンガニーカと合併してタンザニアとなった。",region:"africa",cat:"地名・地域",rank:1,course:["tankyu"],related:["スワヒリ文化","オマーン","インド洋交易"]},
  {term:"シェイクスピア",yomi:"シェイクスピア",def:"イギリス=ルネサンスを代表する劇作家。エリザベス1世の時代に活躍し、『ハムレット』『ヴェニスの商人』など多くの悲劇・喜劇を書いた。",year:1564,end:1616,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["エリザベス1世","ルネサンス","『ハムレット』"]},
  {term:"シオニズム",yomi:"シオニズム",def:"ユダヤ人がパレスチナに民族的郷土を建設しようとする運動。ドレフュス事件を機にヘルツルが提唱し、19世紀末に本格化した。1948年のイスラエル建国につながった。",year:1897,region:"west",cat:"思想・宗教",rank:3,course:["sogo","tankyu"],related:["パレスチナ問題","バルフォア宣言","ドレフュス事件"]},
  {term:"シク戦争",yomi:"シクせんそう",def:"1845〜49年、イギリス東インド会社とパンジャーブ地方のシク王国の間でおこった戦争。イギリスが勝利してパンジャーブを併合した。",year:1845,end:1849,region:"south",cat:"事件・戦争",rank:1,course:["tankyu"],related:["シク王国","イギリス東インド会社","パンジャーブ"]},
  {term:"シク教",yomi:"シクきょう",def:"16世紀初めにナーナクが始めた宗教。ヒンドゥー教にイスラームの影響を受けて、偶像崇拝やカーストを否定した。パンジャーブ地方に広まった。",region:"south",cat:"思想・宗教",rank:3,course:["tankyu"],related:["ナーナク","カーストの否定","インド=イスラーム文化"]},
  {term:"シク教徒",yomi:"シクきょうと",def:"シク教を信じる人々。ムガル帝国のアウラングゼーブの圧迫に抵抗し、19世紀前半にはパンジャーブにシク王国をたてた。",region:"south",cat:"思想・宗教",rank:1,course:["tankyu"],related:["シク教","アウラングゼーブ","シク戦争"]},
  {term:"システィーナ礼拝堂",yomi:"システィーナれいはいどう",def:"ヴァチカン宮殿内の礼拝堂。ミケランジェロが天井画「天地創造」と祭壇画「最後の審判」を描いた。",region:"europe",cat:"文化・学問",rank:1,course:["tankyu"],related:["ミケランジェロ","ルネサンス","ローマ教皇"]},
  {term:"シチリア",yomi:"シチリア",def:"イタリア半島南の地中海最大の島。ローマ最初の属州となり、のちイスラーム勢力やノルマン人に支配され、多様な文化が融合した。",region:"europe",cat:"地名・地域",rank:1,course:["tankyu"],related:["ポエニ戦争","両シチリア王国","ノルマン人"]},
  {term:"シチリアの晩鐘",yomi:"シチリアのばんしょう",def:"1282年、シチリア島でフランスのアンジュー家の支配に対しておこった反乱。以後シチリアはアラゴン王国の支配下に入った。",year:1282,region:"europe",cat:"事件・戦争",rank:1,course:["tankyu"],related:["アラゴン王国","シチリア","両シチリア王国"]},
  {term:"シドン",yomi:"シドン",def:"地中海東岸のフェニキア人の都市国家。ティルスとともに地中海交易で栄えた。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["フェニキア人","ティルス","アルファベット"]},
  {term:"シハヌーク",yomi:"シハヌーク",def:"カンボジアの国王・元首。1953年にフランスからの独立を達成し、中立政策をとった。1970年のクーデタで失脚したが、内戦終結後の1993年に国王に復位した。",year:1953,end:2004,region:"sea",cat:"人物",rank:1,course:["tankyu"],related:["カンボジア","カンボジア内戦","ポル=ポト"]},
  {term:"シベリア出兵",yomi:"シベリアしゅっぺい",def:"1918年、ロシア革命への干渉のため、日本・アメリカなどがシベリアに出兵したこと。日本は最も多くの兵を送り、他国の撤退後も1922年まで駐留を続けた。",year:1918,end:1922,region:"east",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ロシア革命","対ソ干渉戦争","米騒動"]},
  {term:"シモン=ボリバル",yomi:"シモン=ボリバル",def:"ベネズエラ出身のクリオーリョで、南アメリカ北部の独立運動の指導者。ベネズエラ・コロンビア・ボリビアなどの独立を実現し、大コロンビア共和国の大統領となった。",year:1783,end:1830,region:"america",cat:"人物",rank:3,course:["tankyu"],related:["クリオーリョ","ラテンアメリカ諸国の独立","サン=マルティン"]},
  {term:"シャイバーニー朝",yomi:"シャイバーニーちょう",def:"16世紀初め、ウズベクがティムール朝を倒して中央アジアにたてた王朝。ブハラを都とした。",year:1500,end:1599,region:"inner",cat:"国家・王朝",rank:1,course:["tankyu"],related:["ウズベク","ティムール朝","ブハラ=ハン国"]},
  {term:"シャカ",yomi:"シャカ",def:"南部アフリカのズールー王国の建国者。軍事改革を行って周辺を統合し、強大な国家を築いた。",year:1816,end:1828,region:"africa",cat:"人物",rank:1,course:["tankyu"],related:["ズールー王国","南アフリカ"]},
  {term:"シャルル7世",yomi:"シャルルしちせい",def:"フランス王。ジャンヌ=ダルクの活躍によりランスで戴冠し、百年戦争に勝利してカレーを除くフランスからイギリス軍を追い出した。常備軍を設けて王権を強化した。",year:1422,end:1461,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["ジャンヌ=ダルク","百年戦争","オルレアン"]},
  {term:"シャー",yomi:"シャー",def:"イランの王の称号。サファヴィー朝のイスマーイール1世はイラン古来のこの称号を用い、民族意識を高めた。",region:"west",cat:"制度・政策",rank:1,course:["tankyu"],related:["サファヴィー朝","イスマーイール1世","イラン"]},
  {term:"シャープビル事件",yomi:"シャープビルじけん",def:"1960年、南アフリカのシャープビルで、パス法に抗議する黒人のデモに警官隊が発砲し、多数の死者が出た事件。ANCは非合法化され、武装闘争に転じた。",year:1960,region:"africa",cat:"事件・戦争",rank:1,course:["tankyu"],related:["アパルトヘイト","マンデラ","アフリカ民族会議"]},
  {term:"シャープール1世",yomi:"シャープールいっせい",def:"ササン朝第2代の王。西方ではローマ軍を破って皇帝ウァレリアヌスを捕虜とし、東方ではクシャーナ朝を破って領土を広げ、ササン朝の基礎を固めた。",year:241,end:272,region:"west",cat:"人物",rank:2,course:["tankyu"],related:["ササン朝","ローマ帝国","アルダシール1世"]},
  {term:"シュトレーゼマン",yomi:"シュトレーゼマン",def:"ヴァイマル共和国の首相・外相。1923年にレンテンマルクを発行してインフレーションを収束させた。外相としてロカルノ条約を結び、ドイツの国際連盟加盟を実現した。",year:1923,end:1929,region:"europe",cat:"人物",rank:2,course:["sogo","tankyu"],related:["ヴァイマル共和国","ロカルノ条約","インフレーション"]},
  {term:"シュメール人",yomi:"シュメールじん",def:"メソポタミア南部に最古の都市文明を築いた民族。前3000年ころからウル・ウルクなどの都市国家をつくり、くさび形文字や60進法を生み出した。神殿としてジッグラトを建てた。",year:-3000,region:"west",cat:"国家・王朝",rank:3,course:["tankyu"],related:["くさび形文字","ウル","ジッグラト","都市国家"]},
  {term:"シュリーフェン=プラン",yomi:"シュリーフェン=プラン",def:"ドイツの参謀総長シュリーフェンが立てた二正面作戦の計画。中立国ベルギーを通過してフランスを短期で破り、のちロシアと戦う構想だったが、1914年のマルヌの戦いで失敗した。",year:1914,region:"europe",cat:"制度・政策",rank:1,course:["tankyu"],related:["第一次世界大戦","ベルギー","マルヌの戦い"]},
  {term:"シュリーヴィジャヤ",yomi:"シュリーヴィジャヤ",def:"7世紀にスマトラ島のパレンバンを中心に成立した港市国家。マラッカ海峡を支配して交易で栄え、大乗仏教が盛んで、唐の義浄も滞在した。",region:"sea",cat:"国家・王朝",rank:3,course:["tankyu"],related:["義浄","港市国家","大乗仏教","チョーラ朝"]},
  {term:"シュリーヴィジャヤ遠征",yomi:"シュリーヴィジャヤえんせい",def:"11世紀前半、南インドのチョーラ朝がマラッカ海峡の交易支配をめざしてシュリーヴィジャヤを攻撃した遠征。シュリーヴィジャヤの衰退の一因となった。",year:1025,region:"south",cat:"事件・戦争",rank:1,course:["tankyu"],related:["チョーラ朝","シュリーヴィジャヤ","インド洋交易"]},
  {term:"シュレジエン",yomi:"シュレジエン",def:"中欧のオーデル川上流域の地方。鉱産資源に富み、オーストリア継承戦争でプロイセンが獲得し、七年戦争で確保した。現在はおもにポーランド領。",year:1740,region:"europe",cat:"地名・地域",rank:2,course:["tankyu"],related:["オーストリア継承戦争","七年戦争","フリードリヒ2世"]},
  {term:"シリア内戦",yomi:"シリアないせん",def:"2011年の「アラブの春」を機に、シリアでアサド政権と反政府勢力の間で始まった内戦。諸外国の介入や過激派組織ISの台頭で長期化し、大量の難民が発生した。",year:2011,region:"west",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["アラブの春","難民","IS"]},
  {term:"シルクロード",yomi:"シルクロード",def:"ユーラシア大陸の東西を結んだ交易路の総称。とくに中央アジアのオアシスを結ぶ道をさし、中国の絹が西方に運ばれたことから名づけられた。漢の張騫の派遣を機に東西交流が活発になった。",region:"inner",cat:"地名・地域",rank:3,course:["tankyu"],related:["オアシスの道","張騫","ソグド人"]},
  {term:"シン=フェイン党",yomi:"シン=フェインとう",def:"1905年に結成されたアイルランドの民族主義政党。「われら自身」の意。完全独立を求め、1916年のイースター蜂起後に支持を広げ、アイルランド自由国の成立を導いた。",year:1905,region:"europe",cat:"組織・運動",rank:2,course:["sogo","tankyu"],related:["アイルランド自由国","アイルランド自治法","イースター蜂起"]},
  {term:"シンガポール",yomi:"シンガポール",def:"マレー半島南端の島・都市国家。1819年にラッフルズが建設し、海峡植民地の中心として中継貿易で栄えた。1965年にマレーシアから分離独立し、アジアNIESの一つとなった。",year:1819,region:"sea",cat:"国家・王朝",rank:2,course:["sogo","tankyu"],related:["ラッフルズ","海峡植民地","アジアNIES"]},
  {term:"シンガポール分離",yomi:"シンガポールぶんり",def:"1965年、マレー系を優遇する中央政府と対立した中国系住民の多いシンガポールが、マレーシアから分離独立したこと。リー=クアンユーが首相となった。",year:1965,region:"sea",cat:"事件・戦争",rank:1,course:["tankyu"],related:["シンガポール","マレーシア","リー=クアンユー"]},
  {term:"シンハラ人",yomi:"シンハラじん",def:"スリランカの多数派民族。上座部仏教を信仰する。独立後はヒンドゥー教徒のタミル人との対立が深まり、長い内戦となった。",region:"south",cat:"国家・王朝",rank:1,course:["tankyu"],related:["スリランカ","上座部仏教","タミル人"]},
  {term:"シヴァージー",yomi:"シヴァージー",def:"マラーター王国の建国者。ヒンドゥー教徒の国家の復興をかかげてムガル帝国のアウラングゼーブに抵抗し、1674年にデカン地方で王国をたてた。",year:1674,end:1680,region:"south",cat:"人物",rank:2,course:["tankyu"],related:["マラーター王国","アウラングゼーブ","ヒンドゥー教"]},
  {term:"シーア派",yomi:"シーアは",def:"第4代カリフのアリーとその子孫のみをムスリムの正統な指導者（イマーム）と認める一派。ファーティマ朝やサファヴィー朝はシーア派を奉じ、現在はイランなどに多い。",region:"west",cat:"思想・宗教",rank:3,course:["tankyu"],related:["アリー","スンナ派","サファヴィー朝","イラン革命"]},
  {term:"シーラーズ",yomi:"シーラーズ",def:"イラン南西部の都市。18世紀のザンド朝の都となった。ペルシア語の詩人サーディーやハーフィズを生んだことでも知られる。",region:"west",cat:"地名・地域",rank:1,course:["tankyu"],related:["ザンド朝","イラン","ペルシア語"]},
  {term:"ジェノサイド",yomi:"ジェノサイド",def:"特定の民族や集団を意図的に抹殺しようとする集団殺害。ナチスのホロコーストを受けて国際的に犯罪とされた。1994年のルワンダ内戦では多数派フツ人がツチ人などを大量に殺害した。",year:1994,region:"africa",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ルワンダ内戦","ホロコースト","民族問題"]},
  {term:"ジェントリ",yomi:"ジェントリ",def:"イギリスの郷紳（地主層）。貴族の下に位置し、治安判事などとして地方行政を担った。修道院解散で土地を得て力を強め、議会や革命で大きな役割を果たした。",region:"europe",cat:"経済・社会",rank:3,course:["tankyu"],related:["ヘンリ8世","治安判事","ピューリタン革命"]},
  {term:"ジズヤ",yomi:"ジズヤ",def:"イスラーム国家が非ムスリムの庇護民に課した人頭税。ウマイヤ朝では改宗者にも課されたが、アッバース朝では非ムスリムだけが負担した。インドのムガル帝国でも問題となった。",region:"west",cat:"制度・政策",rank:3,course:["tankyu"],related:["ハラージュ","イスラーム帝国","ジズヤの廃止"]},
  {term:"ジズヤの廃止",yomi:"ジズヤのはいし",def:"1564年、ムガル帝国のアクバルが非ムスリムへの人頭税（ジズヤ）を廃止したこと。ヒンドゥー教徒との融和をはかり、帝国の支配を安定させた。",year:1564,region:"south",cat:"制度・政策",rank:2,course:["tankyu"],related:["アクバル","ムガル帝国","ジズヤの復活"]},
  {term:"ジズヤの復活",yomi:"ジズヤのふっかつ",def:"1679年、ムガル帝国のアウラングゼーブがジズヤを復活させたこと。ヒンドゥー教徒などの反発を招き、ラージプートやマラーターの反乱の一因となった。",year:1679,region:"south",cat:"制度・政策",rank:2,course:["tankyu"],related:["アウラングゼーブ","ムガル帝国","ジズヤの廃止"]},
  {term:"ジッグラト",yomi:"ジッグラト",def:"メソポタミアの都市国家に建てられた聖塔。日干しれんがを階段状に積み上げ、頂上に守護神をまつる神殿を置いた。ウルのものがよく知られる。",region:"west",cat:"文化・学問",rank:2,course:["tankyu"],related:["シュメール人","ウル","メソポタミア"]},
  {term:"ジハード",yomi:"ジハード",def:"アラビア語で「努力」の意で、イスラームの信仰のための戦いをさす。正統カリフ時代の大征服は聖戦（ジハード）として進められた。",region:"west",cat:"思想・宗教",rank:2,course:["tankyu"],related:["イスラーム","正統カリフ","ウンマ"]},
  {term:"ジパング",yomi:"ジパング",def:"マルコ=ポーロの『世界の記述』で紹介された日本の呼び名。黄金の国として描かれ、コロンブスらの航海を刺激した。",region:"east",cat:"地名・地域",rank:1,course:["tankyu"],related:["マルコ=ポーロ","『世界の記述（東方見聞録）』","コロンブス"]},
  {term:"ジャイナ教",yomi:"ジャイナきょう",def:"前6世紀ころヴァルダマーナが開いた宗教。バラモンの権威とヴァルナ制を否定し、不殺生と厳しい苦行を説いた。商人層に多く信仰された。",region:"south",cat:"思想・宗教",rank:3,course:["tankyu"],related:["ヴァルダマーナ","仏教","ヴァルナ制"]},
  {term:"ジャガー信仰",yomi:"ジャガーしんこう",def:"メソアメリカやアンデスの古代文明に見られる、ジャガーを神聖視する信仰。オルメカ文明やチャビン文化の美術に表現された。",region:"america",cat:"思想・宗教",rank:1,course:["tankyu"],related:["オルメカ文明","チャビン文化","メソアメリカ文明"]},
  {term:"ジャクソニアン=デモクラシー",yomi:"ジャクソニアン=デモクラシー",def:"アメリカのジャクソン大統領の時代の民主主義の発展。白人男性普通選挙の普及などが進んだが、先住民強制移住法で先住民を西方に追いやった。",year:1829,end:1837,region:"america",cat:"制度・政策",rank:2,course:["tankyu"],related:["ジャクソン","先住民強制移住法","民主党"]},
  {term:"ジャコバン派",yomi:"ジャコバンは",def:"フランス革命期の急進的共和派。山岳派ともいう。1793年にジロンド派を追放して権力を握り、ロベスピエールを中心に恐怖政治を行ったが、1794年のテルミドールの反動で倒れた。",year:1793,end:1794,region:"europe",cat:"組織・運動",rank:3,course:["sogo","tankyu"],related:["ロベスピエール","恐怖政治","ジロンド派"]},
  {term:"ジャムチ",yomi:"ジャムチ",def:"モンゴル帝国の駅伝制。主要道路に一定の距離ごとに駅を設け、牌符をもつ使節や官吏に馬や食料を提供した。広大な帝国の交通・通信を支えた。",region:"inner",cat:"制度・政策",rank:2,course:["tankyu"],related:["モンゴル帝国","オゴデイ","牌符"]},
  {term:"ジャワ島",yomi:"ジャワとう",def:"インドネシアの中心となる島。シャイレンドラ朝のボロブドゥール、マジャパヒト王国などが栄えた。17世紀以降オランダが支配し、強制栽培制度が行われた。",region:"sea",cat:"地名・地域",rank:2,course:["tankyu"],related:["シャイレンドラ朝","マタラム王国","オランダ東インド会社"]},
  {term:"ジャンク船",yomi:"ジャンクせん",def:"中国で発達した木造帆船。宋代以降、羅針盤を用いて南シナ海やインド洋に進出し、中国商人の海上交易を担った。明の鄭和の艦隊にも用いられた。",region:"east",cat:"経済・社会",rank:2,course:["tankyu"],related:["ダウ船","宋","海の道"]},
  {term:"ジャンヌ=ダルク",yomi:"ジャンヌ=ダルク",def:"フランスの農民の娘。神のお告げを受けたとして百年戦争に参加し、1429年にオルレアンを解放してシャルル7世の戴冠を実現した。のちイギリス軍に捕らえられ、火刑に処された。",year:1429,end:1431,region:"europe",cat:"人物",rank:3,course:["tankyu"],related:["百年戦争","シャルル7世","オルレアン"]},
  {term:"ジュネーヴ",yomi:"ジュネーヴ",def:"スイス西部の都市。16世紀にカルヴァンが神権政治を行い、宗教改革の中心地となった。20世紀には国際連盟の本部が置かれ、多くの国際会議が開かれた。",region:"europe",cat:"地名・地域",rank:2,course:["tankyu"],related:["カルヴァン","国際連盟","ジュネーヴ休戦協定"]},
  {term:"ジュネーヴ休戦協定",yomi:"ジュネーヴきゅうせんきょうてい",def:"1954年、インドシナ戦争を終わらせた協定。北緯17度線を暫定軍事境界線としてベトナムを南北に分け、2年後に統一選挙を行うことを定めたが、アメリカは調印しなかった。",year:1954,region:"sea",cat:"条約・宣言",rank:3,course:["sogo","tankyu"],related:["インドシナ戦争","ベトナム","ディエンビエンフー"]},
  {term:"ジュネーヴ協定",yomi:"ジュネーヴきょうてい",def:"インドシナ戦争の講和として1954年に結ばれたジュネーヴ休戦協定のこと。フランス軍はインドシナから撤退し、ベトナムは北緯17度線で南北に分断された。",year:1954,region:"sea",cat:"条約・宣言",rank:1,course:["sogo","tankyu"],related:["ジュネーヴ休戦協定","ホー=チ=ミン","インドシナ戦争"]},
  {term:"ジュンガル",yomi:"ジュンガル",def:"17世紀にオイラトの一部族が中心となってたてた遊牧国家。清と争ったが、18世紀半ばに乾隆帝によって滅ぼされ、その地は新疆として清の領土となった。",region:"inner",cat:"国家・王朝",rank:2,course:["tankyu"],related:["オイラト","康熙帝","乾隆帝"]},
  {term:"ジョチ=ウルス",yomi:"ジョチ=ウルス",def:"チンギス=カンの長子ジョチの子孫が受けついだ国。キプチャク=ハン国ともいい、バトゥの西征ののち南ロシアの草原を中心に成立した。",year:1243,end:1502,region:"europe",cat:"国家・王朝",rank:2,course:["tankyu"],related:["キプチャク=ハン国","バトゥ","サライ"]},
  {term:"ジロンド派",yomi:"ジロンドは",def:"フランス革命期の穏健共和派。商工業者の利益を代表し、1792年に対外戦争を始めたが、1793年にジャコバン派に追放された。",year:1792,end:1793,region:"europe",cat:"組織・運動",rank:2,course:["tankyu"],related:["ジャコバン派","フランス革命","国民公会"]},
  {term:"ジンナー",yomi:"ジンナー",def:"全インド=ムスリム連盟の指導者。ヒンドゥー教徒中心の国民会議派と対立し、ムスリム国家の分離独立を主張した。1947年のパキスタン独立後に初代総督となった。",year:1947,end:1948,region:"south",cat:"人物",rank:2,course:["sogo","tankyu"],related:["全インド=ムスリム連盟","パキスタン","インド・パキスタンの分離独立"]},
  {term:"スウェーデン",yomi:"スウェーデン",def:"スカンディナヴィア半島の国。1523年にカルマル同盟から独立し、17世紀にはグスタフ=アドルフのもとでバルト海の覇権をにぎった。北方戦争でロシアに敗れて地位を失った。",region:"europe",cat:"国家・王朝",rank:1,course:["tankyu"],related:["グスタフ=アドルフ","北方戦争","カルマル同盟"]},
  {term:"スエズ戦争",yomi:"スエズせんそう",def:"1956年、エジプトのスエズ運河国有化に対し、イギリス・フランス・イスラエルが出兵した戦争。第2次中東戦争ともいう。国際的非難を受けて3国は撤退し、ナセルの威信が高まった。",year:1956,region:"west",cat:"事件・戦争",rank:3,course:["sogo","tankyu"],related:["ナセル","スエズ運河国有化","第2次中東戦争"]},
  {term:"スエズ戦争（第2次中東戦争）",yomi:"スエズせんそう（だいにじちゅうとうせんそう）",def:"スエズ戦争と同じ。1956年、エジプトのスエズ運河国有化に反発した英仏とイスラエルがエジプトに出兵したが、米ソや国連の圧力で撤退した。",year:1956,region:"west",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["スエズ戦争","ナセル","スエズ運河国有化"]},
  {term:"スエズ運河",yomi:"スエズうんが",def:"地中海と紅海を結ぶ運河。フランス人レセップスが建設し1869年に開通した。1875年にイギリスのディズレーリが運河会社の株を買収し、イギリスのインドへの道となった。",year:1869,region:"africa",cat:"経済・社会",rank:3,course:["sogo","tankyu"],related:["レセップス","ディズレーリ","スエズ運河国有化"]},
  {term:"スエズ運河国有化",yomi:"スエズうんがこくゆうか",def:"1956年、エジプトのナセル大統領がスエズ運河の国有化を宣言したこと。アスワン=ハイダム建設への英米の援助撤回に対抗したもので、スエズ戦争をまねいた。",year:1956,region:"africa",cat:"事件・戦争",rank:2,course:["sogo","tankyu"],related:["ナセル","スエズ戦争","アスワン=ハイダム"]},
  {term:"スカルノ",yomi:"スカルノ",def:"インドネシアの民族運動の指導者で初代大統領。インドネシア国民党を結成し、1945年に独立を宣言した。1955年のアジア=アフリカ会議を主催したが、九・三〇事件後に失脚した。",year:1945,end:1967,region:"sea",cat:"人物",rank:3,course:["sogo","tankyu"],related:["インドネシア独立","アジア=アフリカ会議","九・三〇事件"]},
  {term:"スキタイ",yomi:"スキタイ",def:"前7世紀ころから黒海北岸の草原地帯で活動したイラン系の騎馬遊牧民。動物文様を特色とする金属器文化を生み、その文化は東方の遊牧民にも影響を与えた。",region:"inner",cat:"国家・王朝",rank:2,course:["tankyu"],related:["騎馬遊牧民","動物文様","匈奴"]},
  {term:"スキピオ",yomi:"スキピオ",def:"古代ローマの将軍。第2回ポエニ戦争で北アフリカに渡ってカルタゴ本国をつき、前202年のザマの戦いでハンニバルを破った。大スキピオとよばれる。",year:-236,end:-183,region:"europe",cat:"人物",rank:2,course:["tankyu"],related:["ザマの戦い","ハンニバル","ポエニ戦争"]}
]);
